create or replace function plantlab_platform.has_permission(
  p_module_code text,
  p_permission text,
  p_site_id uuid default null,
  p_company_id bigint default null
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from plantlab_platform.user_role_assignments ura
    join plantlab_platform.role_definitions rd on rd.id = ura.role_id
    join plantlab_platform.module_registry mr on mr.id = rd.module_id
    where ura.user_id = auth.uid()
      and ura.is_active
      and rd.is_active
      and mr.is_active
      and mr.module_code = upper(p_module_code)
      and ura.valid_from <= now()
      and (ura.valid_until is null or ura.valid_until > now())
      and (ura.site_id is null or ura.site_id = p_site_id)
      and (ura.company_id is null or ura.company_id = p_company_id)
      and (rd.permissions ? '*' or rd.permissions ? p_permission)
  );
$$;

create or replace function plantlab_platform.enforce_status_transition()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_requires_reason boolean;
  v_reason text;
begin
  if old.status is not distinct from new.status then
    return new;
  end if;

  select st.requires_reason
    into v_requires_reason
  from plantlab_platform.status_transitions st
  where st.module_code = tg_argv[0]
    and st.entity_type = tg_argv[1]
    and st.from_status = old.status
    and st.to_status = new.status
    and st.is_active;

  if not found then
    raise exception 'Invalid status transition for %.%: % -> %',
      tg_argv[0], tg_argv[1], old.status, new.status
      using errcode = '23514';
  end if;

  if v_requires_reason then
    v_reason := coalesce(
      nullif(to_jsonb(new) ->> 'status_reason', ''),
      nullif(current_setting('app.status_reason', true), '')
    );

    if v_reason is null then
      raise exception 'Transition %.% % -> % requires a reason',
        tg_argv[0], tg_argv[1], old.status, new.status
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

