insert into plantlab_platform.module_registry (module_code, module_name, description)
values
  ('PLANT', 'Plant', 'Plant process planning, inspection, tests, and sample dispatch.'),
  ('LAB', 'Laboratory', 'Generic laboratory request, testing, result, and approval.'),
  ('GOT_FET', 'GOT/FET', 'Grow-out and field emergence testing; may request additional Lab tests.'),
  ('KC', 'KC', 'Inspection and reference data source.'),
  ('COMPFEED', 'CompFeed', 'Upstream product, production, and Lot source.'),
  ('WAREHOUSE', 'Warehouse', 'Stock and storage reference source.'),
  ('CC', 'Customer Care', 'Complaint and customer-care source.'),
  ('PLATFORM', 'Platform', 'Cross-module administration and authorization.')
on conflict (module_code) do update
set module_name = excluded.module_name,
    description = excluded.description,
    is_active = true,
    updated_at = now();

