create table plantlab_core.lots (
  id uuid primary key default gen_random_uuid(),
  canonical_lot_code text not null default (
    'LOT-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20))
  ),
  lot_code text not null,
  product_id bigint not null references plantlab_master.products(id) on delete restrict,
  company_id bigint not null references plantlab_master.companies(id) on delete restrict,
  plant_site_id uuid references plantlab_master.sites(id) on delete restrict,
  source_lot_code text,
  quantity numeric,
  unit_code text,
  received_at timestamptz,
  manufactured_at date,
  expired_at date,
  status text not null default 'REGISTERED',
  status_reason text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  updated_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint lots_canonical_code_uq unique (canonical_lot_code),
  constraint lots_quantity_ck check (quantity is null or quantity >= 0),
  constraint lots_dates_ck check (
    expired_at is null or manufactured_at is null or expired_at >= manufactured_at
  ),
  constraint lots_status_ck check (
    status in ('REGISTERED', 'IN_PROCESS', 'HOLD', 'RELEASED', 'REJECTED', 'CLOSED')
  ),
  constraint lots_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

comment on column plantlab_core.lots.lot_code is
  'Business/display Lot number. It is intentionally not globally unique; canonical_lot_code is the system identity.';

create index lots_lot_code_idx on plantlab_core.lots (lot_code);
create index lots_product_idx on plantlab_core.lots (product_id);
create index lots_company_idx on plantlab_core.lots (company_id) where company_id is not null;
create index lots_site_idx on plantlab_core.lots (plant_site_id) where plant_site_id is not null;
create index lots_status_idx on plantlab_core.lots (status, plant_site_id);

create table plantlab_core.lot_sources (
  id uuid primary key default gen_random_uuid(),
  lot_id uuid not null references plantlab_core.lots(id) on delete cascade,
  source_system text not null,
  source_entity text not null,
  source_record_key text not null,
  source_lot_code text,
