  constraint lot_sources_source_uq unique (source_system, source_entity, source_record_key),
  constraint lot_sources_quantity_ck check (quantity is null or quantity >= 0),
  constraint lot_sources_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index lot_sources_lot_idx on plantlab_core.lot_sources (lot_id);
create index lot_sources_lot_code_idx on plantlab_core.lot_sources (source_lot_code)
  where source_lot_code is not null;

create table plantlab_core.lot_lineage (
  id uuid primary key default gen_random_uuid(),
  parent_lot_id uuid not null references plantlab_core.lots(id) on delete restrict,
  child_lot_id uuid not null references plantlab_core.lots(id) on delete restrict,
  relationship_type text not null,
  quantity numeric,
  unit_code text,
  occurred_at timestamptz not null default now(),
  reason text,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint lot_lineage_relation_uq unique (parent_lot_id, child_lot_id, relationship_type),
