create index lot_lineage_child_idx on plantlab_core.lot_lineage (child_lot_id);

create table plantlab_core.samples (
  id uuid primary key default gen_random_uuid(),
  sample_code text not null default (
    'SMP-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20))
  ),
  lot_id uuid not null references plantlab_core.lots(id) on delete restrict,
  sample_type text not null,
