    sample_type in (
      'PROCESS', 'GROWER', 'LAB_REQUEST', 'GOT', 'COMPLAINT', 'GUARD', 'MARKET', 'RETAINED'
    )
  ),
  constraint samples_source_module_ck check (
    source_module in ('PLANT', 'LAB', 'GOT_FET', 'KC', 'COMPFEED', 'WAREHOUSE', 'CC', 'MANUAL')
  ),
  constraint samples_quantity_ck check (quantity is null or quantity > 0),
  constraint samples_status_ck check (
    status in ('PREPARED', 'SENT', 'RECEIVED', 'HOLD', 'REJECTED', 'CONSUMED', 'ARCHIVED')
  ),
  constraint samples_timeline_ck check (
    received_at is null or sent_at is null or received_at >= sent_at
  ),
  constraint samples_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index samples_lot_idx on plantlab_core.samples (lot_id);
create index samples_status_idx on plantlab_core.samples (status, source_site_id);
create index samples_source_module_idx on plantlab_core.samples (source_module, created_at desc);

