create table plantlab_audit.workflow_history (
  id bigint generated always as identity primary key,
  module_code text not null references plantlab_platform.module_registry(module_code) on update cascade,
  entity_type text not null,
  entity_key text not null,
  from_status text,
  to_status text,
  action text not null,
  reason text,
  changed_by uuid references plantlab_platform.identities(id) on delete set null,
  changed_at timestamptz not null default now(),
  correlation_key text,
  context jsonb not null default '{}'::jsonb,
  constraint workflow_history_status_change_ck check (
    action <> 'STATUS_CHANGE'
    or (from_status is distinct from to_status and to_status is not null)
  ),
  constraint workflow_history_context_object_ck check (jsonb_typeof(context) = 'object')
);

create index workflow_history_entity_idx
  on plantlab_audit.workflow_history (module_code, entity_type, entity_key, changed_at desc);
create index workflow_history_actor_idx
  on plantlab_audit.workflow_history (changed_by, changed_at desc)
  where changed_by is not null;

create table plantlab_audit.outbox_events (
  id uuid primary key default gen_random_uuid(),
  event_type text not null,
  aggregate_type text not null,
  aggregate_key text not null,
  module_code text not null references plantlab_platform.module_registry(module_code) on update cascade,
  payload jsonb not null,
  idempotency_key text not null,
  status text not null default 'PENDING',
  attempt_count integer not null default 0,
  available_at timestamptz not null default now(),
  locked_at timestamptz,
  locked_by text,
  processed_at timestamptz,
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint outbox_events_idempotency_uq unique (idempotency_key),
  constraint outbox_events_payload_object_ck check (jsonb_typeof(payload) = 'object'),
  constraint outbox_events_status_ck check (
    status in ('PENDING', 'PROCESSING', 'PROCESSED', 'FAILED', 'DEAD_LETTER')
  ),
  constraint outbox_events_attempt_count_ck check (attempt_count >= 0),
  constraint outbox_events_processed_ck check (
    (status = 'PROCESSED' and processed_at is not null)
    or status <> 'PROCESSED'
  )
);

create index outbox_events_dispatch_idx
  on plantlab_audit.outbox_events (available_at, created_at)
  where status in ('PENDING', 'FAILED');
create index outbox_events_aggregate_idx
  on plantlab_audit.outbox_events (aggregate_type, aggregate_key, created_at desc);

create table plantlab_audit.integration_attempts (
  id bigint generated always as identity primary key,
  outbox_event_id uuid references plantlab_audit.outbox_events(id) on delete set null,
  target_system text not null,
  attempt_number integer not null,
  status text not null,
  http_status integer,
  request_payload jsonb,
  response_payload jsonb,
  error_message text,
  started_at timestamptz not null default now(),
  finished_at timestamptz not null default now(),
  constraint integration_attempts_event_attempt_uq
    unique (outbox_event_id, target_system, attempt_number),
  constraint integration_attempts_number_ck check (attempt_number > 0),
  constraint integration_attempts_status_ck check (
    status in ('SUCCEEDED', 'FAILED', 'TIMED_OUT', 'SKIPPED')
  ),
  constraint integration_attempts_timeline_ck check (
    finished_at >= started_at
  )
);

create index integration_attempts_target_idx
  on plantlab_audit.integration_attempts (target_system, started_at desc);

create table plantlab_integration.legacy_record_links (
