create or replace function plantlab_audit.prevent_append_only_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'Table %.% is append-only', tg_table_schema, tg_table_name
    using errcode = '55000';
end;
$$;

create or replace function plantlab_audit.log_status_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb := to_jsonb(old);
  v_actor uuid;
  v_reason text;
begin
  if old.status is not distinct from new.status then
    return new;
  end if;

  v_actor := coalesce(
    nullif(v_new ->> 'updated_by', '')::uuid,
    nullif(v_new ->> 'reviewed_by', '')::uuid,
    nullif(v_new ->> 'approved_by', '')::uuid,
    auth.uid()
  );
  v_reason := coalesce(
    nullif(v_new ->> 'status_reason', ''),
    nullif(current_setting('app.status_reason', true), '')
  );

  insert into plantlab_audit.workflow_history (
    module_code,
    entity_type,
    entity_key,
    from_status,
    to_status,
    action,
    reason,
    changed_by,
    correlation_key,
    context
  ) values (
    tg_argv[0],
    tg_argv[1],
    v_new ->> 'id',
    v_old ->> 'status',
    v_new ->> 'status',
    'STATUS_CHANGE',
    v_reason,
    v_actor,
    nullif(current_setting('app.correlation_key', true), ''),
    jsonb_build_object('table_schema', tg_table_schema, 'table_name', tg_table_name)
  );

  return new;
end;
$$;

create trigger workflow_history_append_only
before update or delete on plantlab_audit.workflow_history
for each row execute function plantlab_audit.prevent_append_only_mutation();

create trigger integration_attempts_append_only
before update or delete on plantlab_audit.integration_attempts
for each row execute function plantlab_audit.prevent_append_only_mutation();

create trigger outbox_events_set_updated_at
before update on plantlab_audit.outbox_events
for each row execute function plantlab_platform.set_updated_at();
