  updated_at timestamptz not null default now(),
  constraint process_types_code_uq unique (process_code),
  constraint process_types_sequence_ck check (default_sequence is null or default_sequence > 0),
  constraint process_types_entry_mode_ck check (entry_mode in ('FORM', 'TEST', 'BOTH'))
);

create table plantlab_plant.process_plans (
