  constraint process_plans_code_uq unique (plan_code),
  constraint process_plans_timeline_ck check (
    planned_end_at is null or planned_start_at is null or planned_end_at >= planned_start_at
  ),
  constraint process_plans_status_ck check (
    status in ('DRAFT', 'REGISTERED', 'ACTIVE', 'HOLD', 'COMPLETED', 'CANCELLED')
  ),
