create or replace function plantlab_plant.validate_process_plan_site()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_site_type text;
begin
  select s.site_type into v_site_type
  from plantlab_master.sites s
  where s.id = new.site_id;

  if v_site_type not in ('PLANT', 'TOLLER') then
    raise exception 'Plant Process Plan site must have type PLANT or TOLLER'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

create or replace function plantlab_plant.validate_inspection_submission()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'SUBMITTED' and old.status is distinct from new.status then
    if new.answers = '{}'::jsonb then
      raise exception 'Inspection answers are required before submission'
        using errcode = '23514';
    end if;
    new.inspector_id := coalesce(new.inspector_id, auth.uid());
    new.inspected_at := coalesce(new.inspected_at, now());
    new.submitted_at := coalesce(new.submitted_at, now());
  end if;
  return new;
end;
$$;

create or replace function plantlab_plant.validate_test_submission()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_required_images integer := 0;
  v_image_count integer;
begin
  if new.test_type = 'MC' and new.upper_spec is null then
    new.upper_spec := 32;
  end if;

  if new.status = 'SUBMITTED' and old.status is distinct from new.status then
    if new.test_type in ('MC', 'PP', 'TSW') and new.numeric_value is null then
      raise exception 'Numeric value is required for Plant test type %', new.test_type
        using errcode = '23514';
    end if;

    if new.test_type = 'MC' then
      v_required_images := 3;
    elsif new.test_type = 'PP' then
      v_required_images := 1;
    end if;

    if v_required_images > 0 then
      select count(*)::integer
        into v_image_count
      from plantlab_core.attachments a
      where a.module_code = 'PLANT'
        and a.entity_type = 'TEST'
        and a.entity_key = new.id::text
        and a.category = 'EVIDENCE'
        and a.mime_type like 'image/%';

      if v_image_count < v_required_images then
        raise exception 'Plant test % requires at least % evidence image(s); found %',
          new.test_code, v_required_images, v_image_count
          using errcode = '23514';
      end if;
    end if;

    if new.numeric_value is not null and (new.lower_spec is not null or new.upper_spec is not null) then
      new.result := case
        when new.lower_spec is not null and new.numeric_value < new.lower_spec then 'OOS'
        when new.upper_spec is not null and new.numeric_value > new.upper_spec then 'OOS'
        else 'PASS'
      end;
    end if;

    new.submitted_at := coalesce(new.submitted_at, now());
  end if;

  return new;
end;
$$;

