create table plantlab_lab.test_types (
  id uuid primary key default gen_random_uuid(),
  test_code text not null,
  test_name text not null,
  description text,
  service_class text not null default 'MAIN',
  default_due_hours integer,
  requires_sample boolean not null default true,
  requires_equipment boolean not null default false,
  requires_approval boolean not null default true,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint test_types_code_uq unique (test_code),
  constraint test_types_service_class_ck check (service_class in ('MAIN', 'ADDITIONAL')),
  constraint test_types_due_ck check (default_due_hours is null or default_due_hours > 0)
);

create table plantlab_lab.parameters (
  id uuid primary key default gen_random_uuid(),
  parameter_code text not null,
  parameter_name text not null,
  description text,
  data_type text not null,
  default_unit_code text,
  decimal_scale integer,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint parameters_code_uq unique (parameter_code),
  constraint parameters_data_type_ck check (data_type in ('NUMERIC', 'TEXT', 'BOOLEAN')),
  constraint parameters_scale_ck check (decimal_scale is null or decimal_scale between 0 and 12)
);

create table plantlab_lab.test_type_parameters (
  test_type_id uuid not null references plantlab_lab.test_types(id) on delete cascade,
  parameter_id uuid not null references plantlab_lab.parameters(id) on delete restrict,
  sequence_no integer not null,
  is_required boolean not null default true,
  is_critical boolean not null default false,
  created_at timestamptz not null default now(),
  constraint test_type_parameters_pkey primary key (test_type_id, parameter_id),
  constraint test_type_parameters_sequence_uq unique (test_type_id, sequence_no),
  constraint test_type_parameters_sequence_ck check (sequence_no > 0)
);

create table plantlab_lab.methods (
