  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint equipment_code_uq unique (equipment_code),
  constraint equipment_serial_uq unique (serial_number),
  constraint equipment_status_ck check (
    status in ('ACTIVE', 'OUT_OF_SERVICE', 'CALIBRATION_DUE', 'RETIRED')
  ),
  constraint equipment_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index equipment_site_status_idx on plantlab_lab.equipment (site_id, status);

create table plantlab_lab.specifications (
  id uuid primary key default gen_random_uuid(),
  specification_code text not null,
  product_id bigint not null references plantlab_master.products(id) on delete restrict,
  test_type_id uuid not null references plantlab_lab.test_types(id) on delete restrict,
  version integer not null,
  effective_from date not null,
  effective_until date,
  status text not null default 'DRAFT',
  status_reason text,
  approved_by uuid references plantlab_platform.identities(id) on delete set null,
  approved_at timestamptz,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint specifications_code_uq unique (specification_code),
  constraint specifications_product_test_version_uq unique (product_id, test_type_id, version),
  constraint specifications_version_ck check (version > 0),
  constraint specifications_effective_ck check (
    effective_until is null or effective_until >= effective_from
  ),
  constraint specifications_status_ck check (status in ('DRAFT', 'ACTIVE', 'RETIRED')),
  constraint specifications_approval_ck check (
    (approved_at is null and approved_by is null)
    or (approved_at is not null and approved_by is not null)
  )
);

create index specifications_active_lookup_idx
  on plantlab_lab.specifications (product_id, test_type_id, effective_from desc)
  where status = 'ACTIVE';

create table plantlab_lab.specification_limits (
  id uuid primary key default gen_random_uuid(),
  specification_id uuid not null references plantlab_lab.specifications(id) on delete cascade,
  parameter_id uuid not null references plantlab_lab.parameters(id) on delete restrict,
  lower_limit numeric,
  upper_limit numeric,
  allowed_values jsonb,
  unit_code text,
  evaluation_rule text,
  is_critical boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint specification_limits_spec_parameter_uq unique (specification_id, parameter_id),
  constraint specification_limits_range_ck check (
    lower_limit is null or upper_limit is null or upper_limit >= lower_limit
  ),
  constraint specification_limits_allowed_array_ck check (
    allowed_values is null or jsonb_typeof(allowed_values) = 'array'
  ),
  constraint specification_limits_rule_present_ck check (
    lower_limit is not null
    or upper_limit is not null
    or allowed_values is not null
    or evaluation_rule is not null
  )
);

create index specification_limits_parameter_idx
  on plantlab_lab.specification_limits (parameter_id);

create or replace function plantlab_lab.validate_equipment_site()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_site_type text;
begin
  select s.site_type into v_site_type
  from plantlab_master.sites s
  where s.id = new.site_id;

  if v_site_type <> 'LAB' then
    raise exception 'Lab equipment site must have type LAB'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

create or replace function plantlab_lab.validate_specification_activation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'ACTIVE' and old.status is distinct from new.status then
    if not exists (
      select 1
      from plantlab_lab.specification_limits sl
      where sl.specification_id = new.id
    ) then
      raise exception 'A Lab specification requires at least one limit before activation'
        using errcode = '23514';
    end if;

    new.approved_by := coalesce(new.approved_by, auth.uid());
    new.approved_at := coalesce(new.approved_at, now());
  elsif new.status = 'RETIRED' and old.status is distinct from new.status then
    new.effective_until := coalesce(new.effective_until, current_date);
  end if;

  return new;
end;
$$;

insert into plantlab_lab.test_types (
  test_code,
  test_name,
  service_class,
  default_due_hours,
  requires_sample,
  requires_equipment,
  requires_approval
)
values
  ('MC', 'Moisture Content', 'MAIN', 24, true, true, true),
  ('PP', 'Physical Purity', 'MAIN', 48, true, true, true),
  ('TSW', 'Thousand Seed Weight', 'MAIN', 24, true, true, true),
  ('GERMINATION', 'Germination', 'MAIN', 240, true, true, true),
  ('VIGOUR', 'Vigour', 'ADDITIONAL', 240, true, true, true),
