insert into plantlab_lab.test_type_parameters (test_type_id, parameter_id, sequence_no, is_required, is_critical)
select tt.id, p.id, x.sequence_no, true, x.is_critical
from (
  values
    ('MC', 'MC_PERCENT', 1, true),
    ('PP', 'PURE_SEED_PERCENT', 1, true),
    ('PP', 'OTHER_VARIETY_PERCENT', 2, false),
    ('PP', 'OTHER_CROP_PERCENT', 3, false),
    ('PP', 'INERT_MATTER_PERCENT', 4, false),
    ('TSW', 'TSW_GRAM', 1, false),
    ('GERMINATION', 'GERMINATION_PERCENT', 1, true),
    ('VIGOUR', 'VIGOUR_PERCENT', 1, true),
    ('GENETIC_PURITY', 'GENETIC_PURITY_PERCENT', 1, true)
) as x(test_code, parameter_code, sequence_no, is_critical)
join plantlab_lab.test_types tt on tt.test_code = x.test_code
join plantlab_lab.parameters p on p.parameter_code = x.parameter_code
on conflict (test_type_id, parameter_id) do update
set sequence_no = excluded.sequence_no,
    is_required = excluded.is_required,
    is_critical = excluded.is_critical;

