create table plantlab_lab.requests (
  id uuid primary key default gen_random_uuid(),
  request_code text not null default (
    'LR-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20))
  ),
  source_module text not null,
  source_entity text,
  source_record_key text,
  lot_id uuid references plantlab_core.lots(id) on delete restrict,
  product_id bigint references plantlab_master.products(id) on delete restrict,
  requested_by uuid not null references plantlab_platform.identities(id) on delete restrict,
  request_site_id uuid references plantlab_master.sites(id) on delete restrict,
  target_lab_site_id uuid not null references plantlab_master.sites(id) on delete restrict,
  priority text not null default 'NORMAL',
  requested_at timestamptz,
  due_at timestamptz,
  sampling_instruction text,
  status text not null default 'DRAFT',
  status_reason text,
  idempotency_key text,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  updated_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint requests_code_uq unique (request_code),
  constraint requests_idempotency_uq unique (idempotency_key),
  constraint requests_subject_ck check (lot_id is not null or product_id is not null),
  constraint requests_source_module_ck check (
    source_module in ('PLANT', 'GOT_FET', 'COMPFEED', 'COMPLAINT', 'MANUAL')
  ),
  constraint requests_priority_ck check (priority in ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
  constraint requests_timeline_ck check (
    due_at is null or requested_at is null or due_at >= requested_at
  ),
  constraint requests_status_ck check (
    status in (
      'DRAFT', 'REQUESTED', 'ACCEPTED', 'PREPARED', 'SENT', 'RECEIVED',
      'TESTING', 'IN_REVIEW', 'APPROVED', 'REJECTED', 'RETEST',
      'CLOSED', 'CANCELLED'
    )
  )
);

create index requests_lot_idx on plantlab_lab.requests (lot_id, created_at desc)
  where lot_id is not null;
create index requests_queue_idx
  on plantlab_lab.requests (target_lab_site_id, status, priority, due_at);
create index requests_source_idx
  on plantlab_lab.requests (source_module, source_entity, source_record_key)
  where source_record_key is not null;

create table plantlab_lab.request_items (
