  priority text not null default 'NORMAL',
  due_at timestamptz,
  status text not null default 'DRAFT',
  status_reason text,
  remarks text,
  is_active boolean not null default true,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  updated_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint request_items_priority_ck check (priority in ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
  constraint request_items_status_ck check (
    status in (
      'DRAFT', 'REQUESTED', 'READY', 'TESTING', 'IN_REVIEW',
      'APPROVED', 'REJECTED', 'RETEST', 'CANCELLED'
    )
  )
);

create unique index request_items_active_request_test_uq
  on plantlab_lab.request_items (request_id, test_type_id)
  where is_active;
create index request_items_queue_idx on plantlab_lab.request_items (status, priority, due_at);
create index request_items_test_type_idx on plantlab_lab.request_items (test_type_id, status);

create table plantlab_lab.request_samples (
  id uuid primary key default gen_random_uuid(),
