create index request_samples_sample_idx on plantlab_lab.request_samples (sample_id);

create table plantlab_plant.sample_dispatches (
  id uuid primary key default gen_random_uuid(),
  dispatch_code text not null default (
    'DSP-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20))
  ),
  sample_id uuid not null references plantlab_core.samples(id) on delete restrict,
  lab_request_id uuid not null references plantlab_lab.requests(id) on delete restrict,
  source_site_id uuid not null references plantlab_master.sites(id) on delete restrict,
  target_lab_site_id uuid not null references plantlab_master.sites(id) on delete restrict,
  prepared_by uuid references plantlab_platform.identities(id) on delete set null,
  prepared_at timestamptz,
  sent_by uuid references plantlab_platform.identities(id) on delete set null,
  sent_at timestamptz,
  delivered_at timestamptz,
  quantity numeric,
  unit_code text,
  condition_at_dispatch text,
  courier_name text,
  tracking_number text,
  status text not null default 'PREPARED',
  status_reason text,
  remarks text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sample_dispatches_code_uq unique (dispatch_code),
  constraint sample_dispatches_request_sample_uq unique (lab_request_id, sample_id),
  constraint sample_dispatches_sites_ck check (source_site_id <> target_lab_site_id),
  constraint sample_dispatches_quantity_ck check (quantity is null or quantity > 0),
  constraint sample_dispatches_status_ck check (
    status in ('PREPARED', 'SENT', 'DELIVERED', 'RECEIVED', 'CANCELLED')
  ),
  constraint sample_dispatches_timeline_ck check (
    (sent_at is null or prepared_at is null or sent_at >= prepared_at)
    and (delivered_at is null or sent_at is null or delivered_at >= sent_at)
  )
);

create index sample_dispatches_queue_idx
  on plantlab_plant.sample_dispatches (target_lab_site_id, status, sent_at);
create index sample_dispatches_sample_idx on plantlab_plant.sample_dispatches (sample_id);

create table plantlab_lab.sample_receipts (
  id uuid primary key default gen_random_uuid(),
  receipt_code text not null default (
    'RCV-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20))
  ),
  request_sample_id uuid not null references plantlab_lab.request_samples(id) on delete restrict,
  received_at timestamptz not null default now(),
  received_by uuid not null references plantlab_platform.identities(id) on delete restrict,
  received_quantity numeric,
  unit_code text,
  condition_notes text,
  temperature_celsius numeric,
  decision text not null default 'PENDING',
  rejection_reason text,
  status text not null default 'DRAFT',
  status_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sample_receipts_code_uq unique (receipt_code),
  constraint sample_receipts_request_sample_uq unique (request_sample_id),
  constraint sample_receipts_quantity_ck check (received_quantity is null or received_quantity > 0),
  constraint sample_receipts_decision_ck check (decision in ('PENDING', 'ACCEPT', 'HOLD', 'REJECT')),
  constraint sample_receipts_status_ck check (status in ('DRAFT', 'ACCEPTED', 'HOLD', 'REJECTED')),
  constraint sample_receipts_decision_status_ck check (
    (decision = 'PENDING' and status = 'DRAFT')
    or (decision = 'ACCEPT' and status = 'ACCEPTED')
    or (decision = 'HOLD' and status = 'HOLD')
    or (decision = 'REJECT' and status = 'REJECTED')
  ),
  constraint sample_receipts_rejection_reason_ck check (
    decision <> 'REJECT' or nullif(rejection_reason, '') is not null
  )
);

create index sample_receipts_queue_idx on plantlab_lab.sample_receipts (status, received_at);

create table plantlab_lab.custody_events (
  id bigint generated always as identity primary key,
