  constraint test_runs_attempt_ck check (attempt_no > 0),
  constraint test_runs_timeline_ck check (
    (completed_at is null or started_at is null or completed_at >= started_at)
    and (submitted_at is null or completed_at is null or submitted_at >= completed_at)
  ),
  constraint test_runs_status_ck check (
    status in (
      'ASSIGNED', 'IN_PROGRESS', 'SUBMITTED', 'IN_REVIEW',
      'APPROVED', 'REJECTED', 'RETEST', 'CANCELLED'
    )
  )
);

create index test_runs_queue_idx on plantlab_lab.test_runs (status, performed_by, created_at);
create index test_runs_item_idx on plantlab_lab.test_runs (request_item_id, attempt_no desc);

create table plantlab_lab.result_values (
  id uuid primary key default gen_random_uuid(),
  test_run_id uuid not null references plantlab_lab.test_runs(id) on delete cascade,
  parameter_id uuid not null references plantlab_lab.parameters(id) on delete restrict,
  numeric_value numeric,
  text_value text,
  boolean_value boolean,
  unit_code text,
  lower_spec_snapshot numeric,
  upper_spec_snapshot numeric,
  allowed_values_snapshot jsonb,
  result text not null default 'PENDING_REVIEW',
  remarks text,
  recorded_by uuid references plantlab_platform.identities(id) on delete set null,
  recorded_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint result_values_run_parameter_uq unique (test_run_id, parameter_id),
  constraint result_values_one_typed_value_ck check (
    num_nonnulls(numeric_value, text_value, boolean_value) = 1
  ),
  constraint result_values_spec_range_ck check (
    lower_spec_snapshot is null
    or upper_spec_snapshot is null
    or upper_spec_snapshot >= lower_spec_snapshot
  ),
  constraint result_values_allowed_array_ck check (
    allowed_values_snapshot is null or jsonb_typeof(allowed_values_snapshot) = 'array'
  ),
  constraint result_values_result_ck check (
    result in ('PENDING_REVIEW', 'PASS', 'FAIL', 'OOS', 'NA')
  )
);

create index result_values_parameter_idx on plantlab_lab.result_values (parameter_id, recorded_at desc);

create table plantlab_lab.result_decisions (
  id bigint generated always as identity primary key,
  test_run_id uuid not null references plantlab_lab.test_runs(id) on delete restrict,
  decision text not null,
  previous_status text not null,
  resulting_status text not null,
  reviewer_id uuid not null references plantlab_platform.identities(id) on delete restrict,
  reason text,
  decided_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  constraint result_decisions_decision_ck check (
    decision in ('APPROVE', 'REJECT', 'RETEST', 'REQUEST_REVISION')
  ),
  constraint result_decisions_resulting_status_ck check (
    resulting_status in ('APPROVED', 'REJECTED', 'RETEST')
  ),
  constraint result_decisions_reason_ck check (
    decision = 'APPROVE' or nullif(reason, '') is not null
  ),
  constraint result_decisions_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index result_decisions_run_idx on plantlab_lab.result_decisions (test_run_id, decided_at desc);

create table plantlab_lab.source_result_links (
  id uuid primary key default gen_random_uuid(),
  request_item_id uuid not null references plantlab_lab.request_items(id) on delete cascade,
  test_run_id uuid references plantlab_lab.test_runs(id) on delete set null,
  source_module text not null,
  source_schema text,
  source_entity text not null,
  source_record_key text not null,
  relationship_type text not null,
  source_snapshot jsonb not null default '{}'::jsonb,
  linked_by uuid references plantlab_platform.identities(id) on delete set null,
  linked_at timestamptz not null default now(),
  constraint source_result_links_source_uq unique (
    request_item_id, source_module, source_entity, source_record_key, relationship_type
  ),
  constraint source_result_links_module_ck check (
    source_module in ('PLANT', 'GOT_FET', 'COMPFEED', 'COMPLAINT')
  ),
  constraint source_result_links_relationship_ck check (
    relationship_type in ('SOURCE', 'REFERENCE', 'COMPARISON', 'ADDITIONAL_TEST')
  ),
  constraint source_result_links_snapshot_object_ck check (jsonb_typeof(source_snapshot) = 'object')
);

create index source_result_links_run_idx on plantlab_lab.source_result_links (test_run_id)
  where test_run_id is not null;
create index source_result_links_source_idx
  on plantlab_lab.source_result_links (source_module, source_entity, source_record_key);

create table plantlab_plant.nonconformances (
  id uuid primary key default gen_random_uuid(),
  nc_code text not null default (
    'NC-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20))
  ),
  lot_id uuid not null references plantlab_core.lots(id) on delete restrict,
  inspection_id uuid references plantlab_plant.inspections(id) on delete restrict,
  plant_test_id uuid references plantlab_plant.tests(id) on delete restrict,
  lab_test_run_id uuid references plantlab_lab.test_runs(id) on delete restrict,
  severity text not null default 'MAJOR',
  description text not null,
  containment_action text,
  root_cause text,
  corrective_action text,
  owner_id uuid references plantlab_platform.identities(id) on delete set null,
  due_at timestamptz,
  status text not null default 'OPEN',
  status_reason text,
  closed_by uuid references plantlab_platform.identities(id) on delete set null,
  closed_at timestamptz,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint nonconformances_code_uq unique (nc_code),
  constraint nonconformances_source_ck check (
    num_nonnulls(inspection_id, plant_test_id, lab_test_run_id) >= 1
  ),
  constraint nonconformances_severity_ck check (severity in ('MINOR', 'MAJOR', 'CRITICAL')),
  constraint nonconformances_status_ck check (
    status in ('OPEN', 'CONTAINED', 'ROOT_CAUSE', 'ACTION_IN_PROGRESS', 'VERIFICATION', 'CLOSED', 'CANCELLED')
  ),
  constraint nonconformances_closure_ck check (
    (closed_at is null and closed_by is null)
    or (closed_at is not null and closed_by is not null)
  ),
  constraint nonconformances_closed_status_ck check (
    status <> 'CLOSED' or (closed_at is not null and closed_by is not null)
  )
);

create index nonconformances_queue_idx on plantlab_plant.nonconformances (status, severity, due_at);
create index nonconformances_lot_idx on plantlab_plant.nonconformances (lot_id, created_at desc);

create or replace function plantlab_lab.validate_request_subject()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_lot_product_id bigint;
  v_target_site_type text;
begin
  select s.site_type into v_target_site_type
  from plantlab_master.sites s
  where s.id = new.target_lab_site_id;

  if v_target_site_type <> 'LAB' then
    raise exception 'Lab Request target site must have type LAB'
      using errcode = '23514';
  end if;

  if new.lot_id is not null then
    select l.product_id into v_lot_product_id
    from plantlab_core.lots l
    where l.id = new.lot_id;

    if new.product_id is null then
      new.product_id := v_lot_product_id;
    elsif new.product_id is distinct from v_lot_product_id then
      raise exception 'Lab Request product does not match the canonical Lot product'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_request_item()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_lot_id uuid;
  v_spec_test_type_id uuid;
  v_existing_id uuid;
begin
  if new.specification_id is not null then
    select s.test_type_id
      into v_spec_test_type_id
    from plantlab_lab.specifications s
    where s.id = new.specification_id;

    if v_spec_test_type_id is distinct from new.test_type_id then
      raise exception 'Specification does not belong to the selected test type'
        using errcode = '23514';
    end if;
  end if;

  select r.lot_id into v_lot_id
  from plantlab_lab.requests r
  where r.id = new.request_id;

  if new.is_active and v_lot_id is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(v_lot_id::text || ':' || new.test_type_id::text, 0)
    );

    select ri.id
      into v_existing_id
    from plantlab_lab.request_items ri
    join plantlab_lab.requests r on r.id = ri.request_id
    where r.lot_id = v_lot_id
      and ri.test_type_id = new.test_type_id
      and ri.is_active
      and ri.id <> new.id
      and r.status not in ('APPROVED', 'REJECTED', 'CLOSED', 'CANCELLED')
    limit 1;

    if v_existing_id is not null then
      raise exception 'An active Lab request already exists for this Lot and test type'
        using errcode = '23505';
    end if;
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.enforce_request_transition_actor()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company_id bigint;
begin
  select l.company_id into v_company_id
  from plantlab_core.lots l
  where l.id = new.lot_id;

  if v_company_id is null then
    select coalesce(target_site.company_id, request_site.company_id)
      into v_company_id
    from plantlab_master.sites target_site
    left join plantlab_master.sites request_site on request_site.id = new.request_site_id
    where target_site.id = new.target_lab_site_id;
  end if;

  if old.status <> 'DRAFT'
    and not plantlab_platform.has_permission(
      'LAB', 'request.write', new.target_lab_site_id, v_company_id
    ) then
    raise exception 'Only the target Lab may advance a request after submission'
      using errcode = '42501';
  end if;

  if old.status = 'IN_REVIEW' and new.status in ('APPROVED', 'REJECTED', 'RETEST') then
    if not plantlab_platform.has_permission(
      'LAB', 'result.approve', new.target_lab_site_id, v_company_id
    ) then
      raise exception 'Final Lab Request decision requires result.approve permission'
        using errcode = '42501';
    end if;

    if new.status = 'APPROVED' and exists (
      select 1
      from plantlab_lab.request_items ri
      where ri.request_id = new.id
        and ri.is_active
        and ri.status <> 'APPROVED'
    ) then
      raise exception 'All active Lab Request items must be APPROVED first'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.enforce_request_item_transition_actor()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_target_lab_site_id uuid;
  v_company_id bigint;
begin
  select r.target_lab_site_id, l.company_id
    into v_target_lab_site_id, v_company_id
  from plantlab_lab.requests r
  left join plantlab_core.lots l on l.id = r.lot_id
  where r.id = new.request_id;

  if old.status <> 'DRAFT'
    and not plantlab_platform.has_permission(
      'LAB', 'request_item.write', v_target_lab_site_id, v_company_id
    ) then
    raise exception 'Only the target Lab may advance a request item after submission'
      using errcode = '42501';
  end if;

  if old.status = 'IN_REVIEW' and new.status in ('APPROVED', 'REJECTED', 'RETEST')
    and not plantlab_platform.has_permission(
      'LAB', 'result.approve', v_target_lab_site_id, v_company_id
    ) then
    raise exception 'Final Lab Request item decision requires result.approve permission'
      using errcode = '42501';
  end if;

  if old.status = 'IN_REVIEW' and new.status = 'APPROVED'
    and not exists (
      select 1
      from plantlab_lab.test_runs tr
      where tr.request_item_id = new.id
        and tr.status = 'APPROVED'
    ) then
    raise exception 'A Lab Request item requires an APPROVED Test Run'
      using errcode = '23514';
  end if;

  if old.status = 'IN_REVIEW' and new.status = 'RETEST'
    and not exists (
      select 1
      from plantlab_lab.test_runs tr
      where tr.request_item_id = new.id
        and tr.status = 'RETEST'
    ) then
    raise exception 'A Lab Request item RETEST status requires a RETEST Test Run decision'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_request_sample()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request_lot_id uuid;
  v_sample_lot_id uuid;
begin
  select r.lot_id into v_request_lot_id from plantlab_lab.requests r where r.id = new.request_id;
  select s.lot_id into v_sample_lot_id from plantlab_core.samples s where s.id = new.sample_id;

  if v_request_lot_id is not null and v_request_lot_id is distinct from v_sample_lot_id then
    raise exception 'Sample Lot does not match Lab Request Lot'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_sample_receipt()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request_id uuid;
  v_sample_id uuid;
  v_sent_at timestamptz;
begin
  select rs.request_id, rs.sample_id
    into v_request_id, v_sample_id
  from plantlab_lab.request_samples rs
  where rs.id = new.request_sample_id;

  select d.sent_at
    into v_sent_at
  from plantlab_plant.sample_dispatches d
  where d.lab_request_id = v_request_id
    and d.sample_id = v_sample_id;

  if v_sent_at is not null and new.received_at < v_sent_at then
    raise exception 'Sample received_at cannot be earlier than dispatch sent_at'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_assignment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request_id uuid;
begin
  select ri.request_id into v_request_id
  from plantlab_lab.request_items ri
  where ri.id = new.request_item_id;

  if not exists (
    select 1
    from plantlab_lab.request_samples rs
    where rs.request_id = v_request_id
      and rs.sample_id = new.sample_id
  ) then
    raise exception 'Assigned Sample is not linked to the Lab Request'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_run_identity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_assignment_item_id uuid;
  v_assignment_sample_id uuid;
  v_parent_item_id uuid;
  v_parent_sample_id uuid;
  v_parent_attempt integer;
begin
  if new.assignment_id is not null then
    select ta.request_item_id, ta.sample_id
      into v_assignment_item_id, v_assignment_sample_id
    from plantlab_lab.test_assignments ta
    where ta.id = new.assignment_id;

    if v_assignment_item_id is distinct from new.request_item_id
      or v_assignment_sample_id is distinct from new.sample_id then
      raise exception 'Test Run does not match its assignment item and Sample'
        using errcode = '23514';
    end if;
  end if;

  if new.retest_of_id is not null then
    select tr.request_item_id, tr.sample_id, tr.attempt_no
      into v_parent_item_id, v_parent_sample_id, v_parent_attempt
    from plantlab_lab.test_runs tr
    where tr.id = new.retest_of_id;

    if v_parent_item_id is distinct from new.request_item_id
      or v_parent_sample_id is distinct from new.sample_id
      or new.attempt_no <> v_parent_attempt + 1 then
      raise exception 'Retest must use the same request item and Sample with the next attempt number'
        using errcode = '23514';
    end if;
  elsif new.attempt_no > 1 then
    raise exception 'Attempt number greater than 1 requires retest_of_id'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.enforce_result_editable()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_test_run_id uuid;
  v_run_status text;
begin
  if tg_op = 'DELETE' then
    v_test_run_id := old.test_run_id;
  else
    v_test_run_id := new.test_run_id;
  end if;

  select tr.status into v_run_status
  from plantlab_lab.test_runs tr
  where tr.id = v_test_run_id;

  if v_run_status <> 'IN_PROGRESS' then
    raise exception 'Result values can only be changed while the Test Run is IN_PROGRESS'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create or replace function plantlab_lab.validate_result_value()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_data_type text;
  v_default_unit text;
  v_specification_id uuid;
  v_test_type_id uuid;
  v_lower numeric;
  v_upper numeric;
  v_allowed jsonb;
begin
  select p.data_type, p.default_unit_code, ri.specification_id, ri.test_type_id
    into v_data_type, v_default_unit, v_specification_id, v_test_type_id
  from plantlab_lab.parameters p
  join plantlab_lab.test_runs tr on tr.id = new.test_run_id
  join plantlab_lab.request_items ri on ri.id = tr.request_item_id
  where p.id = new.parameter_id;

  if not exists (
    select 1
    from plantlab_lab.test_type_parameters ttp
    where ttp.test_type_id = v_test_type_id
      and ttp.parameter_id = new.parameter_id
  ) then
    raise exception 'Parameter is not configured for the requested test type'
      using errcode = '23514';
  end if;

  if (v_data_type = 'NUMERIC' and new.numeric_value is null)
    or (v_data_type = 'TEXT' and new.text_value is null)
    or (v_data_type = 'BOOLEAN' and new.boolean_value is null) then
    raise exception 'Typed value does not match parameter data type %', v_data_type
      using errcode = '23514';
  end if;

  if v_specification_id is not null then
    select sl.lower_limit, sl.upper_limit, sl.allowed_values
      into v_lower, v_upper, v_allowed
    from plantlab_lab.specification_limits sl
    where sl.specification_id = v_specification_id
      and sl.parameter_id = new.parameter_id;

    new.lower_spec_snapshot := coalesce(new.lower_spec_snapshot, v_lower);
    new.upper_spec_snapshot := coalesce(new.upper_spec_snapshot, v_upper);
    new.allowed_values_snapshot := coalesce(new.allowed_values_snapshot, v_allowed);
  end if;

  new.unit_code := coalesce(new.unit_code, v_default_unit);

  if new.numeric_value is not null
    and (new.lower_spec_snapshot is not null or new.upper_spec_snapshot is not null) then
    new.result := case
      when new.lower_spec_snapshot is not null and new.numeric_value < new.lower_spec_snapshot then 'OOS'
      when new.upper_spec_snapshot is not null and new.numeric_value > new.upper_spec_snapshot then 'OOS'
      else 'PASS'
    end;
  elsif new.text_value is not null and new.allowed_values_snapshot is not null then
    new.result := case when new.allowed_values_snapshot ? new.text_value then 'PASS' else 'OOS' end;
  else
    new.result := 'PENDING_REVIEW';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.prevent_approved_result_mutation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_test_run_id uuid;
begin
  if tg_op = 'DELETE' then
    v_test_run_id := old.test_run_id;
  else
    v_test_run_id := new.test_run_id;
  end if;

  if exists (
    select 1
    from plantlab_lab.result_decisions d
    where d.test_run_id = v_test_run_id
      and d.decision = 'APPROVE'
  ) then
    raise exception 'Approved Lab results are immutable; create a revision or retest'
      using errcode = '55000';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create or replace function plantlab_lab.validate_result_decision()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_current_status text;
  v_performed_by uuid;
  v_item_status text;
  v_missing_required integer;
  v_failed_values integer;
begin
  select tr.status, tr.performed_by, ri.status
    into v_current_status, v_performed_by, v_item_status
  from plantlab_lab.test_runs tr
  join plantlab_lab.request_items ri on ri.id = tr.request_item_id
  where tr.id = new.test_run_id
  for update;

  if v_current_status <> 'IN_REVIEW' then
    raise exception 'Lab Test Run must be IN_REVIEW before a decision; current status is %', v_current_status
      using errcode = '23514';
  end if;

  if v_item_status <> 'IN_REVIEW' then
    raise exception 'Lab Request item must be IN_REVIEW before a Test Run decision'
      using errcode = '23514';
  end if;

  if v_performed_by is not null and v_performed_by = new.reviewer_id then
    raise exception 'The analyst who performed a Lab Test Run cannot approve or reject the same run'
      using errcode = '42501';
  end if;

  new.previous_status := v_current_status;
  new.resulting_status := case new.decision
    when 'APPROVE' then 'APPROVED'
    when 'RETEST' then 'RETEST'
    else 'REJECTED'
  end;

  if new.decision = 'APPROVE' then
    select count(*)::integer
      into v_missing_required
    from plantlab_lab.test_runs tr
    join plantlab_lab.request_items ri on ri.id = tr.request_item_id
    join plantlab_lab.test_type_parameters ttp
      on ttp.test_type_id = ri.test_type_id and ttp.is_required
    left join plantlab_lab.result_values rv
      on rv.test_run_id = tr.id and rv.parameter_id = ttp.parameter_id
    where tr.id = new.test_run_id
      and rv.id is null;

    select count(*)::integer
      into v_failed_values
    from plantlab_lab.result_values rv
    where rv.test_run_id = new.test_run_id
      and rv.result in ('FAIL', 'OOS');

    if v_missing_required > 0 then
      raise exception 'Cannot approve: % required result parameter(s) are missing', v_missing_required
        using errcode = '23514';
    end if;
    if v_failed_values > 0 then
      raise exception 'Cannot approve: % result value(s) are FAIL/OOS', v_failed_values
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.apply_result_decision()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform set_config('app.status_reason', coalesce(new.reason, ''), true);
  perform set_config('app.result_decision_context', 'on', true);

  update plantlab_lab.test_runs
  set status = new.resulting_status,
      status_reason = new.reason,
      updated_by = new.reviewer_id,
      updated_at = now()
  where id = new.test_run_id;

  perform set_config('app.result_decision_context', 'off', true);

  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_run_workflow()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_missing_required integer;
  v_item_status text;
  v_request_status text;
begin
  if old.status = 'IN_REVIEW'
    and new.status in ('APPROVED', 'REJECTED', 'RETEST')
    and current_setting('app.result_decision_context', true) is distinct from 'on' then
    raise exception 'Final Test Run status can only be set through plantlab_lab.result_decisions'
      using errcode = '42501';
  end if;

  if new.status = 'IN_PROGRESS' and old.status is distinct from new.status then
    select ri.status, r.status
      into v_item_status, v_request_status
    from plantlab_lab.request_items ri
    join plantlab_lab.requests r on r.id = ri.request_id
    where ri.id = new.request_item_id;

    if v_item_status not in ('READY', 'TESTING')
      or v_request_status not in ('RECEIVED', 'TESTING') then
      raise exception 'Lab Request and item must be received/ready before testing starts'
        using errcode = '23514';
    end if;

    new.started_at := coalesce(new.started_at, now());
    new.performed_by := coalesce(new.performed_by, auth.uid());
  end if;

  if new.status = 'SUBMITTED' and old.status is distinct from new.status then
    select ri.status into v_item_status
    from plantlab_lab.request_items ri
    where ri.id = new.request_item_id;

    if v_item_status <> 'TESTING' then
      raise exception 'Lab Request item must be TESTING before a Test Run is submitted'
        using errcode = '23514';
    end if;

    select count(*)::integer
      into v_missing_required
    from plantlab_lab.request_items ri
    join plantlab_lab.test_type_parameters ttp
      on ttp.test_type_id = ri.test_type_id and ttp.is_required
    left join plantlab_lab.result_values rv
      on rv.test_run_id = new.id and rv.parameter_id = ttp.parameter_id
    where ri.id = new.request_item_id
      and rv.id is null;

    if v_missing_required > 0 then
      raise exception 'Cannot submit Test Run: % required result parameter(s) are missing',
        v_missing_required using errcode = '23514';
    end if;

    new.completed_at := coalesce(new.completed_at, now());
    new.submitted_at := coalesce(new.submitted_at, now());
  end if;

  return new;
end;
$$;

