create or replace function plantlab_platform.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from plantlab_platform.user_role_assignments ura
    join plantlab_platform.role_definitions rd on rd.id = ura.role_id
    join plantlab_platform.module_registry mr on mr.id = rd.module_id
    where ura.user_id = auth.uid()
      and ura.is_active
      and rd.is_active
      and mr.is_active
      and ura.valid_from <= now()
      and (ura.valid_until is null or ura.valid_until > now())
  );
$$;

create or replace function plantlab_platform.has_module_permission(
  p_module_code text,
  p_permission text
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from plantlab_platform.user_role_assignments ura
    join plantlab_platform.role_definitions rd on rd.id = ura.role_id
    join plantlab_platform.module_registry mr on mr.id = rd.module_id
    where ura.user_id = auth.uid()
      and ura.is_active
      and rd.is_active
      and mr.is_active
      and mr.module_code = upper(p_module_code)
      and ura.valid_from <= now()
      and (ura.valid_until is null or ura.valid_until > now())
      and (rd.permissions ? '*' or rd.permissions ? p_permission)
  );
$$;

