create or replace function plantlab_platform.can_access_lab_request_values(
  p_source_module text,
  p_request_site_id uuid,
  p_target_lab_site_id uuid,
  p_lot_id uuid,
  p_permission text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_company_id bigint;
  v_source_module text;
begin
  select l.company_id into v_company_id
  from plantlab_core.lots l
  where l.id = p_lot_id;

  if v_company_id is null then
    select coalesce(target_site.company_id, request_site.company_id)
      into v_company_id
    from plantlab_master.sites target_site
    left join plantlab_master.sites request_site on request_site.id = p_request_site_id
    where target_site.id = p_target_lab_site_id;
  end if;

  v_source_module := case p_source_module
    when 'COMPLAINT' then 'CC'
    when 'MANUAL' then null
    else p_source_module
  end;

  return plantlab_platform.has_permission(
      'LAB', p_permission, p_target_lab_site_id, v_company_id
    )
    or (
      v_source_module is not null
      and plantlab_platform.has_permission(
        v_source_module, p_permission, p_request_site_id, v_company_id
      )
    );
end;
$$;

