create or replace function plantlab_platform.can_access_core_lot(
  p_lot_id uuid,
  p_permission text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_lot plantlab_core.lots%rowtype;
begin
  select * into v_lot from plantlab_core.lots l where l.id = p_lot_id;
  if not found then
    return false;
  end if;

  if plantlab_platform.has_permission('PLANT', p_permission, v_lot.plant_site_id, v_lot.company_id)
    or plantlab_platform.has_permission('COMPFEED', p_permission, v_lot.plant_site_id, v_lot.company_id)
    or plantlab_platform.has_permission('WAREHOUSE', p_permission, v_lot.plant_site_id, v_lot.company_id)
    or plantlab_platform.has_permission('KC', p_permission, v_lot.plant_site_id, v_lot.company_id) then
    return true;
  end if;

  return exists (
    select 1
    from plantlab_lab.requests r
    where r.lot_id = p_lot_id
      and plantlab_platform.can_access_lab_request_values(
        r.source_module,
        r.request_site_id,
        r.target_lab_site_id,
        r.lot_id,
        p_permission
      )
  );
end;
$$;

