  from plantlab_core.samples s
  where s.id = p_sample_id;
$$;

create or replace function plantlab_platform.can_access_dispatch_values(
  p_sample_id uuid,
  p_source_site_id uuid,
  p_target_lab_site_id uuid,
  p_permission text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_company_id bigint;
begin
  select l.company_id into v_company_id
  from plantlab_core.samples s
  join plantlab_core.lots l on l.id = s.lot_id
  where s.id = p_sample_id;

  return plantlab_platform.has_permission('PLANT', p_permission, p_source_site_id, v_company_id)
    or plantlab_platform.has_permission('LAB', p_permission, p_target_lab_site_id, v_company_id);
end;
$$;

