)
insert into plantlab_platform.role_definitions (
  module_id,
  role_code,
  role_name,
  permissions
)
select mr.id, rs.role_code, rs.role_name, rs.permissions
from role_seed rs
join plantlab_platform.module_registry mr on mr.module_code = rs.module_code
on conflict (module_id, role_code) do update
set role_name = excluded.role_name,
    permissions = excluded.permissions,
    is_active = true,
    updated_at = now();

do $$
declare
  r record;
begin
  for r in
    select schemaname, tablename
    from pg_tables
    where schemaname in ('plantlab_platform', 'plantlab_master', 'plantlab_core', 'plantlab_plant', 'plantlab_lab', 'plantlab_audit', 'plantlab_integration')
  loop
    execute format('alter table %I.%I enable row level security', r.schemaname, r.tablename);
  end loop;
end;
$$;

