-- Canonical source: 20260811000800_workflow_api_outbox.sql
create or replace function plantlab_platform.enforce_initial_status()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status is distinct from tg_argv[0] then
    raise exception 'Initial status for %.% must be %, received %',
      tg_table_schema, tg_table_name, tg_argv[0], new.status
      using errcode = '23514';
  end if;
  return new;
end;
$$;

create or replace function plantlab_audit.enqueue_status_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb := to_jsonb(old);
  v_idempotency_key text;
begin
  if old.status is not distinct from new.status then
    return new;
  end if;

  v_idempotency_key := concat_ws(
    ':',
    tg_argv[0],
    tg_argv[1],
    v_new ->> 'id',
    v_old ->> 'status',
    v_new ->> 'status',
    coalesce(v_new ->> 'updated_at', clock_timestamp()::text)
  );

  insert into plantlab_audit.outbox_events (
    event_type,
    aggregate_type,
    aggregate_key,
    module_code,
    payload,
    idempotency_key
  ) values (
    tg_argv[0] || '.' || tg_argv[1] || '.' || (v_new ->> 'status'),
    tg_argv[1],
    v_new ->> 'id',
    tg_argv[0],
    jsonb_build_object(
      'id', v_new ->> 'id',
      'entity_type', tg_argv[1],
      'module_code', tg_argv[0],
      'from_status', v_old ->> 'status',
      'to_status', v_new ->> 'status',
      'occurred_at', now(),
      'correlation_key', nullif(current_setting('app.correlation_key', true), '')
    ),
    v_idempotency_key
  )
  on conflict (idempotency_key) do nothing;

  return new;
end;
$$;

insert into plantlab_platform.status_transitions
  (module_code, entity_type, from_status, to_status, requires_reason)
values
  ('PLATFORM', 'LOT', 'REGISTERED', 'IN_PROCESS', false),
  ('PLATFORM', 'LOT', 'REGISTERED', 'HOLD', true),
  ('PLATFORM', 'LOT', 'REGISTERED', 'REJECTED', true),
  ('PLATFORM', 'LOT', 'REGISTERED', 'CLOSED', true),
  ('PLATFORM', 'LOT', 'IN_PROCESS', 'HOLD', true),
  ('PLATFORM', 'LOT', 'IN_PROCESS', 'RELEASED', false),
  ('PLATFORM', 'LOT', 'IN_PROCESS', 'REJECTED', true),
  ('PLATFORM', 'LOT', 'HOLD', 'IN_PROCESS', true),
  ('PLATFORM', 'LOT', 'HOLD', 'RELEASED', true),
  ('PLATFORM', 'LOT', 'HOLD', 'REJECTED', true),
  ('PLATFORM', 'LOT', 'RELEASED', 'CLOSED', false),
  ('PLATFORM', 'LOT', 'REJECTED', 'CLOSED', true),
  ('PLATFORM', 'SAMPLE', 'PREPARED', 'SENT', false),
  ('PLATFORM', 'SAMPLE', 'PREPARED', 'RECEIVED', false),
  ('PLATFORM', 'SAMPLE', 'PREPARED', 'HOLD', true),
  ('PLATFORM', 'SAMPLE', 'PREPARED', 'REJECTED', true),
  ('PLATFORM', 'SAMPLE', 'SENT', 'RECEIVED', false),
  ('PLATFORM', 'SAMPLE', 'SENT', 'HOLD', true),
  ('PLATFORM', 'SAMPLE', 'SENT', 'REJECTED', true),
  ('PLATFORM', 'SAMPLE', 'RECEIVED', 'HOLD', true),
  ('PLATFORM', 'SAMPLE', 'RECEIVED', 'CONSUMED', false),
  ('PLATFORM', 'SAMPLE', 'RECEIVED', 'ARCHIVED', false),
  ('PLATFORM', 'SAMPLE', 'HOLD', 'RECEIVED', true),
  ('PLATFORM', 'SAMPLE', 'HOLD', 'REJECTED', true),
  ('PLATFORM', 'SAMPLE', 'CONSUMED', 'ARCHIVED', false)
on conflict do nothing;

