create or replace function plantlab_plant.submit_inspection(p_inspection_id uuid)
returns plantlab_plant.inspections
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_plant.inspections;
begin
  update plantlab_plant.inspections
  set status = 'SUBMITTED',
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_inspection_id
    and status = 'DRAFT'
  returning * into v_row;

  if not found then
    raise exception 'Inspection not found, not accessible, or not in DRAFT status'
      using errcode = 'P0002';
  end if;

  return v_row;
end;
$$;

create or replace function plantlab_plant.submit_test(p_test_id uuid)
returns plantlab_plant.tests
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_plant.tests;
begin
  update plantlab_plant.tests
  set status = 'SUBMITTED',
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_test_id
    and status = 'DRAFT'
  returning * into v_row;

  if not found then
    raise exception 'Plant Test not found, not accessible, or not in DRAFT status'
      using errcode = 'P0002';
  end if;

  return v_row;
end;
$$;

create or replace function plantlab_lab.submit_request(p_request_id uuid)
returns plantlab_lab.requests
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_lab.requests;
  v_item_count integer;
begin
  select count(*)::integer into v_item_count
  from plantlab_lab.request_items ri
  where ri.request_id = p_request_id
    and ri.is_active;

  if v_item_count = 0 then
    raise exception 'At least one active test item is required before submitting a Lab Request'
      using errcode = '23514';
  end if;

  update plantlab_lab.requests
  set status = 'REQUESTED',
      requested_at = coalesce(requested_at, now()),
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_request_id
    and status = 'DRAFT'
  returning * into v_row;

  if not found then
    raise exception 'Lab Request not found, not accessible, or not in DRAFT status'
      using errcode = 'P0002';
  end if;

  update plantlab_lab.request_items
  set status = 'REQUESTED',
      updated_by = auth.uid(),
      updated_at = now()
  where request_id = p_request_id
    and is_active
    and status = 'DRAFT';

  return v_row;
end;
$$;

create or replace function plantlab_lab.advance_test_run(
  p_test_run_id uuid,
  p_next_status text,
  p_reason text default null
)
returns plantlab_lab.test_runs
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_lab.test_runs;
  v_request_item_id uuid;
  v_request_id uuid;
begin
  if p_next_status not in ('IN_PROGRESS', 'SUBMITTED', 'IN_REVIEW', 'CANCELLED') then
    raise exception 'Unsupported Test Run status for this function: %', p_next_status
      using errcode = '22023';
  end if;

  perform set_config('app.status_reason', coalesce(p_reason, ''), true);

  select tr.request_item_id, ri.request_id
    into v_request_item_id, v_request_id
  from plantlab_lab.test_runs tr
  join plantlab_lab.request_items ri on ri.id = tr.request_item_id
  where tr.id = p_test_run_id;

  update plantlab_lab.test_runs
  set status = p_next_status,
      status_reason = p_reason,
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_test_run_id
  returning * into v_row;

  if not found then
    raise exception 'Lab Test Run not found or not accessible'
      using errcode = 'P0002';
  end if;

  if p_next_status = 'IN_PROGRESS' then
    update plantlab_lab.request_items
    set status = 'TESTING',
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_request_item_id
      and status = 'READY';

    update plantlab_lab.requests
    set status = 'TESTING',
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_request_id
      and status = 'RECEIVED';
  elsif p_next_status = 'IN_REVIEW' then
    update plantlab_lab.request_items
    set status = 'IN_REVIEW',
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_request_item_id
      and status = 'TESTING';

    if not exists (
      select 1
      from plantlab_lab.request_items ri
      where ri.request_id = v_request_id
        and ri.is_active
        and ri.status not in ('IN_REVIEW', 'APPROVED', 'REJECTED', 'RETEST')
    ) then
      update plantlab_lab.requests
      set status = 'IN_REVIEW',
          updated_by = auth.uid(),
          updated_at = now()
      where id = v_request_id
        and status = 'TESTING';
    end if;
  end if;

  return v_row;
end;
$$;

create or replace function plantlab_lab.decide_test_run(
  p_test_run_id uuid,
  p_decision text,
  p_reason text default null,
  p_metadata jsonb default '{}'::jsonb
)
returns plantlab_lab.result_decisions
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_lab.result_decisions;
  v_request_item_id uuid;
  v_request_id uuid;
  v_item_status text;
  v_request_status text;
begin
  if p_decision not in ('APPROVE', 'REJECT', 'RETEST', 'REQUEST_REVISION') then
    raise exception 'Unsupported Lab decision: %', p_decision
      using errcode = '22023';
  end if;

  insert into plantlab_lab.result_decisions (
    test_run_id,
    decision,
    reviewer_id,
    reason,
    metadata
  ) values (
    p_test_run_id,
    p_decision,
    auth.uid(),
    p_reason,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning * into v_row;

  select tr.request_item_id, ri.request_id
    into v_request_item_id, v_request_id
  from plantlab_lab.test_runs tr
  join plantlab_lab.request_items ri on ri.id = tr.request_item_id
  where tr.id = p_test_run_id;

  v_item_status := case p_decision
    when 'APPROVE' then 'APPROVED'
    when 'RETEST' then 'RETEST'
    else 'REJECTED'
  end;
  v_request_status := v_item_status;

  perform set_config('app.status_reason', coalesce(p_reason, ''), true);

  update plantlab_lab.request_items
  set status = v_item_status,
      status_reason = p_reason,
      updated_by = auth.uid(),
      updated_at = now()
  where id = v_request_item_id
    and status = 'IN_REVIEW';

  if p_decision = 'APPROVE' then
    if not exists (
      select 1
      from plantlab_lab.request_items ri
      where ri.request_id = v_request_id
        and ri.is_active
        and ri.status <> 'APPROVED'
    ) then
      update plantlab_lab.requests
      set status = 'APPROVED',
          status_reason = p_reason,
          updated_by = auth.uid(),
          updated_at = now()
      where id = v_request_id
        and status = 'IN_REVIEW';
    end if;
  else
    update plantlab_lab.requests
    set status = v_request_status,
        status_reason = p_reason,
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_request_id
      and status = 'IN_REVIEW';
  end if;

  return v_row;
end;
$$;

create or replace function plantlab_lab.record_sample_receipt(
  p_request_sample_id uuid,
  p_decision text,
  p_received_quantity numeric default null,
  p_unit_code text default null,
  p_condition_notes text default null,
  p_rejection_reason text default null
)
returns plantlab_lab.sample_receipts
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_receipt plantlab_lab.sample_receipts;
  v_request_id uuid;
  v_sample_id uuid;
  v_receipt_status text;
  v_sample_status text;
begin
  if p_decision not in ('ACCEPT', 'HOLD', 'REJECT') then
    raise exception 'Unsupported Sample receipt decision: %', p_decision
      using errcode = '22023';
  end if;

  select rs.request_id, rs.sample_id
    into v_request_id, v_sample_id
  from plantlab_lab.request_samples rs
  where rs.id = p_request_sample_id;

  if not found then
    raise exception 'Lab Request Sample not found or not accessible'
      using errcode = 'P0002';
  end if;

  v_receipt_status := case p_decision
    when 'ACCEPT' then 'ACCEPTED'
    when 'HOLD' then 'HOLD'
    else 'REJECTED'
  end;
  v_sample_status := case p_decision
    when 'ACCEPT' then 'RECEIVED'
    when 'HOLD' then 'HOLD'
    else 'REJECTED'
  end;

  insert into plantlab_lab.sample_receipts (
    request_sample_id,
    received_by,
    received_quantity,
    unit_code,
    condition_notes,
    decision,
    status
  ) values (
    p_request_sample_id,
    auth.uid(),
    p_received_quantity,
    p_unit_code,
    p_condition_notes,
    'PENDING',
    'DRAFT'
  )
  returning * into v_receipt;

  perform set_config(
    'app.status_reason',
    coalesce(p_rejection_reason, p_condition_notes, ''),
    true
  );

  update plantlab_lab.sample_receipts
  set decision = p_decision,
      status = v_receipt_status,
      status_reason = coalesce(p_rejection_reason, p_condition_notes),
      rejection_reason = p_rejection_reason,
      updated_at = now()
  where id = v_receipt.id
  returning * into v_receipt;

  update plantlab_core.samples
  set status = v_sample_status,
      status_reason = coalesce(p_rejection_reason, p_condition_notes),
      received_at = case when p_decision = 'ACCEPT' then now() else received_at end,
      updated_by = auth.uid(),
      updated_at = now()
  where id = v_sample_id;

  if p_decision = 'ACCEPT' then
    update plantlab_plant.sample_dispatches
    set status = 'RECEIVED',
        delivered_at = coalesce(delivered_at, now()),
        updated_at = now()
    where lab_request_id = v_request_id
      and sample_id = v_sample_id
      and status in ('SENT', 'DELIVERED');

    update plantlab_lab.requests
    set status = 'RECEIVED',
        updated_by = auth.uid(),
        updated_at = now()
    where id = v_request_id
      and status = 'SENT';
  end if;

  insert into plantlab_lab.custody_events (
    sample_id,
    request_id,
    event_type,
    performed_by,
    condition_notes,
    reference_type,
    reference_key
  ) values (
    v_sample_id,
    v_request_id,
    case when p_decision = 'REJECT' then 'REJECTED' else 'RECEIVED' end,
    auth.uid(),
    p_condition_notes,
    'SAMPLE_RECEIPT',
    v_receipt.id::text
  );

  return v_receipt;
end;
$$;

