create or replace view plantlab_reporting.v_lot_end_to_end_status
with (security_invoker = true)
as
select
  l.id as lot_id,
  l.canonical_lot_code,
  l.lot_code,
  l.product_id,
  p.name as product_name,
  l.company_id,
  l.plant_site_id,
  l.status as lot_status,
  pp.id as latest_plan_id,
  pp.plan_code as latest_plan_code,
  pp.status as latest_plan_status,
  lr.id as latest_lab_request_id,
  lr.request_code as latest_lab_request_code,
  lr.status as latest_lab_request_status,
  lr.target_lab_site_id,
  coalesce(s.sample_count, 0) as sample_count,
  coalesce(oos.open_oos_count, 0) as open_oos_count,
  greatest(
    l.updated_at,
    coalesce(pp.updated_at, '-infinity'::timestamptz),
    coalesce(lr.updated_at, '-infinity'::timestamptz)
  ) as last_activity_at
from plantlab_core.lots l
join plantlab_master.products p on p.id = l.product_id
left join lateral (
  select x.id, x.plan_code, x.status, x.updated_at
  from plantlab_plant.process_plans x
  where x.lot_id = l.id
  order by x.created_at desc
  limit 1
) pp on true
left join lateral (
  select x.id, x.request_code, x.status, x.target_lab_site_id, x.updated_at
  from plantlab_lab.requests x
  where x.lot_id = l.id
  order by x.created_at desc
  limit 1
) lr on true
left join lateral (
  select count(*)::integer as sample_count
  from plantlab_core.samples x
  where x.lot_id = l.id
) s on true
left join lateral (
  select count(*)::integer as open_oos_count
  from plantlab_plant.nonconformances x
  where x.lot_id = l.id
    and x.status not in ('CLOSED', 'CANCELLED')
) oos on true;

create or replace view plantlab_reporting.v_plant_work_queue
with (security_invoker = true)
as
select
  'PROCESS_PLAN'::text as work_type,
  pp.id as work_id,
  pp.plan_code as work_code,
  pp.lot_id,
  pp.site_id,
  pp.status,
  pp.planned_start_at as due_or_schedule_at,
  null::uuid as assigned_to,
  pp.created_at
from plantlab_plant.process_plans pp
where pp.status in ('DRAFT', 'REGISTERED', 'ACTIVE', 'HOLD')
union all
select
  'PROCESS_STEP',
  ps.id,
  pp.plan_code || '/' || ps.sequence_no::text,
  pp.lot_id,
  pp.site_id,
  ps.status,
  ps.scheduled_start_at,
  ps.assigned_to,
  ps.created_at
from plantlab_plant.process_steps ps
join plantlab_plant.process_plans pp on pp.id = ps.plan_id
where ps.status in ('PENDING', 'READY', 'IN_PROGRESS', 'HOLD')
union all
select
  'INSPECTION',
  i.id,
  i.inspection_code,
  i.lot_id,
  l.plant_site_id,
  i.status,
  i.inspected_at,
  i.inspector_id,
  i.created_at
from plantlab_plant.inspections i
join plantlab_core.lots l on l.id = i.lot_id
where i.status in ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'NEED_REVISION', 'OOS')
union all
select
  'PLANT_TEST',
  t.id,
  t.test_code,
  t.lot_id,
  l.plant_site_id,
  t.status,
  t.tested_at,
  t.tested_by,
  t.created_at
from plantlab_plant.tests t
join plantlab_core.lots l on l.id = t.lot_id
where t.status in ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'FAILED', 'OOS', 'RETEST');

create or replace view plantlab_reporting.v_lab_work_queue
with (security_invoker = true)
as
select
  r.id as request_id,
  r.request_code,
  r.source_module,
  r.lot_id,
  r.product_id,
  r.target_lab_site_id,
  r.priority as request_priority,
  r.status as request_status,
  ri.id as request_item_id,
  tt.test_code,
  tt.test_name,
  ri.priority as item_priority,
  ri.status as item_status,
  coalesce(ri.due_at, r.due_at) as due_at,
  ta.id as assignment_id,
  ta.analyst_id,
  ta.status as assignment_status,
  tr.id as latest_test_run_id,
  tr.attempt_no as latest_attempt_no,
  tr.status as latest_test_run_status
from plantlab_lab.requests r
join plantlab_lab.request_items ri on ri.request_id = r.id and ri.is_active
join plantlab_lab.test_types tt on tt.id = ri.test_type_id
left join lateral (
  select x.id, x.analyst_id, x.status
  from plantlab_lab.test_assignments x
  where x.request_item_id = ri.id
    and x.status <> 'CANCELLED'
  order by x.assigned_at desc
  limit 1
) ta on true
left join lateral (
  select x.id, x.attempt_no, x.status
  from plantlab_lab.test_runs x
  where x.request_item_id = ri.id
  order by x.attempt_no desc
  limit 1
) tr on true
where r.status not in ('CLOSED', 'CANCELLED')
  and ri.status <> 'CANCELLED';

create or replace view plantlab_reporting.v_sample_chain_of_custody
with (security_invoker = true)
as
select
  s.id as sample_id,
  s.sample_code,
  s.lot_id,
  s.sample_type,
  s.source_module,
  s.status as sample_status,
  ce.id as custody_event_id,
  ce.event_type,
  ce.from_site_id,
  ce.to_site_id,
  ce.performed_by,
  ce.occurred_at,
  ce.condition_notes,
  ce.reference_type,
  ce.reference_key
from plantlab_core.samples s
left join plantlab_lab.custody_events ce on ce.sample_id = s.id;

create or replace view plantlab_reporting.v_lot_traceability
with (security_invoker = true)
as
select
  l.id as lot_id,
  l.canonical_lot_code,
  l.lot_code,
  ls.source_system,
  ls.source_entity,
  ls.source_record_key,
  ls.source_lot_code,
  null::uuid as related_lot_id,
  null::text as lineage_relationship,
  ls.created_at as linked_at
from plantlab_core.lots l
join plantlab_core.lot_sources ls on ls.lot_id = l.id
union all
select
  parent.id,
  parent.canonical_lot_code,
  parent.lot_code,
  'INTERNAL',
  'plantlab_core.lot_lineage',
  ll.id::text,
  null,
  child.id,
  ll.relationship_type,
  ll.created_at
from plantlab_core.lot_lineage ll
join plantlab_core.lots parent on parent.id = ll.parent_lot_id
join plantlab_core.lots child on child.id = ll.child_lot_id;

create or replace view plantlab_reporting.v_open_oos
with (security_invoker = true)
as
select
  'PLANT_TEST'::text as source_type,
  t.id::text as source_key,
  t.lot_id,
  t.test_type as test_or_parameter,
  t.numeric_value,
  t.unit_code,
  t.result,
  t.status,
  t.status_reason,
  t.created_at
from plantlab_plant.tests t
where t.result in ('FAIL', 'OOS')
  and t.status not in ('CLOSED', 'CANCELLED')
union all
select
  'LAB_RESULT',
  rv.id::text,
  r.lot_id,
  p.parameter_code,
  rv.numeric_value,
  rv.unit_code,
  rv.result,
  tr.status,
  tr.status_reason,
  rv.created_at
from plantlab_lab.result_values rv
join plantlab_lab.parameters p on p.id = rv.parameter_id
join plantlab_lab.test_runs tr on tr.id = rv.test_run_id
join plantlab_lab.request_items ri on ri.id = tr.request_item_id
join plantlab_lab.requests r on r.id = ri.request_id
where rv.result in ('FAIL', 'OOS')
  and tr.status not in ('APPROVED', 'CANCELLED');

grant select on
  plantlab_reporting.v_lot_end_to_end_status,
  plantlab_reporting.v_plant_work_queue,
  plantlab_reporting.v_lab_work_queue,
  plantlab_reporting.v_sample_chain_of_custody,
  plantlab_reporting.v_lot_traceability,
  plantlab_reporting.v_open_oos
to authenticated, service_role;
