create table plantlab_master.crop_categories (
  crop_category_code text primary key,
  crop_category_name text not null,
  description text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint crop_categories_code_format_ck check (
    crop_category_code = upper(crop_category_code)
    and crop_category_code ~ '^[A-Z][A-Z0-9_]*$'
  )
);

create table plantlab_master.seed_generations (
  seed_generation_code text primary key,
  seed_generation_name text not null,
  crop_category_code text not null
    references plantlab_master.crop_categories(crop_category_code) on update cascade on delete restrict,
  description text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint seed_generations_code_format_ck check (
    seed_generation_code = upper(seed_generation_code)
    and seed_generation_code ~ '^[A-Z][A-Z0-9_]*$'
  )
);

create table plantlab_master.flag_definitions (
  flag_code text primary key,
  flag_name text not null,
  flag_domain text not null,
  description text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint flag_definitions_code_format_ck check (
    flag_code = upper(flag_code)
    and flag_code ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint flag_definitions_domain_ck check (flag_domain in ('FIELD', 'PLANT'))
);

create table plantlab_master.flag_reasons (
  flag_reason_code text primary key,
  flag_code text not null
    references plantlab_master.flag_definitions(flag_code) on update cascade on delete restrict,
  flag_subcode text,
  flag_reason_name text not null,
  description text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint flag_reasons_code_format_ck check (
    flag_reason_code = upper(flag_reason_code)
    and flag_reason_code ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint flag_reasons_subcode_format_ck check (
    flag_subcode is null
    or (
      flag_subcode = upper(flag_subcode)
      and flag_subcode ~ '^[A-Z][A-Z0-9_]*$'
    )
  ),
  constraint flag_reasons_rf_subcode_ck check (
    (flag_code = 'RF' and flag_subcode in ('RFI', 'RFD'))
    or (flag_code <> 'RF' and flag_subcode is null)
  )
);

