create or replace function plantlab_core.normalize_identifier(p_value text)
returns text
language sql
immutable
strict
set search_path = ''
as $$
  select upper(regexp_replace(btrim(p_value), '[[:space:]]+', ' ', 'g'));
$$;

create table plantlab_core.lot_identifiers (
  id uuid primary key default gen_random_uuid(),
  lot_id uuid not null references plantlab_core.lots(id) on delete cascade,
  identifier_type text not null,
  identifier_value text not null,
  normalized_identifier text generated always as (
    plantlab_core.normalize_identifier(identifier_value)
  ) stored,
  source_system text not null,
  source_entity text,
  source_record_key text,
  is_primary boolean not null default false,
  valid_from timestamptz,
  valid_until timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  updated_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint lot_identifiers_value_ck check (nullif(btrim(identifier_value), '') is not null),
  constraint lot_identifiers_type_format_ck check (
    identifier_type = upper(identifier_type)
    and identifier_type ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint lot_identifiers_source_format_ck check (
    source_system = upper(source_system)
    and source_system ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint lot_identifiers_validity_ck check (
    valid_until is null or valid_from is null or valid_until > valid_from
  ),
  constraint lot_identifiers_metadata_object_ck check (jsonb_typeof(metadata) = 'object'),
  constraint lot_identifiers_lot_source_uq unique (
    lot_id,
    identifier_type,
    normalized_identifier,
    source_system
  )
);

create index lot_identifiers_lookup_idx
  on plantlab_core.lot_identifiers (source_system, identifier_type, normalized_identifier);
create unique index lot_identifiers_one_primary_uq
  on plantlab_core.lot_identifiers (lot_id, identifier_type)
  where is_primary and valid_until is null;

create table plantlab_core.lot_flags (
  id uuid primary key default gen_random_uuid(),
  lot_id uuid not null references plantlab_core.lots(id) on delete cascade,
  flag_code text not null
    references plantlab_master.flag_definitions(flag_code) on update cascade on delete restrict,
  flag_subcode text,
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  source_system text not null,
  source_record_key text,
  notes text,
  metadata jsonb not null default '{}'::jsonb,
  recorded_by uuid references plantlab_platform.identities(id) on delete set null,
  updated_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint lot_flags_subcode_ck check (
    (flag_code = 'RF' and flag_subcode in ('RFI', 'RFD'))
    or (flag_code <> 'RF' and flag_subcode is null)
  ),
  constraint lot_flags_timeline_ck check (ended_at is null or ended_at >= started_at),
  constraint lot_flags_source_format_ck check (
    source_system = upper(source_system)
    and source_system ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint lot_flags_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index lot_flags_lot_timeline_idx
  on plantlab_core.lot_flags (lot_id, started_at desc);
create index lot_flags_current_idx
  on plantlab_core.lot_flags (flag_code, lot_id)
  where ended_at is null;
create unique index lot_flags_source_record_uq
  on plantlab_core.lot_flags (source_system, source_record_key)
  where source_record_key is not null;

create table plantlab_core.lot_flag_reasons (
  lot_flag_id uuid not null references plantlab_core.lot_flags(id) on delete cascade,
  flag_reason_code text not null
    references plantlab_master.flag_reasons(flag_reason_code) on update cascade on delete restrict,
  details text,
  metadata jsonb not null default '{}'::jsonb,
  recorded_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint lot_flag_reasons_pkey primary key (lot_flag_id, flag_reason_code),
  constraint lot_flag_reasons_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create table plantlab_core.sample_lineage (
  id uuid primary key default gen_random_uuid(),
  parent_sample_id uuid not null references plantlab_core.samples(id) on delete restrict,
  child_sample_id uuid not null references plantlab_core.samples(id) on delete restrict,
  relationship_type text not null,
  occurred_at timestamptz not null default now(),
  reason text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint sample_lineage_relation_uq unique (
    parent_sample_id,
    child_sample_id,
    relationship_type
  ),
  constraint sample_lineage_not_self_ck check (parent_sample_id <> child_sample_id),
  constraint sample_lineage_type_ck check (
    relationship_type in ('RESAMPLE', 'SPLIT', 'RETAINED', 'REPLACEMENT')
  ),
  constraint sample_lineage_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index sample_lineage_child_idx on plantlab_core.sample_lineage (child_sample_id);

create table plantlab_integration.import_batches (
  id uuid primary key default gen_random_uuid(),
  source_type text not null,
  source_file_name text not null,
  source_file_sha256 text not null,
  source_file_size bigint,
  source_modified_at timestamptz,
  parser_version integer not null default 1,
  status text not null default 'REGISTERED',
  total_row_count integer not null default 0,
  validated_row_count integer not null default 0,
  mapped_row_count integer not null default 0,
  rejected_row_count integer not null default 0,
  started_at timestamptz,
  completed_at timestamptz,
  imported_by uuid references plantlab_platform.identities(id) on delete set null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint import_batches_file_version_uq unique (
    source_type,
    source_file_sha256,
    parser_version
  ),
  constraint import_batches_source_type_format_ck check (
    source_type = upper(source_type)
    and source_type ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint import_batches_filename_ck check (
    nullif(btrim(source_file_name), '') is not null
  ),
  constraint import_batches_sha256_ck check (
    source_file_sha256 = lower(source_file_sha256)
    and source_file_sha256 ~ '^[0-9a-f]{64}$'
  ),
  constraint import_batches_file_size_ck check (
    source_file_size is null or source_file_size >= 0
  ),
  constraint import_batches_parser_version_ck check (parser_version > 0),
  constraint import_batches_counts_ck check (
    total_row_count >= 0
    and validated_row_count between 0 and total_row_count
    and mapped_row_count between 0 and total_row_count
    and rejected_row_count between 0 and total_row_count
    and mapped_row_count + rejected_row_count <= total_row_count
  ),
  constraint import_batches_status_ck check (
    status in (
      'REGISTERED', 'STAGED', 'VALIDATING', 'VALIDATED', 'MAPPING',
      'PARTIALLY_MAPPED', 'COMPLETED', 'FAILED', 'CANCELLED'
    )
  ),
  constraint import_batches_timeline_ck check (
    (completed_at is null or started_at is null or completed_at >= started_at)
    and (status <> 'COMPLETED' or completed_at is not null)
  ),
  constraint import_batches_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index import_batches_status_idx
  on plantlab_integration.import_batches (status, created_at desc);

create table plantlab_integration.import_rows (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references plantlab_integration.import_batches(id) on delete cascade,
  sheet_name text not null,
  source_row_number integer not null,
  source_record_key text,
  row_sha256 text not null,
  raw_payload jsonb not null,
  normalized_payload jsonb not null default '{}'::jsonb,
  status text not null default 'RAW',
  target_schema text,
  target_entity text,
  target_record_key text,
  mapped_at timestamptz,
  mapped_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint import_rows_source_position_uq unique (
    batch_id,
    sheet_name,
    source_row_number
  ),
  constraint import_rows_sheet_ck check (nullif(btrim(sheet_name), '') is not null),
  constraint import_rows_row_number_ck check (source_row_number > 0),
  constraint import_rows_sha256_ck check (
    row_sha256 = lower(row_sha256)
    and row_sha256 ~ '^[0-9a-f]{64}$'
  ),
  constraint import_rows_payload_object_ck check (jsonb_typeof(raw_payload) = 'object'),
  constraint import_rows_normalized_object_ck check (
    jsonb_typeof(normalized_payload) = 'object'
  ),
  constraint import_rows_status_ck check (
    status in ('RAW', 'VALIDATED', 'MAPPED', 'REJECTED', 'SKIPPED')
  ),
  constraint import_rows_mapping_ck check (
    status <> 'MAPPED'
    or (
      target_schema is not null
      and target_entity is not null
      and target_record_key is not null
      and mapped_at is not null
    )
  )
);

create index import_rows_batch_status_idx
  on plantlab_integration.import_rows (batch_id, status, source_row_number);
create index import_rows_source_key_idx
  on plantlab_integration.import_rows (batch_id, source_record_key)
  where source_record_key is not null;
create index import_rows_target_idx
  on plantlab_integration.import_rows (target_schema, target_entity, target_record_key)
  where status = 'MAPPED';

create table plantlab_integration.import_issues (
  id bigint generated always as identity primary key,
  batch_id uuid not null references plantlab_integration.import_batches(id) on delete cascade,
  import_row_id uuid references plantlab_integration.import_rows(id) on delete cascade,
  severity text not null default 'ERROR',
  issue_code text not null,
  column_name text,
  source_value jsonb,
  message text not null,
  status text not null default 'OPEN',
  resolution text,
  resolved_by uuid references plantlab_platform.identities(id) on delete set null,
  resolved_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint import_issues_severity_ck check (
    severity in ('INFO', 'WARNING', 'ERROR', 'BLOCKING')
  ),
  constraint import_issues_code_format_ck check (
    issue_code = upper(issue_code)
    and issue_code ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint import_issues_status_ck check (
    status in ('OPEN', 'RESOLVED', 'WAIVED')
  ),
  constraint import_issues_resolution_ck check (
    (status = 'OPEN' and resolved_at is null)
    or (
      status in ('RESOLVED', 'WAIVED')
      and resolved_at is not null
      and nullif(btrim(resolution), '') is not null
    )
  ),
  constraint import_issues_message_ck check (nullif(btrim(message), '') is not null),
  constraint import_issues_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index import_issues_queue_idx
  on plantlab_integration.import_issues (batch_id, status, severity, created_at);
create index import_issues_row_idx
  on plantlab_integration.import_issues (import_row_id, status)
  where import_row_id is not null;

create or replace function plantlab_core.validate_lot_flag_reason()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event_flag_code text;
  v_event_flag_subcode text;
  v_reason_flag_code text;
  v_reason_flag_subcode text;
begin
  select lf.flag_code, lf.flag_subcode
    into v_event_flag_code, v_event_flag_subcode
  from plantlab_core.lot_flags lf
  where lf.id = new.lot_flag_id;

  if not found then
    raise exception 'Lot flag % does not exist', new.lot_flag_id
      using errcode = '23503';
  end if;

  select fr.flag_code, fr.flag_subcode
    into v_reason_flag_code, v_reason_flag_subcode
  from plantlab_master.flag_reasons fr
  where fr.flag_reason_code = new.flag_reason_code
    and fr.is_active;

  if not found then
    raise exception 'Flag reason % is missing or inactive', new.flag_reason_code
      using errcode = '23514';
  end if;

  if v_reason_flag_code <> v_event_flag_code
    or v_reason_flag_subcode is distinct from v_event_flag_subcode then
    raise exception 'Flag reason % is not valid for flag %/%',
      new.flag_reason_code,
      v_event_flag_code,
      coalesce(v_event_flag_subcode, '-')
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_platform.can_access_core_lot_flag(
  p_lot_flag_id uuid,
  p_permission text
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(plantlab_platform.can_access_core_lot(lf.lot_id, p_permission), false)
  from plantlab_core.lot_flags lf
  where lf.id = p_lot_flag_id;
$$;

create trigger crop_categories_set_updated_at
before update on plantlab_master.crop_categories
for each row execute function plantlab_platform.set_updated_at();
create trigger seed_generations_set_updated_at
before update on plantlab_master.seed_generations
for each row execute function plantlab_platform.set_updated_at();
create trigger flag_definitions_set_updated_at
before update on plantlab_master.flag_definitions
for each row execute function plantlab_platform.set_updated_at();
create trigger flag_reasons_set_updated_at
before update on plantlab_master.flag_reasons
for each row execute function plantlab_platform.set_updated_at();
create trigger lot_identifiers_set_updated_at
before update on plantlab_core.lot_identifiers
for each row execute function plantlab_platform.set_updated_at();
create trigger lot_flags_set_updated_at
before update on plantlab_core.lot_flags
for each row execute function plantlab_platform.set_updated_at();
create trigger lot_flag_reasons_validate
before insert or update on plantlab_core.lot_flag_reasons
for each row execute function plantlab_core.validate_lot_flag_reason();
create trigger import_batches_set_updated_at
before update on plantlab_integration.import_batches
for each row execute function plantlab_platform.set_updated_at();
create trigger import_rows_set_updated_at
before update on plantlab_integration.import_rows
for each row execute function plantlab_platform.set_updated_at();
create trigger import_issues_set_updated_at
before update on plantlab_integration.import_issues
for each row execute function plantlab_platform.set_updated_at();

alter table plantlab_master.crop_categories enable row level security;
alter table plantlab_master.seed_generations enable row level security;
alter table plantlab_master.flag_definitions enable row level security;
alter table plantlab_master.flag_reasons enable row level security;
alter table plantlab_core.lot_identifiers enable row level security;
alter table plantlab_core.lot_flags enable row level security;
alter table plantlab_core.lot_flag_reasons enable row level security;
alter table plantlab_core.sample_lineage enable row level security;
alter table plantlab_integration.import_batches enable row level security;
alter table plantlab_integration.import_rows enable row level security;
alter table plantlab_integration.import_issues enable row level security;

revoke all on table
  plantlab_master.crop_categories,
  plantlab_master.seed_generations,
  plantlab_master.flag_definitions,
  plantlab_master.flag_reasons,
  plantlab_core.lot_identifiers,
  plantlab_core.lot_flags,
  plantlab_core.lot_flag_reasons,
  plantlab_core.sample_lineage,
  plantlab_integration.import_batches,
  plantlab_integration.import_rows,
  plantlab_integration.import_issues
from anon;

grant select, insert, update, delete on table
  plantlab_master.crop_categories,
  plantlab_master.seed_generations,
  plantlab_master.flag_definitions,
  plantlab_master.flag_reasons
to authenticated, service_role;

grant select, insert, update on table
  plantlab_core.lot_identifiers,
  plantlab_core.lot_flags,
  plantlab_core.lot_flag_reasons,
  plantlab_core.sample_lineage
to authenticated, service_role;

revoke all on table
  plantlab_integration.import_batches,
  plantlab_integration.import_rows,
  plantlab_integration.import_issues
from authenticated;
grant select, insert, update, delete on table
  plantlab_integration.import_batches,
  plantlab_integration.import_rows,
  plantlab_integration.import_issues
to service_role;
grant usage, select on sequence plantlab_integration.import_issues_id_seq to service_role;

revoke all on function plantlab_core.normalize_identifier(text) from PUBLIC, anon;
revoke all on function plantlab_core.validate_lot_flag_reason() from PUBLIC, anon, authenticated;
revoke all on function plantlab_platform.can_access_core_lot_flag(uuid, text) from PUBLIC, anon;
grant execute on function plantlab_core.normalize_identifier(text) to authenticated, service_role;
grant execute on function plantlab_core.validate_lot_flag_reason() to service_role;
grant execute on function plantlab_platform.can_access_core_lot_flag(uuid, text)
  to authenticated, service_role;

create policy crop_categories_select on plantlab_master.crop_categories
for select to authenticated using (plantlab_platform.is_active_user());
create policy crop_categories_manage on plantlab_master.crop_categories
for all to authenticated
using (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'))
with check (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'));

create policy seed_generations_select on plantlab_master.seed_generations
for select to authenticated using (plantlab_platform.is_active_user());
create policy seed_generations_manage on plantlab_master.seed_generations
for all to authenticated
using (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'))
with check (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'));

create policy flag_definitions_select on plantlab_master.flag_definitions
for select to authenticated using (plantlab_platform.is_active_user());
create policy flag_definitions_manage on plantlab_master.flag_definitions
for all to authenticated
using (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'))
with check (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'));

create policy flag_reasons_select on plantlab_master.flag_reasons
for select to authenticated using (plantlab_platform.is_active_user());
create policy flag_reasons_manage on plantlab_master.flag_reasons
for all to authenticated
using (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'))
with check (plantlab_platform.has_module_permission('PLATFORM', 'plantlab_master.write'));

create policy lot_identifiers_select on plantlab_core.lot_identifiers
for select to authenticated
using (plantlab_platform.can_access_core_lot(lot_id, 'lot.read'));
create policy lot_identifiers_insert on plantlab_core.lot_identifiers
for insert to authenticated
with check (
  created_by = auth.uid()
  and plantlab_platform.can_access_core_lot(lot_id, 'lot.write')
);
create policy lot_identifiers_update on plantlab_core.lot_identifiers
for update to authenticated
using (plantlab_platform.can_access_core_lot(lot_id, 'lot.write'))
with check (
  updated_by = auth.uid()
  and plantlab_platform.can_access_core_lot(lot_id, 'lot.write')
);

create policy lot_flags_select on plantlab_core.lot_flags
for select to authenticated
using (plantlab_platform.can_access_core_lot(lot_id, 'lot.read'));
create policy lot_flags_insert on plantlab_core.lot_flags
for insert to authenticated
with check (
  recorded_by = auth.uid()
  and plantlab_platform.can_access_core_lot(lot_id, 'lot.write')
);
create policy lot_flags_update on plantlab_core.lot_flags
for update to authenticated
using (plantlab_platform.can_access_core_lot(lot_id, 'lot.write'))
with check (
  updated_by = auth.uid()
  and plantlab_platform.can_access_core_lot(lot_id, 'lot.write')
);

create policy lot_flag_reasons_select on plantlab_core.lot_flag_reasons
for select to authenticated
using (plantlab_platform.can_access_core_lot_flag(lot_flag_id, 'lot.read'));
create policy lot_flag_reasons_insert on plantlab_core.lot_flag_reasons
for insert to authenticated
with check (
  recorded_by = auth.uid()
  and plantlab_platform.can_access_core_lot_flag(lot_flag_id, 'lot.write')
);

create policy sample_lineage_select on plantlab_core.sample_lineage
for select to authenticated
using (
  plantlab_platform.can_access_core_sample(parent_sample_id, 'sample.read')
  and plantlab_platform.can_access_core_sample(child_sample_id, 'sample.read')
);
create policy sample_lineage_insert on plantlab_core.sample_lineage
for insert to authenticated
with check (
  created_by = auth.uid()
  and plantlab_platform.can_access_core_sample(parent_sample_id, 'sample.write')
  and plantlab_platform.can_access_core_sample(child_sample_id, 'sample.write')
);

comment on table plantlab_integration.import_batches is
  'Service-role-only registry for idempotent legacy workbook ingestion.';
comment on table plantlab_integration.import_rows is
  'Service-role-only raw and normalized source rows; canonical tables remain the source of truth.';
comment on table plantlab_integration.import_issues is
  'Service-role-only reconciliation queue for duplicate, mapping, formula, and validation issues.';
comment on table plantlab_core.lot_flags is
  'Versioned Lot flag events. Multiple reasons are stored in plantlab_core.lot_flag_reasons.';
-- Canonical source: 20260812000200_plant_manual_forms_and_measurements.sql
set local lock_timeout = '5s';
set local statement_timeout = '2min';

-- Migration 015: Plant input model for web/Android based on the audited
-- DB Plant Inspector workbook. This migration is additive and imports no
-- historical transaction rows.

create table plantlab_plant.measurement_definitions (
  measurement_code text primary key,
  measurement_name text not null,
  data_type text not null,
  default_unit_code text,
  decimal_scale integer,
  description text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint measurement_definitions_code_format_ck check (
    measurement_code = upper(measurement_code)
    and measurement_code ~ '^[A-Z][A-Z0-9_]*$'
  ),
  constraint measurement_definitions_data_type_ck check (
    data_type in ('NUMERIC', 'TEXT', 'BOOLEAN')
  ),
  constraint measurement_definitions_scale_ck check (
    decimal_scale is null or decimal_scale between 0 and 12
  )
);

create table plantlab_plant.scope_inspections (
  id uuid primary key default gen_random_uuid(),
  inspection_code text not null default (
    'SINS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 20))
  ),
  site_id uuid not null references plantlab_master.sites(id) on delete restrict,
  company_id bigint references plantlab_master.companies(id) on delete restrict,
  process_type_id uuid not null references plantlab_plant.process_types(id) on delete restrict,
  form_template_id uuid not null references plantlab_plant.form_templates(id) on delete restrict,
  scope_type text not null,
  subject_code text,
  subject_name text,
  inspector_id uuid references plantlab_platform.identities(id) on delete set null,
  inspected_at timestamptz,
  answers jsonb not null default '{}'::jsonb,
  result text not null default 'PENDING',
  status text not null default 'DRAFT',
  status_reason text,
  submitted_at timestamptz,
  reviewed_by uuid references plantlab_platform.identities(id) on delete set null,
  reviewed_at timestamptz,
  revision_of_id uuid references plantlab_plant.scope_inspections(id) on delete restrict,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  updated_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint scope_inspections_code_uq unique (inspection_code),
  constraint scope_inspections_scope_type_ck check (
    scope_type in ('SITE', 'WAREHOUSE', 'AREA', 'MATERIAL', 'EQUIPMENT')
  ),
  constraint scope_inspections_subject_ck check (
    scope_type in ('SITE', 'WAREHOUSE')
    or nullif(btrim(subject_code), '') is not null
    or nullif(btrim(subject_name), '') is not null
  ),
  constraint scope_inspections_answers_object_ck check (jsonb_typeof(answers) = 'object'),
  constraint scope_inspections_result_ck check (
    result in ('PENDING', 'PASS', 'FAIL', 'OOS', 'NA')
  ),
  constraint scope_inspections_status_ck check (
    status in (
      'DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'PASSED', 'OOS',
      'NEED_REVISION', 'CLOSED', 'CANCELLED'
    )
  ),
  constraint scope_inspections_pass_result_ck check (
    status <> 'PASSED' or result = 'PASS'
  ),
  constraint scope_inspections_oos_result_ck check (
    status <> 'OOS' or result in ('FAIL', 'OOS')
  ),
  constraint scope_inspections_review_ck check (
    (reviewed_at is null and reviewed_by is null)
    or (reviewed_at is not null and reviewed_by is not null)
  )
);

create index scope_inspections_queue_idx
  on plantlab_plant.scope_inspections (site_id, status, inspected_at desc);
create index scope_inspections_subject_idx
  on plantlab_plant.scope_inspections (scope_type, subject_code, created_at desc)
  where subject_code is not null;

create table plantlab_plant.process_measurements (
  id uuid primary key default gen_random_uuid(),
  process_step_id uuid references plantlab_plant.process_steps(id) on delete cascade,
  inspection_id uuid references plantlab_plant.inspections(id) on delete cascade,
  scope_inspection_id uuid references plantlab_plant.scope_inspections(id) on delete cascade,
  measurement_code text not null
    references plantlab_plant.measurement_definitions(measurement_code)
    on update cascade on delete restrict,
  sequence_no integer not null default 1,
  numeric_value numeric,
  text_value text,
  boolean_value boolean,
  unit_code text,
  measured_at timestamptz not null default now(),
  measured_by uuid references plantlab_platform.identities(id) on delete set null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint process_measurements_one_parent_ck check (
    num_nonnulls(process_step_id, inspection_id, scope_inspection_id) = 1
  ),
  constraint process_measurements_one_value_ck check (
    num_nonnulls(numeric_value, text_value, boolean_value) = 1
  ),
  constraint process_measurements_sequence_ck check (sequence_no > 0),
  constraint process_measurements_metadata_object_ck check (
    jsonb_typeof(metadata) = 'object'
  )
);

create unique index process_measurements_parent_parameter_uq
  on plantlab_plant.process_measurements (
    coalesce(process_step_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(inspection_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(scope_inspection_id, '00000000-0000-0000-0000-000000000000'::uuid),
    measurement_code,
    sequence_no
  );
create index process_measurements_step_idx
  on plantlab_plant.process_measurements (process_step_id, measurement_code)
  where process_step_id is not null;
create index process_measurements_inspection_idx
  on plantlab_plant.process_measurements (inspection_id, measurement_code)
  where inspection_id is not null;
create index process_measurements_scope_idx
  on plantlab_plant.process_measurements (scope_inspection_id, measurement_code)
  where scope_inspection_id is not null;

create table plantlab_plant.test_result_values (
  id uuid primary key default gen_random_uuid(),
  plant_test_id uuid not null references plantlab_plant.tests(id) on delete cascade,
  parameter_id uuid not null references plantlab_lab.parameters(id) on delete restrict,
  numeric_value numeric,
  text_value text,
  boolean_value boolean,
  unit_code text,
  lower_spec_snapshot numeric,
  upper_spec_snapshot numeric,
  result text not null default 'PENDING_REVIEW',
  remarks text,
  recorded_by uuid references plantlab_platform.identities(id) on delete set null,
  recorded_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint plant_test_result_values_test_parameter_uq unique (
    plant_test_id,
    parameter_id
  ),
  constraint plant_test_result_values_one_value_ck check (
    num_nonnulls(numeric_value, text_value, boolean_value) = 1
  ),
  constraint plant_test_result_values_spec_range_ck check (
    lower_spec_snapshot is null
    or upper_spec_snapshot is null
    or upper_spec_snapshot >= lower_spec_snapshot
  ),
  constraint plant_test_result_values_result_ck check (
    result in ('PENDING_REVIEW', 'PASS', 'FAIL', 'OOS', 'NA')
  )
);

create index plant_test_result_values_parameter_idx
  on plantlab_plant.test_result_values (parameter_id, recorded_at desc);

insert into plantlab_plant.measurement_definitions (
  measurement_code,
  measurement_name,
  data_type,
  default_unit_code,
  decimal_scale,
  description
)
values
  ('WAITING_TIME_HOURS', 'Waiting Time', 'NUMERIC', 'HOUR', 2, 'Elapsed waiting time in hours.'),
  ('MANPOWER_PER_TABLE', 'Manpower per Sorting Table', 'NUMERIC', 'PERSON', 0, 'Sorting manpower per table.'),
  ('SORTING_ACCURACY_PERCENT', 'Sorting Accuracy', 'NUMERIC', 'PERCENT', 2, 'Sorting accuracy percentage.'),
  ('BATCH_QUANTITY_KG', 'Batch Quantity', 'NUMERIC', 'KG', 3, 'Batch, feeding, or net-bin quantity.'),
  ('TEMPERATURE_C', 'Temperature', 'NUMERIC', 'CELSIUS', 2, 'Observed temperature in degrees Celsius.'),
  ('MOISTURE_PERCENT', 'Moisture Content', 'NUMERIC', 'PERCENT', 2, 'Observed moisture content.'),
  ('DRYING_TIME_HOURS', 'Drying Time', 'NUMERIC', 'HOUR', 2, 'Drying duration in hours.'),
  ('SHELLING_WAIT_HOURS', 'Waiting to Shelling', 'NUMERIC', 'HOUR', 2, 'Waiting time before shelling.'),
  ('PACKAGE_WEIGHT_GRAM', 'Package Weight', 'NUMERIC', 'GRAM', 3, 'Finished package weight.'),
  ('HUMIDITY_PERCENT', 'Relative Humidity', 'NUMERIC', 'PERCENT', 2, 'Observed relative humidity.'),
  ('BIN_NUMBER', 'Bin Number', 'TEXT', null, null, 'Bin identity/reference.'),
  ('DRIER_TYPE', 'Drier Type', 'TEXT', null, null, 'Selected drier type.')
on conflict (measurement_code) do update
set measurement_name = excluded.measurement_name,
    data_type = excluded.data_type,
    default_unit_code = excluded.default_unit_code,
    decimal_scale = excluded.decimal_scale,
    description = excluded.description,
    is_active = true,
    updated_at = now();

insert into plantlab_lab.parameters (
  parameter_code,
  parameter_name,
  description,
  data_type,
  default_unit_code,
  decimal_scale,
  is_active
)
values
  ('WORKING_SAMPLE_GRAM', 'Working Sample', 'PP working sample weight.', 'NUMERIC', 'GRAM', 3, true),
  ('PURE_SEED_GRAM', 'Pure Seed', 'PP pure seed component weight.', 'NUMERIC', 'GRAM', 3, true),
  ('INERT_MATTER_GRAM', 'Inert Matter', 'PP inert matter component weight.', 'NUMERIC', 'GRAM', 3, true),
  ('FUNGI_GRAM', 'Fungi', 'PP fungi component weight.', 'NUMERIC', 'GRAM', 3, true),
  ('DAMAGE_GRAM', 'Damage', 'PP damaged seed component weight.', 'NUMERIC', 'GRAM', 3, true),
  ('PREGERM_GRAM', 'Pregerm', 'PP pregerm component weight.', 'NUMERIC', 'GRAM', 3, true),
  ('SMALL_SEED_GRAM', 'Small Seed', 'PP small-seed component weight.', 'NUMERIC', 'GRAM', 3, true),
  ('OTHER_SEED_GRAM', 'Other Seed', 'PP other-seed component weight.', 'NUMERIC', 'GRAM', 3, true),
  ('TOTAL_COMPONENT_GRAM', 'Total Component', 'PP total component weight.', 'NUMERIC', 'GRAM', 3, true)
on conflict (parameter_code) do update
set parameter_name = excluded.parameter_name,
    description = excluded.description,
    data_type = excluded.data_type,
    default_unit_code = excluded.default_unit_code,
    decimal_scale = excluded.decimal_scale,
    is_active = true,
    updated_at = now();

insert into plantlab_lab.test_type_parameters (
  test_type_id,
  parameter_id,
  sequence_no,
  is_required,
  is_critical
)
select
  tt.id,
  p.id,
  x.sequence_no,
  false,
  false
from (
  values
    ('WORKING_SAMPLE_GRAM', 10),
    ('PURE_SEED_GRAM', 11),
    ('INERT_MATTER_GRAM', 12),
    ('FUNGI_GRAM', 13),
    ('DAMAGE_GRAM', 14),
    ('PREGERM_GRAM', 15),
    ('SMALL_SEED_GRAM', 16),
    ('OTHER_SEED_GRAM', 17),
    ('TOTAL_COMPONENT_GRAM', 18)
) as x(parameter_code, sequence_no)
join plantlab_lab.test_types tt on tt.test_code = 'PP'
join plantlab_lab.parameters p on p.parameter_code = x.parameter_code
on conflict (test_type_id, parameter_id) do update
set sequence_no = excluded.sequence_no,
    is_required = excluded.is_required,
    is_critical = excluded.is_critical;

update plantlab_plant.process_types
set requires_plan = false,
    process_name = case process_code
      when 'NON_SEED' then 'Non-Seed Inspection'
      else process_name
    end,
    updated_at = now()
where process_code in ('RECEIVING', 'INTAKE', 'WAREHOUSE_INSPECTION', 'NON_SEED');

