insert into plantlab_plant.form_templates (
  template_code,
  template_name,
  process_type_id,
  version,
  field_schema,
  validation_rules,
  effective_from,
  is_active
)
select
  ts.template_code,
  ts.template_name,
  pt.id,
  1,
  ts.field_schema,
  ts.validation_rules,
  date '2026-08-12',
  true
from template_seed ts
join plantlab_plant.process_types pt on pt.process_code = ts.process_code
on conflict (template_code, version) do update
set template_name = excluded.template_name,
    process_type_id = excluded.process_type_id,
    field_schema = excluded.field_schema,
    validation_rules = excluded.validation_rules,
    effective_from = excluded.effective_from,
    effective_until = null,
    is_active = true,
    updated_at = now();

create or replace function plantlab_plant.validate_scope_inspection_identity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_site_type text;
  v_site_company_id bigint;
  v_template_process_type_id uuid;
begin
  select s.site_type, s.company_id
    into v_site_type, v_site_company_id
  from plantlab_master.sites s
  where s.id = new.site_id;

  if not found or v_site_type not in ('PLANT', 'WAREHOUSE', 'TOLLER') then
    raise exception 'Scope inspection site must have type PLANT, WAREHOUSE, or TOLLER'
      using errcode = '23514';
  end if;

  if new.company_id is null then
    new.company_id := v_site_company_id;
  elsif v_site_company_id is not null and new.company_id <> v_site_company_id then
    raise exception 'Scope inspection company does not match the selected site'
      using errcode = '23514';
  end if;

  select ft.process_type_id
    into v_template_process_type_id
  from plantlab_plant.form_templates ft
  where ft.id = new.form_template_id
    and ft.is_active;

  if not found or v_template_process_type_id <> new.process_type_id then
    raise exception 'Scope inspection form template is inactive or belongs to another process type'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_plant.validate_scope_inspection_submission()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'SUBMITTED' and old.status is distinct from new.status then
    if new.answers = '{}'::jsonb then
      raise exception 'Scope inspection answers are required before submission'
        using errcode = '23514';
    end if;

    new.inspector_id := coalesce(new.inspector_id, auth.uid());
    new.inspected_at := coalesce(new.inspected_at, now());
    new.submitted_at := coalesce(new.submitted_at, now());
  end if;

  return new;
end;
$$;

create or replace function plantlab_plant.ensure_process_measurement_editable()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row plantlab_plant.process_measurements;
  v_status text;
begin
  if tg_op = 'DELETE' then
    v_row := old;
  else
    v_row := new;
  end if;

  if v_row.inspection_id is not null then
    select i.status into v_status
    from plantlab_plant.inspections i
    where i.id = v_row.inspection_id;

    if v_status <> 'DRAFT' then
      raise exception 'Measurements can only be changed while the Plant inspection is DRAFT'
        using errcode = '55000';
    end if;
  elsif v_row.scope_inspection_id is not null then
    select si.status into v_status
    from plantlab_plant.scope_inspections si
    where si.id = v_row.scope_inspection_id;

    if v_status <> 'DRAFT' then
      raise exception 'Measurements can only be changed while the scope inspection is DRAFT'
        using errcode = '55000';
    end if;
  else
    select ps.status into v_status
    from plantlab_plant.process_steps ps
    where ps.id = v_row.process_step_id;

    if v_status in ('COMPLETED', 'CANCELLED') then
      raise exception 'Measurements cannot be changed after the process step is completed/cancelled'
        using errcode = '55000';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;

create or replace function plantlab_plant.ensure_test_result_value_editable()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row plantlab_plant.test_result_values;
  v_status text;
begin
  if tg_op = 'DELETE' then
    v_row := old;
  else
    v_row := new;
  end if;

  select t.status into v_status
  from plantlab_plant.tests t
  where t.id = v_row.plant_test_id;

  if v_status <> 'DRAFT' then
    raise exception 'Plant test component values can only be changed while the test is DRAFT'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;

create or replace function plantlab_plant.validate_process_measurement_value()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_data_type text;
  v_default_unit_code text;
begin
  select md.data_type, md.default_unit_code
    into v_data_type, v_default_unit_code
  from plantlab_plant.measurement_definitions md
  where md.measurement_code = new.measurement_code
    and md.is_active;

  if not found then
    raise exception 'Plant measurement definition % is missing or inactive', new.measurement_code
      using errcode = '23514';
  end if;

  if (v_data_type = 'NUMERIC' and new.numeric_value is null)
    or (v_data_type = 'TEXT' and new.text_value is null)
    or (v_data_type = 'BOOLEAN' and new.boolean_value is null) then
    raise exception 'Typed value does not match Plant measurement data type %', v_data_type
      using errcode = '23514';
  end if;

  new.unit_code := coalesce(new.unit_code, v_default_unit_code);
  return new;
end;
$$;

create or replace function plantlab_plant.validate_test_result_value()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_data_type text;
  v_default_unit_code text;
  v_test_type_id uuid;
begin
  select p.data_type, p.default_unit_code, tt.id
    into v_data_type, v_default_unit_code, v_test_type_id
  from plantlab_lab.parameters p
  join plantlab_plant.tests t on t.id = new.plant_test_id
  join plantlab_lab.test_types tt on tt.test_code = t.test_type
  where p.id = new.parameter_id
    and p.is_active
    and tt.is_active;

  if not found then
    raise exception 'Plant test type or result parameter is missing/inactive'
      using errcode = '23514';
  end if;

  if not exists (
    select 1
    from plantlab_lab.test_type_parameters ttp
    where ttp.test_type_id = v_test_type_id
      and ttp.parameter_id = new.parameter_id
  ) then
    raise exception 'Parameter is not configured for Plant test type'
      using errcode = '23514';
  end if;

  if (v_data_type = 'NUMERIC' and new.numeric_value is null)
    or (v_data_type = 'TEXT' and new.text_value is null)
    or (v_data_type = 'BOOLEAN' and new.boolean_value is null) then
    raise exception 'Typed value does not match Plant test parameter data type %', v_data_type
      using errcode = '23514';
  end if;

  new.unit_code := coalesce(new.unit_code, v_default_unit_code);

  if new.numeric_value is not null
    and (new.lower_spec_snapshot is not null or new.upper_spec_snapshot is not null) then
    new.result := case
      when new.lower_spec_snapshot is not null
        and new.numeric_value < new.lower_spec_snapshot then 'OOS'
      when new.upper_spec_snapshot is not null
        and new.numeric_value > new.upper_spec_snapshot then 'OOS'
      else 'PASS'
    end;
  else
    new.result := 'PENDING_REVIEW';
  end if;

  return new;
end;
$$;

create or replace function plantlab_platform.can_access_plant_scope_inspection(
  p_scope_inspection_id uuid,
  p_permission text
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    plantlab_platform.has_permission('PLANT', p_permission, si.site_id, si.company_id),
    false
  )
  from plantlab_plant.scope_inspections si
  where si.id = p_scope_inspection_id;
$$;

create or replace function plantlab_platform.can_access_plant_test(
  p_plant_test_id uuid,
  p_permission text
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(plantlab_platform.can_access_plant_lot(t.lot_id, p_permission), false)
  from plantlab_plant.tests t
  where t.id = p_plant_test_id;
$$;

create or replace function plantlab_platform.can_access_process_measurement(
  p_process_step_id uuid,
  p_inspection_id uuid,
  p_scope_inspection_id uuid,
  p_permission text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_plan_id uuid;
  v_lot_id uuid;
begin
  if num_nonnulls(p_process_step_id, p_inspection_id, p_scope_inspection_id) <> 1 then
    return false;
  end if;

  if p_process_step_id is not null then
    select ps.plan_id into v_plan_id
    from plantlab_plant.process_steps ps
    where ps.id = p_process_step_id;
    return coalesce(plantlab_platform.can_access_plant_plan(v_plan_id, p_permission), false);
  end if;

  if p_inspection_id is not null then
    select i.lot_id into v_lot_id
    from plantlab_plant.inspections i
    where i.id = p_inspection_id;
    return coalesce(plantlab_platform.can_access_plant_lot(v_lot_id, p_permission), false);
  end if;

  return coalesce(
    plantlab_platform.can_access_plant_scope_inspection(p_scope_inspection_id, p_permission),
    false
  );
end;
$$;

create or replace function plantlab_plant.submit_scope_inspection(p_scope_inspection_id uuid)
returns plantlab_plant.scope_inspections
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_plant.scope_inspections;
begin
  update plantlab_plant.scope_inspections
  set status = 'SUBMITTED',
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_scope_inspection_id
    and status = 'DRAFT'
  returning * into v_row;

  if not found then
    raise exception 'Scope inspection not found, not accessible, or not in DRAFT status'
      using errcode = 'P0002';
  end if;

  return v_row;
end;
$$;

insert into plantlab_platform.status_transitions (
  module_code,
  entity_type,
  from_status,
  to_status,
  requires_reason
)
values
  ('PLANT', 'SCOPE_INSPECTION', 'DRAFT', 'SUBMITTED', false),
  ('PLANT', 'SCOPE_INSPECTION', 'DRAFT', 'CANCELLED', true),
  ('PLANT', 'SCOPE_INSPECTION', 'SUBMITTED', 'UNDER_REVIEW', false),
  ('PLANT', 'SCOPE_INSPECTION', 'SUBMITTED', 'NEED_REVISION', true),
  ('PLANT', 'SCOPE_INSPECTION', 'UNDER_REVIEW', 'PASSED', false),
  ('PLANT', 'SCOPE_INSPECTION', 'UNDER_REVIEW', 'OOS', true),
  ('PLANT', 'SCOPE_INSPECTION', 'UNDER_REVIEW', 'NEED_REVISION', true),
  ('PLANT', 'SCOPE_INSPECTION', 'NEED_REVISION', 'DRAFT', true),
  ('PLANT', 'SCOPE_INSPECTION', 'PASSED', 'CLOSED', false),
  ('PLANT', 'SCOPE_INSPECTION', 'OOS', 'CLOSED', true)
on conflict do nothing;

create trigger measurement_definitions_set_updated_at
before update on plantlab_plant.measurement_definitions
for each row execute function plantlab_platform.set_updated_at();
create trigger scope_inspections_set_updated_at
before update on plantlab_plant.scope_inspections
for each row execute function plantlab_platform.set_updated_at();
create trigger process_measurements_set_updated_at
before update on plantlab_plant.process_measurements
for each row execute function plantlab_platform.set_updated_at();
create trigger plant_test_result_values_set_updated_at
before update on plantlab_plant.test_result_values
for each row execute function plantlab_platform.set_updated_at();

create trigger a0_scope_inspections_initial_status
before insert on plantlab_plant.scope_inspections
for each row execute function plantlab_platform.enforce_initial_status('DRAFT');
create trigger a_scope_inspections_identity_insert
before insert on plantlab_plant.scope_inspections
for each row execute function plantlab_plant.validate_scope_inspection_identity();
create trigger a_scope_inspections_identity_update
before update of site_id, company_id, process_type_id, form_template_id
on plantlab_plant.scope_inspections
for each row execute function plantlab_plant.validate_scope_inspection_identity();
create trigger b_scope_inspections_status_guard
before update of status on plantlab_plant.scope_inspections
for each row execute function plantlab_platform.enforce_status_transition('PLANT', 'SCOPE_INSPECTION');
create trigger c_scope_inspections_submission_guard
before update of status on plantlab_plant.scope_inspections
for each row execute function plantlab_plant.validate_scope_inspection_submission();
create trigger y_scope_inspections_status_outbox
after update of status on plantlab_plant.scope_inspections
for each row execute function plantlab_audit.enqueue_status_event('PLANT', 'SCOPE_INSPECTION');
create trigger z_scope_inspections_status_audit
after update of status on plantlab_plant.scope_inspections
for each row execute function plantlab_audit.log_status_change('PLANT', 'SCOPE_INSPECTION');

create trigger a_process_measurements_editable
before insert or update or delete on plantlab_plant.process_measurements
for each row execute function plantlab_plant.ensure_process_measurement_editable();
create trigger b_process_measurements_validate
before insert or update on plantlab_plant.process_measurements
for each row execute function plantlab_plant.validate_process_measurement_value();
create trigger a_plant_test_result_values_editable
before insert or update or delete on plantlab_plant.test_result_values
for each row execute function plantlab_plant.ensure_test_result_value_editable();
create trigger b_plant_test_result_values_validate
before insert or update on plantlab_plant.test_result_values
for each row execute function plantlab_plant.validate_test_result_value();

alter table plantlab_plant.measurement_definitions enable row level security;
alter table plantlab_plant.scope_inspections enable row level security;
alter table plantlab_plant.process_measurements enable row level security;
alter table plantlab_plant.test_result_values enable row level security;

revoke all on table
  plantlab_plant.measurement_definitions,
  plantlab_plant.scope_inspections,
  plantlab_plant.process_measurements,
  plantlab_plant.test_result_values
from anon;
grant select, insert, update, delete on table
  plantlab_plant.measurement_definitions,
  plantlab_plant.scope_inspections,
  plantlab_plant.process_measurements,
  plantlab_plant.test_result_values
to authenticated, service_role;

revoke all on function plantlab_plant.validate_scope_inspection_identity() from PUBLIC, anon, authenticated;
revoke all on function plantlab_plant.validate_scope_inspection_submission() from PUBLIC, anon, authenticated;
