comment on table plantlab_plant.scope_inspections is
  'Warehouse, Non-Seed, area, material, and equipment inspections that do not require a dummy Lot.';
comment on table plantlab_plant.process_measurements is
  'Typed process measurements used for filtering, trend analysis, and manual-report compatibility.';
comment on table plantlab_plant.test_result_values is
  'Plant test component values, including the detailed Physical Purity breakdown.';
-- Canonical source: 20260812000300_lab_cycles_observations_and_tolerance.sql
set local lock_timeout = '5s';
set local statement_timeout = '2min';

-- Migration 016: normalized Lab methods, testing cycles, milestone events,
-- replicate observations, and the literal TOLERATED DIFF master from the
-- audited Germination/Vigour workbook. No historical transaction is imported.

alter table plantlab_lab.methods
  add column procedure_metadata jsonb not null default '{}'::jsonb,
  add constraint methods_procedure_metadata_object_ck check (
    jsonb_typeof(procedure_metadata) = 'object'
  );

create table plantlab_lab.method_test_types (
  method_id uuid not null references plantlab_lab.methods(id) on delete cascade,
  test_type_id uuid not null references plantlab_lab.test_types(id) on delete cascade,
  is_default boolean not null default false,
  requires_replicate_observations boolean not null default false,
  created_at timestamptz not null default now(),
  constraint method_test_types_pkey primary key (method_id, test_type_id)
);

create unique index method_test_types_one_default_uq
  on plantlab_lab.method_test_types (test_type_id)
  where is_default;

alter table plantlab_lab.request_items
  add column requested_method_id uuid
    references plantlab_lab.methods(id) on delete restrict;

drop index plantlab_lab.request_items_active_request_test_uq;
create unique index request_items_active_request_test_method_uq
  on plantlab_lab.request_items (
    request_id,
    test_type_id,
    coalesce(requested_method_id, '00000000-0000-0000-0000-000000000000'::uuid)
  )
  where is_active;

create index request_items_requested_method_idx
  on plantlab_lab.request_items (requested_method_id, status)
  where requested_method_id is not null;

alter table plantlab_lab.sample_receipts
  add column external_accession_no text,
  add column source_received_at timestamptz,
  add constraint sample_receipts_external_accession_ck check (
    external_accession_no is null
    or nullif(btrim(external_accession_no), '') is not null
  );

create index sample_receipts_external_accession_idx
  on plantlab_lab.sample_receipts (upper(btrim(external_accession_no)))
  where external_accession_no is not null;

create table plantlab_lab.test_cycles (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references plantlab_lab.requests(id) on delete cascade,
  sample_id uuid not null references plantlab_core.samples(id) on delete restrict,
  cycle_no integer not null,
  cycle_type text not null default 'INITIAL',
  testing_program_code text,
  parent_cycle_id uuid references plantlab_lab.test_cycles(id) on delete restrict,
  incoming_receipt_id uuid references plantlab_lab.sample_receipts(id) on delete restrict,
  status text not null default 'PLANNED',
  status_reason text,
  started_at timestamptz,
  completed_at timestamptz,
  remarks text,
  idempotency_key text,
  metadata jsonb not null default '{}'::jsonb,
  created_by uuid references plantlab_platform.identities(id) on delete set null,
  updated_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint test_cycles_request_sample_fk foreign key (request_id, sample_id)
    references plantlab_lab.request_samples(request_id, sample_id) on delete restrict,
  constraint test_cycles_request_sample_no_uq unique (request_id, sample_id, cycle_no),
  constraint test_cycles_idempotency_uq unique (idempotency_key),
  constraint test_cycles_cycle_no_ck check (cycle_no > 0),
  constraint test_cycles_cycle_type_ck check (
    cycle_type in ('INITIAL', 'RESAMPLE', 'RETEST', 'DOUBLE_SAMPLE', 'RCS', 'OTHER')
  ),
  constraint test_cycles_program_code_ck check (
    testing_program_code is null
    or (
      testing_program_code = upper(testing_program_code)
      and testing_program_code ~ '^[A-Z][A-Z0-9_]*$'
    )
  ),
  constraint test_cycles_status_ck check (
    status in ('PLANNED', 'ACTIVE', 'COMPLETED', 'CANCELLED')
  ),
  constraint test_cycles_parent_ck check (parent_cycle_id is null or parent_cycle_id <> id),
  constraint test_cycles_timeline_ck check (
    completed_at is null or started_at is null or completed_at >= started_at
  ),
  constraint test_cycles_idempotency_ck check (
    idempotency_key is null or nullif(btrim(idempotency_key), '') is not null
  ),
  constraint test_cycles_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index test_cycles_queue_idx
  on plantlab_lab.test_cycles (request_id, sample_id, status, cycle_no desc);
create index test_cycles_parent_idx
  on plantlab_lab.test_cycles (parent_cycle_id)
  where parent_cycle_id is not null;

alter table plantlab_lab.test_runs
  add column test_cycle_id uuid references plantlab_lab.test_cycles(id) on delete restrict;

create index test_runs_cycle_idx
  on plantlab_lab.test_runs (test_cycle_id, status)
  where test_cycle_id is not null;

create table plantlab_lab.test_run_events (
  id bigint generated always as identity primary key,
  test_run_id uuid not null references plantlab_lab.test_runs(id) on delete cascade,
  event_type text not null,
  sequence_no integer not null default 1,
  event_at timestamptz not null default now(),
  performed_by uuid references plantlab_platform.identities(id) on delete set null,
  remarks text,
  idempotency_key text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint test_run_events_run_type_sequence_uq unique (
    test_run_id,
    event_type,
    sequence_no
  ),
  constraint test_run_events_idempotency_uq unique (idempotency_key),
  constraint test_run_events_type_ck check (
    event_type in (
      'PREPARED', 'PLANTED', 'OBSERVED_FIRST', 'OBSERVED_FINAL',
      'SUBMITTED', 'DELIVERED_GOT', 'OTHER'
    )
  ),
  constraint test_run_events_sequence_ck check (sequence_no > 0),
  constraint test_run_events_idempotency_ck check (
    idempotency_key is null or nullif(btrim(idempotency_key), '') is not null
  ),
  constraint test_run_events_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index test_run_events_timeline_idx
  on plantlab_lab.test_run_events (test_run_id, event_type, event_at desc, sequence_no desc);

create table plantlab_lab.test_run_observations (
  id uuid primary key default gen_random_uuid(),
  test_run_id uuid not null references plantlab_lab.test_runs(id) on delete cascade,
  observation_phase text not null,
  replicate_no integer not null,
  observed_at timestamptz not null default now(),
  normal_count integer,
  abnormal_count integer,
  dead_count integer,
  total_count integer generated always as (
    coalesce(normal_count, 0) + coalesce(abnormal_count, 0) + coalesce(dead_count, 0)
  ) stored,
  remarks text,
  metadata jsonb not null default '{}'::jsonb,
  recorded_by uuid references plantlab_platform.identities(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint test_run_observations_run_phase_replicate_uq unique (
    test_run_id,
    observation_phase,
    replicate_no
  ),
  constraint test_run_observations_phase_ck check (
    observation_phase in ('FIRST_COUNT', 'INTERMEDIATE', 'FINAL')
  ),
  constraint test_run_observations_replicate_ck check (replicate_no > 0),
  constraint test_run_observations_count_present_ck check (
    num_nonnulls(normal_count, abnormal_count, dead_count) >= 1
  ),
  constraint test_run_observations_counts_nonnegative_ck check (
    coalesce(normal_count, 0) >= 0
    and coalesce(abnormal_count, 0) >= 0
    and coalesce(dead_count, 0) >= 0
  ),
  constraint test_run_observations_metadata_object_ck check (jsonb_typeof(metadata) = 'object')
);

create index test_run_observations_timeline_idx
  on plantlab_lab.test_run_observations (test_run_id, observation_phase, observed_at, replicate_no);

create table plantlab_lab.tolerance_rules (
  id uuid primary key default gen_random_uuid(),
  rule_code text not null,
  test_type_id uuid references plantlab_lab.test_types(id) on delete restrict,
  method_id uuid references plantlab_lab.methods(id) on delete restrict,
  replicate_count integer not null,
  value_percent integer not null,
  max_allowed_difference numeric not null,
  version integer not null default 1,
  effective_from date not null,
  effective_until date,
  source_reference text not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint tolerance_rules_code_uq unique (rule_code),
  constraint tolerance_rules_replicate_ck check (replicate_count between 2 and 100),
  constraint tolerance_rules_value_ck check (value_percent between 0 and 100),
  constraint tolerance_rules_difference_ck check (
    max_allowed_difference between 0 and 100
  ),
  constraint tolerance_rules_version_ck check (version > 0),
  constraint tolerance_rules_effective_ck check (
    effective_until is null or effective_until >= effective_from
  )
);

create unique index tolerance_rules_scope_value_version_uq
  on plantlab_lab.tolerance_rules (
    coalesce(test_type_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(method_id, '00000000-0000-0000-0000-000000000000'::uuid),
    replicate_count,
    value_percent,
    version
  );
create index tolerance_rules_lookup_idx
  on plantlab_lab.tolerance_rules (
    replicate_count,
    value_percent,
    effective_from desc,
    version desc
  )
  where is_active;

