insert into plantlab_lab.method_test_types (
  method_id,
  test_type_id,
  is_default,
  requires_replicate_observations
)
select
  m.id,
  tt.id,
  false,
  true
from (
  values
    ('SAND_25C', 'GERMINATION'),
    ('COLD_TEST_5C_24H', 'VIGOUR'),
    ('AAT_42C_72H_RH90', 'VIGOUR'),
    ('SCT_10C7D_25C5D', 'VIGOUR'),
    ('RET_16C_48H', 'VIGOUR'),
    ('AAT_EXT_42C_96H_RH90', 'VIGOUR')
) seed(method_code, test_code)
join plantlab_lab.methods m
  on m.method_code = seed.method_code and m.version = 1
join plantlab_lab.test_types tt on tt.test_code = seed.test_code
on conflict (method_id, test_type_id) do update
set requires_replicate_observations = excluded.requires_replicate_observations;

with tolerance_series(replicate_count, tolerance_values) as (
  values
    (
      2,
      array[
        4,5,6,6,7,8,8,9,9,9,10,10,11,11,11,11,12,12,12,13,
        13,13,13,13,14,14,14,14,14,14,14,15,15,15,15,15,15,15,15,15,
        15,15,15,15,15,16,16,16,16,16,16,16,16,15,15,15,15,15,15,15,
        15,15,15,15,15,15,15,14,14,14,14,14,14,14,13,13,13,13,13,12,
        12,12,11,11,11,11,10,10,9,9,9,8,8,7,6,6,5,4
      ]::integer[]
    ),
    (
      4,
      array[
        5,6,7,8,9,10,10,11,11,12,12,13,13,14,14,14,15,15,15,16,
        16,16,17,17,17,17,17,18,18,18,18,18,18,19,19,19,19,19,19,19,
        19,19,19,19,20,20,20,20,20,20,20,20,20,20,19,19,19,19,19,19,
        19,19,19,19,19,18,18,18,18,18,18,17,17,17,17,17,16,16,16,15,
        15,15,14,14,14,13,13,12,12,11,11,10,10,9,8,7,6,5
      ]::integer[]
    )
), tolerance_seed as (
  select
    format(
      'LEGACY-TOL-%s-%s-V1',
      ts.replicate_count,
      lpad((u.position + 1)::text, 3, '0')
    ) as rule_code,
    ts.replicate_count,
    (u.position + 1)::integer as value_percent,
    u.max_allowed_difference::numeric as max_allowed_difference
  from tolerance_series ts
  cross join lateral unnest(ts.tolerance_values)
    with ordinality as u(max_allowed_difference, position)
)
insert into plantlab_lab.tolerance_rules (
  rule_code,
  replicate_count,
  value_percent,
  max_allowed_difference,
  version,
  effective_from,
  source_reference,
  is_active
)
select
  seed.rule_code,
  seed.replicate_count,
  seed.value_percent,
  seed.max_allowed_difference,
  1,
  date '2026-01-01',
  'Germinasi vigor CY2026 (Latest update 10.08.2026).xlsx / TOLERATED DIFF!A3:E100',
  true
from tolerance_seed seed
on conflict (rule_code) do update
set replicate_count = excluded.replicate_count,
    value_percent = excluded.value_percent,
    max_allowed_difference = excluded.max_allowed_difference,
    source_reference = excluded.source_reference,
    is_active = true,
    updated_at = now();

create or replace function plantlab_lab.validate_request_item()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_lot_id uuid;
  v_spec_test_type_id uuid;
  v_existing_id uuid;
begin
  if tg_op = 'UPDATE'
    and old.requested_method_id is distinct from new.requested_method_id
    and old.status <> 'DRAFT' then
    raise exception 'Requested method can only be changed while the request item is DRAFT'
      using errcode = '55000';
  end if;

  if new.specification_id is not null then
    select s.test_type_id
      into v_spec_test_type_id
    from plantlab_lab.specifications s
    where s.id = new.specification_id;

    if v_spec_test_type_id is distinct from new.test_type_id then
      raise exception 'Specification does not belong to the selected test type'
        using errcode = '23514';
    end if;
  end if;

  if new.requested_method_id is not null and not exists (
    select 1
    from plantlab_lab.methods m
    join plantlab_lab.method_test_types mtt on mtt.method_id = m.id
    where m.id = new.requested_method_id
      and m.is_active
      and mtt.test_type_id = new.test_type_id
  ) then
    raise exception 'Requested method is inactive or incompatible with the selected test type'
      using errcode = '23514';
  end if;

  select r.lot_id into v_lot_id
  from plantlab_lab.requests r
  where r.id = new.request_id;

  if new.is_active and v_lot_id is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(
        v_lot_id::text || ':' || new.test_type_id::text || ':'
        || coalesce(new.requested_method_id::text, '*'),
        0
      )
    );

    select ri.id
      into v_existing_id
    from plantlab_lab.request_items ri
    join plantlab_lab.requests r on r.id = ri.request_id
    where r.lot_id = v_lot_id
      and ri.test_type_id = new.test_type_id
      and ri.requested_method_id is not distinct from new.requested_method_id
      and ri.is_active
      and ri.id <> new.id
      and r.status not in ('APPROVED', 'REJECTED', 'CLOSED', 'CANCELLED')
    limit 1;

    if v_existing_id is not null then
      raise exception 'An active Lab request already exists for this Lot, test type, and method'
        using errcode = '23505';
    end if;
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_assignment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request_id uuid;
  v_test_type_id uuid;
  v_test_code text;
  v_requested_method_id uuid;
begin
  select ri.request_id, ri.test_type_id, tt.test_code, ri.requested_method_id
    into v_request_id, v_test_type_id, v_test_code, v_requested_method_id
  from plantlab_lab.request_items ri
  join plantlab_lab.test_types tt on tt.id = ri.test_type_id
  where ri.id = new.request_item_id;

  if not exists (
    select 1
    from plantlab_lab.request_samples rs
    where rs.request_id = v_request_id
      and rs.sample_id = new.sample_id
  ) then
    raise exception 'Assigned Sample is not linked to the Lab Request'
      using errcode = '23514';
  end if;

  if v_requested_method_id is not null then
    if new.method_id is null then
      new.method_id := v_requested_method_id;
    elsif new.method_id is distinct from v_requested_method_id then
      raise exception 'Assignment method does not match the requested method'
        using errcode = '23514';
    end if;
  end if;

  if new.method_id is not null and not exists (
    select 1
    from plantlab_lab.methods m
    join plantlab_lab.method_test_types mtt on mtt.method_id = m.id
    where m.id = new.method_id
      and m.is_active
      and mtt.test_type_id = v_test_type_id
  ) then
    raise exception 'Assignment method is inactive or incompatible with the test type'
      using errcode = '23514';
  end if;

  if v_test_code in ('GERMINATION', 'VIGOUR') and new.method_id is null then
    raise exception 'Germination and Vigour assignments require a method'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_cycle()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent_request_id uuid;
  v_parent_sample_id uuid;
  v_parent_cycle_no integer;
begin
  if not exists (
    select 1
    from plantlab_lab.request_samples rs
    where rs.request_id = new.request_id
      and rs.sample_id = new.sample_id
  ) then
    raise exception 'Test cycle Sample is not linked to the Lab Request'
      using errcode = '23514';
  end if;

  if new.incoming_receipt_id is not null and not exists (
    select 1
    from plantlab_lab.sample_receipts sr
    join plantlab_lab.request_samples rs on rs.id = sr.request_sample_id
    where sr.id = new.incoming_receipt_id
      and rs.request_id = new.request_id
      and rs.sample_id = new.sample_id
  ) then
    raise exception 'Test cycle receipt does not belong to its request and Sample'
      using errcode = '23514';
  end if;

  if new.parent_cycle_id is not null then
    select tc.request_id, tc.sample_id, tc.cycle_no
      into v_parent_request_id, v_parent_sample_id, v_parent_cycle_no
    from plantlab_lab.test_cycles tc
    where tc.id = new.parent_cycle_id;

    if v_parent_request_id is distinct from new.request_id
      or v_parent_sample_id is distinct from new.sample_id
      or v_parent_cycle_no >= new.cycle_no then
      raise exception 'Parent test cycle must use the same request and Sample with a lower cycle number'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_cycle_workflow()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.status is distinct from new.status then
    if new.status = 'ACTIVE' then
      new.started_at := coalesce(new.started_at, now());
    elsif new.status = 'COMPLETED' then
      new.started_at := coalesce(new.started_at, old.started_at, now());
      new.completed_at := coalesce(new.completed_at, now());
    end if;
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_run_identity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_assignment_item_id uuid;
  v_assignment_sample_id uuid;
  v_assignment_method_id uuid;
  v_request_id uuid;
  v_test_type_id uuid;
  v_test_code text;
  v_requested_method_id uuid;
  v_cycle_request_id uuid;
  v_cycle_sample_id uuid;
  v_parent_item_id uuid;
  v_parent_sample_id uuid;
  v_parent_attempt integer;
begin
  if tg_op = 'UPDATE' and old.status <> 'ASSIGNED' then
    if old.method_id is distinct from new.method_id then
      raise exception 'Test Run method cannot be changed after testing starts'
        using errcode = '55000';
    end if;
    if old.test_cycle_id is distinct from new.test_cycle_id then
      raise exception 'Test Run cycle cannot be changed after testing starts'
        using errcode = '55000';
    end if;
  end if;

  select ri.request_id, ri.test_type_id, tt.test_code, ri.requested_method_id
    into v_request_id, v_test_type_id, v_test_code, v_requested_method_id
  from plantlab_lab.request_items ri
  join plantlab_lab.test_types tt on tt.id = ri.test_type_id
  where ri.id = new.request_item_id;

  if new.assignment_id is not null then
    select ta.request_item_id, ta.sample_id, ta.method_id
      into v_assignment_item_id, v_assignment_sample_id, v_assignment_method_id
    from plantlab_lab.test_assignments ta
    where ta.id = new.assignment_id;

    if v_assignment_item_id is distinct from new.request_item_id
      or v_assignment_sample_id is distinct from new.sample_id then
      raise exception 'Test Run does not match its assignment item and Sample'
        using errcode = '23514';
    end if;

    if new.method_id is null then
      new.method_id := v_assignment_method_id;
    elsif v_assignment_method_id is not null
      and new.method_id is distinct from v_assignment_method_id then
      raise exception 'Test Run method does not match its assignment method'
        using errcode = '23514';
    end if;
  end if;

  if v_requested_method_id is not null then
    if new.method_id is null then
      new.method_id := v_requested_method_id;
    elsif new.method_id is distinct from v_requested_method_id then
      raise exception 'Test Run method does not match the requested method'
        using errcode = '23514';
    end if;
  end if;

  if new.method_id is not null and not exists (
    select 1
    from plantlab_lab.methods m
    join plantlab_lab.method_test_types mtt on mtt.method_id = m.id
    where m.id = new.method_id
      and m.is_active
      and mtt.test_type_id = v_test_type_id
  ) then
    raise exception 'Test Run method is inactive or incompatible with the test type'
      using errcode = '23514';
  end if;

  if v_test_code in ('GERMINATION', 'VIGOUR') and new.method_id is null then
    raise exception 'Germination and Vigour Test Runs require a method'
      using errcode = '23514';
  end if;

  if new.test_cycle_id is not null then
    select tc.request_id, tc.sample_id
      into v_cycle_request_id, v_cycle_sample_id
    from plantlab_lab.test_cycles tc
    where tc.id = new.test_cycle_id;

    if v_cycle_request_id is distinct from v_request_id
      or v_cycle_sample_id is distinct from new.sample_id then
      raise exception 'Test Run cycle does not match its request and Sample'
        using errcode = '23514';
    end if;
  end if;

  if new.retest_of_id is not null then
    select tr.request_item_id, tr.sample_id, tr.attempt_no
      into v_parent_item_id, v_parent_sample_id, v_parent_attempt
    from plantlab_lab.test_runs tr
    where tr.id = new.retest_of_id;

    if v_parent_item_id is distinct from new.request_item_id
      or v_parent_sample_id is distinct from new.sample_id
      or new.attempt_no <> v_parent_attempt + 1 then
      raise exception 'Retest must use the same request item and Sample with the next attempt number'
        using errcode = '23514';
    end if;
  elsif new.attempt_no > 1 then
    raise exception 'Attempt number greater than 1 requires retest_of_id'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create or replace function plantlab_lab.ensure_test_run_observation_editable()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_test_run_id uuid;
  v_run_status text;
begin
  v_test_run_id := case when tg_op = 'DELETE' then old.test_run_id else new.test_run_id end;

  select tr.status into v_run_status
  from plantlab_lab.test_runs tr
  where tr.id = v_test_run_id;

  if v_run_status <> 'IN_PROGRESS' then
    raise exception 'Replicate observations can only be changed while the Test Run is IN_PROGRESS'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create or replace function plantlab_lab.validate_test_run_workflow()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_missing_required integer;
  v_item_status text;
  v_request_status text;
  v_requires_observations boolean;
begin
  if old.status = 'IN_REVIEW'
    and new.status in ('APPROVED', 'REJECTED', 'RETEST')
    and current_setting('app.result_decision_context', true) is distinct from 'on' then
    raise exception 'Final Test Run status can only be set through plantlab_lab.result_decisions'
      using errcode = '42501';
  end if;

  if new.status = 'IN_PROGRESS' and old.status is distinct from new.status then
    select ri.status, r.status
      into v_item_status, v_request_status
    from plantlab_lab.request_items ri
    join plantlab_lab.requests r on r.id = ri.request_id
    where ri.id = new.request_item_id;

    if v_item_status not in ('READY', 'TESTING')
      or v_request_status not in ('RECEIVED', 'TESTING') then
      raise exception 'Lab Request and item must be received/ready before testing starts'
        using errcode = '23514';
    end if;

    new.started_at := coalesce(new.started_at, now());
    new.performed_by := coalesce(new.performed_by, auth.uid());
  end if;

  if new.status = 'SUBMITTED' and old.status is distinct from new.status then
    select ri.status into v_item_status
    from plantlab_lab.request_items ri
    where ri.id = new.request_item_id;

    if v_item_status <> 'TESTING' then
      raise exception 'Lab Request item must be TESTING before a Test Run is submitted'
        using errcode = '23514';
    end if;

    select count(*)::integer
      into v_missing_required
    from plantlab_lab.request_items ri
    join plantlab_lab.test_type_parameters ttp
      on ttp.test_type_id = ri.test_type_id and ttp.is_required
    left join plantlab_lab.result_values rv
      on rv.test_run_id = new.id and rv.parameter_id = ttp.parameter_id
    where ri.id = new.request_item_id
      and rv.id is null;

    if v_missing_required > 0 then
      raise exception 'Cannot submit Test Run: % required result parameter(s) are missing',
        v_missing_required using errcode = '23514';
    end if;

    select coalesce(mtt.requires_replicate_observations, false)
      into v_requires_observations
    from plantlab_lab.method_test_types mtt
    where mtt.method_id = new.method_id
      and mtt.test_type_id = (
        select ri.test_type_id
        from plantlab_lab.request_items ri
        where ri.id = new.request_item_id
      );

    if coalesce(v_requires_observations, false) then
      if not exists (
        select 1
        from plantlab_lab.test_run_observations tro
        where tro.test_run_id = new.id
          and tro.observation_phase = 'FINAL'
      ) then
        raise exception 'Cannot submit Test Run: final replicate observations are missing'
          using errcode = '23514';
      end if;

      if not exists (
        select 1
        from plantlab_lab.test_run_events tre
        where tre.test_run_id = new.id
          and tre.event_type = 'OBSERVED_FINAL'
      ) then
        raise exception 'Cannot submit Test Run: OBSERVED_FINAL event is missing'
          using errcode = '23514';
      end if;
    end if;

    new.completed_at := coalesce(new.completed_at, now());
    new.submitted_at := coalesce(new.submitted_at, now());
  end if;

  return new;
end;
$$;

create or replace function plantlab_platform.can_access_lab_test_cycle(
  p_test_cycle_id uuid,
  p_permission text
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(plantlab_platform.can_access_lab_request(tc.request_id, p_permission), false)
  from plantlab_lab.test_cycles tc
  where tc.id = p_test_cycle_id;
$$;

create or replace function plantlab_lab.get_tolerance_limit(
  p_replicate_count integer,
  p_value_percent numeric,
  p_test_type_id uuid default null,
  p_method_id uuid default null,
  p_at date default current_date
)
returns numeric
language sql
stable
security invoker
set search_path = ''
as $$
  select tr.max_allowed_difference
  from plantlab_lab.tolerance_rules tr
  where tr.is_active
    and tr.replicate_count = p_replicate_count
    and tr.value_percent = round(p_value_percent)::integer
    and (tr.test_type_id is null or tr.test_type_id = p_test_type_id)
    and (tr.method_id is null or tr.method_id = p_method_id)
    and tr.effective_from <= p_at
    and (tr.effective_until is null or tr.effective_until >= p_at)
  order by
    (tr.method_id is not null)::integer desc,
    (tr.test_type_id is not null)::integer desc,
    tr.version desc,
    tr.effective_from desc
  limit 1;
$$;

create or replace function plantlab_lab.create_test_cycle(
  p_request_id uuid,
  p_sample_id uuid,
  p_cycle_type text default 'INITIAL',
  p_parent_cycle_id uuid default null,
  p_incoming_receipt_id uuid default null,
  p_testing_program_code text default null,
  p_remarks text default null,
  p_idempotency_key text default null,
  p_metadata jsonb default '{}'::jsonb
)
returns plantlab_lab.test_cycles
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_lab.test_cycles;
  v_cycle_no integer;
begin
  if p_idempotency_key is not null then
    select * into v_row
    from plantlab_lab.test_cycles tc
    where tc.idempotency_key = p_idempotency_key;

    if found then
      return v_row;
    end if;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_request_id::text || ':' || p_sample_id::text, 0)
  );

  select coalesce(max(tc.cycle_no), 0) + 1
    into v_cycle_no
  from plantlab_lab.test_cycles tc
  where tc.request_id = p_request_id
    and tc.sample_id = p_sample_id;

  insert into plantlab_lab.test_cycles (
    request_id,
    sample_id,
    cycle_no,
    cycle_type,
    parent_cycle_id,
    incoming_receipt_id,
    testing_program_code,
    remarks,
    idempotency_key,
    metadata,
    created_by,
    updated_by
  ) values (
    p_request_id,
    p_sample_id,
    v_cycle_no,
    upper(p_cycle_type),
    p_parent_cycle_id,
    p_incoming_receipt_id,
    upper(p_testing_program_code),
    p_remarks,
    p_idempotency_key,
    coalesce(p_metadata, '{}'::jsonb),
    auth.uid(),
    auth.uid()
  )
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function plantlab_lab.advance_test_cycle(
  p_test_cycle_id uuid,
  p_target_status text,
  p_reason text default null
)
returns plantlab_lab.test_cycles
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_lab.test_cycles;
begin
  perform set_config('app.status_reason', coalesce(p_reason, ''), true);

  update plantlab_lab.test_cycles
  set status = upper(p_target_status),
      status_reason = p_reason,
      updated_by = auth.uid(),
      updated_at = now()
  where id = p_test_cycle_id
  returning * into v_row;

  if not found then
    raise exception 'Test cycle not found or not accessible'
      using errcode = 'P0002';
  end if;

  return v_row;
end;
$$;

create or replace function plantlab_lab.record_test_run_event(
  p_test_run_id uuid,
  p_event_type text,
  p_event_at timestamptz default now(),
  p_remarks text default null,
  p_metadata jsonb default '{}'::jsonb,
  p_idempotency_key text default null
)
returns plantlab_lab.test_run_events
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_lab.test_run_events;
  v_sequence_no integer;
  v_event_type text := upper(p_event_type);
begin
  if p_idempotency_key is not null then
    select * into v_row
    from plantlab_lab.test_run_events tre
    where tre.idempotency_key = p_idempotency_key;

    if found then
      return v_row;
    end if;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_test_run_id::text || ':' || v_event_type, 0)
  );

  select coalesce(max(tre.sequence_no), 0) + 1
    into v_sequence_no
  from plantlab_lab.test_run_events tre
  where tre.test_run_id = p_test_run_id
    and tre.event_type = v_event_type;

  insert into plantlab_lab.test_run_events (
    test_run_id,
    event_type,
    sequence_no,
    event_at,
    performed_by,
    remarks,
    metadata,
    idempotency_key
  ) values (
    p_test_run_id,
    v_event_type,
    v_sequence_no,
    p_event_at,
    auth.uid(),
    p_remarks,
    coalesce(p_metadata, '{}'::jsonb),
    p_idempotency_key
  )
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function plantlab_lab.save_test_run_observation(
  p_test_run_id uuid,
  p_observation_phase text,
  p_replicate_no integer,
  p_observed_at timestamptz default now(),
  p_normal_count integer default null,
  p_abnormal_count integer default null,
  p_dead_count integer default null,
  p_remarks text default null,
  p_metadata jsonb default '{}'::jsonb
)
returns plantlab_lab.test_run_observations
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_row plantlab_lab.test_run_observations;
begin
  insert into plantlab_lab.test_run_observations (
    test_run_id,
    observation_phase,
    replicate_no,
    observed_at,
    normal_count,
    abnormal_count,
    dead_count,
    remarks,
    metadata,
    recorded_by
  ) values (
    p_test_run_id,
    upper(p_observation_phase),
    p_replicate_no,
    p_observed_at,
    p_normal_count,
    p_abnormal_count,
    p_dead_count,
    p_remarks,
    coalesce(p_metadata, '{}'::jsonb),
    auth.uid()
  )
  on conflict (test_run_id, observation_phase, replicate_no) do update
  set observed_at = excluded.observed_at,
      normal_count = excluded.normal_count,
      abnormal_count = excluded.abnormal_count,
      dead_count = excluded.dead_count,
      remarks = excluded.remarks,
      metadata = excluded.metadata,
      recorded_by = auth.uid(),
      updated_at = now()
  returning * into v_row;

  return v_row;
end;
$$;

create or replace function plantlab_lab.record_sample_receipt_v2(
  p_request_sample_id uuid,
  p_decision text,
  p_received_quantity numeric default null,
  p_unit_code text default null,
  p_condition_notes text default null,
  p_rejection_reason text default null,
  p_external_accession_no text default null,
  p_source_received_at timestamptz default null
)
returns plantlab_lab.sample_receipts
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_receipt plantlab_lab.sample_receipts;
begin
  v_receipt := plantlab_lab.record_sample_receipt(
    p_request_sample_id,
    p_decision,
    p_received_quantity,
    p_unit_code,
    p_condition_notes,
    p_rejection_reason
  );

  update plantlab_lab.sample_receipts
  set external_accession_no = p_external_accession_no,
      source_received_at = coalesce(p_source_received_at, received_at),
      updated_at = now()
  where id = v_receipt.id
  returning * into v_receipt;

  return v_receipt;
end;
$$;

insert into plantlab_platform.status_transitions (
  module_code,
  entity_type,
  from_status,
  to_status,
  requires_reason
)
values
  ('LAB', 'TEST_CYCLE', 'PLANNED', 'ACTIVE', false),
  ('LAB', 'TEST_CYCLE', 'PLANNED', 'CANCELLED', true),
  ('LAB', 'TEST_CYCLE', 'ACTIVE', 'COMPLETED', false),
  ('LAB', 'TEST_CYCLE', 'ACTIVE', 'CANCELLED', true)
on conflict do nothing;

drop trigger request_items_validate on plantlab_lab.request_items;
create trigger request_items_validate
before insert or update of
  request_id,
  test_type_id,
  specification_id,
  requested_method_id,
  is_active
on plantlab_lab.request_items
for each row execute function plantlab_lab.validate_request_item();

drop trigger test_assignments_validate on plantlab_lab.test_assignments;
create trigger test_assignments_validate
before insert or update of request_item_id, sample_id, method_id
on plantlab_lab.test_assignments
for each row execute function plantlab_lab.validate_test_assignment();

drop trigger test_runs_validate_identity on plantlab_lab.test_runs;
create trigger test_runs_validate_identity
before insert or update of
  assignment_id,
  request_item_id,
  sample_id,
  attempt_no,
  retest_of_id,
  method_id,
  test_cycle_id
on plantlab_lab.test_runs
for each row execute function plantlab_lab.validate_test_run_identity();

create trigger test_cycles_set_updated_at
before update on plantlab_lab.test_cycles
for each row execute function plantlab_platform.set_updated_at();
create trigger a0_test_cycles_initial_status
before insert on plantlab_lab.test_cycles
for each row execute function plantlab_platform.enforce_initial_status('PLANNED');
create trigger a_test_cycles_validate
before insert or update of
  request_id,
  sample_id,
  cycle_no,
  parent_cycle_id,
  incoming_receipt_id
on plantlab_lab.test_cycles
for each row execute function plantlab_lab.validate_test_cycle();
create trigger b_test_cycles_status_guard
before update of status on plantlab_lab.test_cycles
for each row execute function plantlab_platform.enforce_status_transition('LAB', 'TEST_CYCLE');
create trigger c_test_cycles_workflow_guard
before update of status on plantlab_lab.test_cycles
for each row execute function plantlab_lab.validate_test_cycle_workflow();
create trigger y_test_cycles_status_outbox
after update of status on plantlab_lab.test_cycles
for each row execute function plantlab_audit.enqueue_status_event('LAB', 'TEST_CYCLE');
create trigger z_test_cycles_status_audit
after update of status on plantlab_lab.test_cycles
for each row execute function plantlab_audit.log_status_change('LAB', 'TEST_CYCLE');

create trigger test_run_observations_set_updated_at
before update on plantlab_lab.test_run_observations
for each row execute function plantlab_platform.set_updated_at();
create trigger test_run_observations_editable
before insert or update or delete on plantlab_lab.test_run_observations
for each row execute function plantlab_lab.ensure_test_run_observation_editable();
create trigger test_run_events_append_only
before update or delete on plantlab_lab.test_run_events
for each row execute function plantlab_audit.prevent_append_only_mutation();
create trigger tolerance_rules_set_updated_at
before update on plantlab_lab.tolerance_rules
for each row execute function plantlab_platform.set_updated_at();

alter table plantlab_lab.method_test_types enable row level security;
alter table plantlab_lab.test_cycles enable row level security;
alter table plantlab_lab.test_run_events enable row level security;
alter table plantlab_lab.test_run_observations enable row level security;
alter table plantlab_lab.tolerance_rules enable row level security;

revoke all on table
  plantlab_lab.method_test_types,
  plantlab_lab.test_cycles,
  plantlab_lab.test_run_events,
  plantlab_lab.test_run_observations,
  plantlab_lab.tolerance_rules
from anon;
grant select, insert, update, delete on table
  plantlab_lab.method_test_types,
  plantlab_lab.test_cycles,
