-- Canonical source: 20260812000400_manual_compatibility_reporting_views.sql
set local lock_timeout = '5s';
set local statement_timeout = '2min';

-- Migration 017: normalized read models for web/Android and manual-report
-- compatibility. Views are security-invoker so underlying RLS remains active.
-- The legacy wide Testing 1-6 export is intentionally deferred until QA signs
-- off cycle-label precedence and historical duplicate handling.

create or replace function plantlab_lab.validate_test_run_request_sample()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request_id uuid;
begin
  select ri.request_id into v_request_id
  from plantlab_lab.request_items ri
  where ri.id = new.request_item_id;

  if not exists (
    select 1
    from plantlab_lab.request_samples rs
    where rs.request_id = v_request_id
      and rs.sample_id = new.sample_id
  ) then
    raise exception 'Test Run Sample is not linked to the Lab Request'
      using errcode = '23514';
  end if;

  return new;
end;
$$;

create trigger a0_test_runs_request_sample_validate
before insert or update of request_item_id, sample_id on plantlab_lab.test_runs
for each row execute function plantlab_lab.validate_test_run_request_sample();

revoke all on function plantlab_lab.validate_test_run_request_sample()
  from PUBLIC, anon, authenticated;

create or replace view plantlab_reporting.v_lab_tat
with (security_invoker = true)
as
with final_events as (
  select distinct on (tre.test_run_id)
    tre.test_run_id,
    tre.id as final_event_id,
    tre.event_at as final_observation_at,
    tre.sequence_no as final_event_sequence_no
  from plantlab_lab.test_run_events tre
  where tre.event_type = 'OBSERVED_FINAL'
  order by tre.test_run_id, tre.event_at desc, tre.sequence_no desc, tre.id desc
), run_context as (
  select
    tr.id as test_run_id,
    tr.test_code as test_run_code,
    tr.assignment_id,
    tr.request_item_id,
    tr.sample_id,
    tr.test_cycle_id,
    tr.attempt_no,
    tr.retest_of_id,
    tr.method_id,
    tr.status as test_run_status,
    tr.started_at,
    tr.completed_at,
    tr.submitted_at,
    tr.created_at as test_run_created_at,
    ri.request_id,
    ri.test_type_id,
    ri.requested_method_id,
    ri.status as request_item_status,
    r.request_code,
    r.source_module,
    r.source_entity,
    r.source_record_key,
    r.lot_id as request_lot_id,
    r.product_id as request_product_id,
    r.target_lab_site_id,
    r.status as request_status,
    tt.test_code,
    tt.test_name,
    s.sample_code,
    s.sample_type,
    s.received_at as sample_received_at,
    l.id as lot_id,
    l.canonical_lot_code,
    l.lot_code,
    l.company_id,
    l.product_id as lot_product_id,
    l.plant_site_id,
    l.stage_code,
    l.crop_category_code,
    l.seed_generation_code,
    l.crop_year,
    l.season_code,
    l.field_status_code,
    p.sku,
    p.name as product_name,
    actual_method.method_code,
    actual_method.method_name,
    requested_method.method_code as requested_method_code,
    requested_method.method_name as requested_method_name,
    tc.cycle_no,
    tc.cycle_type,
    tc.testing_program_code,
    tc.status as test_cycle_status,
    tc.incoming_receipt_id,
    lab_site.site_code as lab_site_code,
    lab_site.site_name as lab_site_name,
    lab_site.timezone_name,
    rs.id as request_sample_id
  from plantlab_lab.test_runs tr
  join plantlab_lab.request_items ri on ri.id = tr.request_item_id
  join plantlab_lab.requests r on r.id = ri.request_id
  join plantlab_lab.test_types tt on tt.id = ri.test_type_id
  join plantlab_core.samples s on s.id = tr.sample_id
  left join plantlab_core.lots l on l.id = coalesce(r.lot_id, s.lot_id)
  join plantlab_master.products p on p.id = coalesce(l.product_id, r.product_id)
  left join plantlab_lab.methods actual_method on actual_method.id = tr.method_id
  left join plantlab_lab.methods requested_method on requested_method.id = ri.requested_method_id
  left join plantlab_lab.test_cycles tc on tc.id = tr.test_cycle_id
  join plantlab_master.sites lab_site on lab_site.id = r.target_lab_site_id
  left join plantlab_lab.request_samples rs
    on rs.request_id = r.id and rs.sample_id = tr.sample_id
), timed as (
  select
    rc.*,
    receipt.id as sample_receipt_id,
    receipt.receipt_code,
    receipt.external_accession_no,
    coalesce(
      receipt.source_received_at,
      receipt.received_at,
      rc.sample_received_at
    ) as incoming_at,
    fe.final_event_id,
    fe.final_event_sequence_no,
    fe.final_observation_at
  from run_context rc
  left join final_events fe on fe.test_run_id = rc.test_run_id
  left join lateral (
    select sr.*
    from plantlab_lab.sample_receipts sr
    where sr.id = rc.incoming_receipt_id
      or (
        rc.incoming_receipt_id is null
        and sr.request_sample_id = rc.request_sample_id
      )
    order by
      (sr.id = rc.incoming_receipt_id) desc,
      coalesce(sr.source_received_at, sr.received_at) desc,
      sr.created_at desc
    limit 1
  ) receipt on true
)
select
  timed.*,
  (timed.incoming_at at time zone timed.timezone_name)::date as incoming_date,
  (timed.final_observation_at at time zone timed.timezone_name)::date
    as final_observation_date,
  case
    when timed.incoming_at is null or timed.final_observation_at is null then null
    else
      (timed.final_observation_at at time zone timed.timezone_name)::date
      - (timed.incoming_at at time zone timed.timezone_name)::date
  end as tat_days,
  case
    when timed.incoming_at is null or timed.final_observation_at is null then null
    else round(
      extract(epoch from (timed.final_observation_at - timed.incoming_at))::numeric
      / 3600,
      2
    )
  end as tat_elapsed_hours,
  date_trunc(
    'month',
    timed.final_observation_at at time zone timed.timezone_name
  )::date as final_observation_month,
  extract(
    isoyear from timed.final_observation_at at time zone timed.timezone_name
  )::integer as final_observation_iso_year,
  extract(
    week from timed.final_observation_at at time zone timed.timezone_name
  )::integer as final_observation_iso_week
from timed;

create or replace view plantlab_reporting.v_germ_vigor_detail
with (security_invoker = true)
as
select
  tat.test_run_id,
  tat.test_run_code,
  tat.request_id,
  tat.request_code,
  tat.request_item_id,
  tat.request_item_status,
  tat.request_status,
  tat.test_type_id,
  tat.test_code,
  tat.test_name,
  tat.method_id,
  tat.method_code,
  tat.method_name,
  tat.test_cycle_id,
  tat.cycle_no,
  tat.cycle_type,
  tat.testing_program_code,
  tat.attempt_no,
  tat.sample_id,
  tat.sample_code,
  tat.sample_type,
  tat.sample_receipt_id,
  tat.receipt_code,
  tat.external_accession_no,
  tat.incoming_at,
  tat.incoming_date,
  tat.final_observation_at,
  tat.final_observation_date,
  tat.tat_days,
  tat.tat_elapsed_hours,
  tat.lot_id,
  tat.canonical_lot_code,
  tat.lot_code,
  tat.product_name,
  tat.sku,
  tat.company_id,
  tat.plant_site_id,
  tat.target_lab_site_id,
  tat.lab_site_code,
  tat.lab_site_name,
  tat.stage_code,
  tat.crop_category_code,
  tat.seed_generation_code,
  tat.crop_year,
  tat.season_code,
  tat.field_status_code,
  tro.id as observation_id,
  tro.observation_phase,
  tro.replicate_no,
  tro.observed_at,
  tro.normal_count,
  tro.abnormal_count,
  tro.dead_count,
  tro.total_count,
  case
    when tro.total_count = 0 then null
    else round(tro.normal_count::numeric * 100 / tro.total_count, 2)
  end as normal_percent,
  tro.remarks as observation_remarks,
  tro.metadata as observation_metadata,
  tro.recorded_by
from plantlab_reporting.v_lab_tat tat
join plantlab_lab.test_run_observations tro on tro.test_run_id = tat.test_run_id
where tat.test_code in ('GERMINATION', 'VIGOUR');

create or replace view plantlab_reporting.v_germ_vigor_summary
with (security_invoker = true)
as
with observation_summary as (
  select
    detail.test_run_id,
    count(*) filter (where detail.total_count > 0)::integer as replicate_count,
    sum(detail.normal_count) as normal_count,
    sum(detail.abnormal_count) as abnormal_count,
    sum(detail.dead_count) as dead_count,
    sum(detail.total_count) as total_count,
    round(avg(detail.normal_percent), 2) as average_normal_percent,
    min(detail.normal_percent) as minimum_normal_percent,
    max(detail.normal_percent) as maximum_normal_percent,
    round(max(detail.normal_percent) - min(detail.normal_percent), 2)
      as replicate_difference,
    min(detail.observed_at) as first_replicate_observed_at,
    max(detail.observed_at) as last_replicate_observed_at
  from plantlab_reporting.v_germ_vigor_detail detail
  where detail.observation_phase = 'FINAL'
  group by detail.test_run_id
), aggregate_result as (
  select
    rv.test_run_id,
    rv.numeric_value as recorded_result_percent,
    rv.result as recorded_result_evaluation,
    rv.unit_code as recorded_result_unit,
    p.parameter_code as result_parameter_code
  from plantlab_lab.result_values rv
  join plantlab_lab.parameters p on p.id = rv.parameter_id
  where p.parameter_code in ('GERMINATION_PERCENT', 'VIGOUR_PERCENT')
)
select
  tat.test_run_id,
  tat.test_run_code,
  tat.request_id,
  tat.request_code,
  tat.request_item_id,
  tat.test_code,
  tat.test_name,
  tat.method_id,
  tat.method_code,
  tat.method_name,
  tat.test_cycle_id,
  tat.cycle_no,
  tat.cycle_type,
  tat.testing_program_code,
  tat.attempt_no,
  tat.test_run_status,
  tat.sample_id,
  tat.sample_code,
  tat.external_accession_no,
  tat.lot_id,
  tat.canonical_lot_code,
  tat.lot_code,
  tat.product_name,
  tat.sku,
  tat.company_id,
  tat.target_lab_site_id,
  tat.lab_site_code,
  tat.lab_site_name,
  tat.stage_code,
  tat.crop_category_code,
  tat.seed_generation_code,
  tat.crop_year,
  tat.season_code,
  tat.incoming_at,
  tat.incoming_date,
  tat.final_observation_at,
  tat.final_observation_date,
  tat.tat_days,
  tat.tat_elapsed_hours,
  obs.replicate_count,
  obs.normal_count,
  obs.abnormal_count,
  obs.dead_count,
  obs.total_count,
  obs.average_normal_percent,
  obs.minimum_normal_percent,
  obs.maximum_normal_percent,
  obs.replicate_difference,
  tolerance.max_allowed_difference,
  case
    when obs.replicate_count is null then 'NO_FINAL_OBSERVATION'
    when obs.replicate_count not in (2, 4) then 'REPLICATE_COUNT_NOT_CONFIGURED'
    when tolerance.max_allowed_difference is null then 'TOLERANCE_RULE_NOT_FOUND'
    when obs.replicate_difference <= tolerance.max_allowed_difference
      then 'WITHIN_TOLERANCE'
    else 'EXCEEDS_TOLERANCE'
  end as tolerance_evaluation,
  result_value.result_parameter_code,
  result_value.recorded_result_percent,
  result_value.recorded_result_unit,
  result_value.recorded_result_evaluation
from plantlab_reporting.v_lab_tat tat
left join observation_summary obs on obs.test_run_id = tat.test_run_id
left join lateral (
  select plantlab_lab.get_tolerance_limit(
    obs.replicate_count,
    obs.average_normal_percent,
    tat.test_type_id,
    tat.method_id,
    coalesce(tat.final_observation_date, current_date)
  ) as max_allowed_difference
) tolerance on true
left join aggregate_result result_value
  on result_value.test_run_id = tat.test_run_id
where tat.test_code in ('GERMINATION', 'VIGOUR');

create or replace view plantlab_reporting.v_quality_information_current
with (security_invoker = true)
as
with decision_activity as (
  select
    rd.test_run_id,
    max(rd.decided_at) as latest_decision_at
  from plantlab_lab.result_decisions rd
  group by rd.test_run_id
), ranked_runs as (
  select
    tat.*,
    da.latest_decision_at,
    row_number() over (
      partition by tat.request_item_id
      order by
        coalesce(tat.cycle_no, 0) desc,
        tat.attempt_no desc,
        case tat.test_run_status
          when 'APPROVED' then 1
          when 'IN_REVIEW' then 2
          when 'SUBMITTED' then 3
          when 'IN_PROGRESS' then 4
          when 'ASSIGNED' then 5
          when 'RETEST' then 6
          when 'REJECTED' then 7
          when 'CANCELLED' then 8
          else 9
        end,
        coalesce(
          da.latest_decision_at,
          tat.final_observation_at,
          tat.submitted_at,
          tat.completed_at,
          tat.started_at,
          tat.test_run_created_at
        ) desc,
        tat.test_run_id desc
    ) as current_rank
  from plantlab_reporting.v_lab_tat tat
  left join decision_activity da on da.test_run_id = tat.test_run_id
), result_payload as (
  select
    rv.test_run_id,
    jsonb_object_agg(
      p.parameter_code,
      jsonb_strip_nulls(jsonb_build_object(
        'numeric_value', rv.numeric_value,
        'text_value', rv.text_value,
        'boolean_value', rv.boolean_value,
        'unit_code', rv.unit_code,
        'evaluation', rv.result,
        'remarks', rv.remarks,
        'recorded_at', rv.recorded_at
      ))
      order by p.parameter_code
    ) as result_values
  from plantlab_lab.result_values rv
  join plantlab_lab.parameters p on p.id = rv.parameter_id
  group by rv.test_run_id
)
select
  r.id as request_id,
  r.request_code,
  r.source_module,
  r.source_entity,
  r.source_record_key,
  r.priority as request_priority,
  r.requested_at,
  r.due_at as request_due_at,
  r.status as request_status,
  ri.id as request_item_id,
  ri.priority as item_priority,
  ri.due_at as item_due_at,
  ri.status as request_item_status,
  tt.id as test_type_id,
  tt.test_code,
  tt.test_name,
  coalesce(current_run.method_id, ri.requested_method_id) as method_id,
  coalesce(current_run.method_code, requested_method.method_code) as method_code,
  coalesce(current_run.method_name, requested_method.method_name) as method_name,
  r.lot_id,
  l.canonical_lot_code,
  l.lot_code,
  l.product_id,
  p.sku,
  p.name as product_name,
  l.company_id,
  l.plant_site_id,
  l.stage_code,
  l.crop_category_code,
  l.seed_generation_code,
  l.crop_year,
  l.season_code,
  l.field_status_code,
  r.target_lab_site_id,
  lab_site.site_code as lab_site_code,
  lab_site.site_name as lab_site_name,
  current_run.sample_id,
  current_run.sample_code,
  current_run.external_accession_no,
  current_run.test_cycle_id,
  current_run.cycle_no,
  current_run.cycle_type,
  current_run.testing_program_code,
  current_run.test_run_id as current_test_run_id,
  current_run.test_run_code as current_test_run_code,
  current_run.attempt_no as current_attempt_no,
  current_run.test_run_status as current_test_run_status,
  current_run.incoming_at,
  current_run.incoming_date,
  current_run.final_observation_at,
  current_run.final_observation_date,
  current_run.tat_days,
  current_run.tat_elapsed_hours,
  summary.replicate_count,
  summary.average_normal_percent,
  summary.replicate_difference,
  summary.max_allowed_difference,
  summary.tolerance_evaluation,
  summary.recorded_result_percent,
  summary.recorded_result_evaluation,
  coalesce(payload.result_values, '{}'::jsonb) as result_values,
  greatest(
    r.updated_at,
    ri.updated_at,
    coalesce(current_run.latest_decision_at, '-infinity'::timestamptz),
    coalesce(current_run.final_observation_at, '-infinity'::timestamptz),
    coalesce(current_run.test_run_created_at, '-infinity'::timestamptz)
  ) as latest_activity_at
from plantlab_lab.requests r
join plantlab_lab.request_items ri on ri.request_id = r.id and ri.is_active
join plantlab_lab.test_types tt on tt.id = ri.test_type_id
left join plantlab_core.lots l on l.id = r.lot_id
join plantlab_master.products p on p.id = coalesce(l.product_id, r.product_id)
join plantlab_master.sites lab_site on lab_site.id = r.target_lab_site_id
left join plantlab_lab.methods requested_method on requested_method.id = ri.requested_method_id
left join ranked_runs current_run
  on current_run.request_item_id = ri.id and current_run.current_rank = 1
left join plantlab_reporting.v_germ_vigor_summary summary
  on summary.test_run_id = current_run.test_run_id
left join result_payload payload on payload.test_run_id = current_run.test_run_id;

create or replace view plantlab_reporting.v_receiving_harvest
with (security_invoker = true)
as
with lab_final_activity as (
  select
    tat.lot_id,
    max(tat.final_observation_at) as latest_final_observation_at
  from plantlab_reporting.v_lab_tat tat
  where tat.lot_id is not null
    and tat.final_observation_at is not null
  group by tat.lot_id
), lab_approval_activity as (
  select
    r.lot_id,
    max(rd.decided_at) as latest_approved_at
  from plantlab_lab.result_decisions rd
  join plantlab_lab.test_runs tr on tr.id = rd.test_run_id
  join plantlab_lab.request_items ri on ri.id = tr.request_item_id
  join plantlab_lab.requests r on r.id = ri.request_id
  where r.lot_id is not null
    and rd.resulting_status = 'APPROVED'
  group by r.lot_id
), lab_got_activity as (
  select
    r.lot_id,
    max(tre.event_at) as latest_got_delivery_at
  from plantlab_lab.test_run_events tre
  join plantlab_lab.test_runs tr on tr.id = tre.test_run_id
  join plantlab_lab.request_items ri on ri.id = tr.request_item_id
  join plantlab_lab.requests r on r.id = ri.request_id
  where r.lot_id is not null
    and tre.event_type = 'DELIVERED_GOT'
  group by r.lot_id
)
select
  l.id as lot_id,
  l.canonical_lot_code,
  l.lot_code,
  l.source_lot_code,
  l.product_id,
  p.sku,
  p.name as product_name,
  l.company_id,
  c.name as company_name,
  l.plant_site_id,
  plant_site.site_code as plant_site_code,
  plant_site.site_name as plant_site_name,
  l.stage_code,
  l.crop_category_code,
  l.seed_generation_code,
  l.crop_year,
  l.season_code,
  l.field_status_code,
  l.quantity as lot_quantity,
  l.unit_code as lot_unit_code,
  l.received_at as lot_received_at,
  l.status as lot_status,
  current_flags.active_flags,
  latest_receipt.sample_id,
  latest_receipt.sample_code,
  latest_receipt.sample_type,
  latest_receipt.external_accession_no,
  latest_receipt.incoming_at,
  latest_receipt.receipt_decision,
  latest_receipt.receipt_status,
  vigour.vigour_method_codes,
  vigour.vigour_method_names,
  shelling.shelling_started_at,
  shelling.shelling_completed_at,
  shelling.shelling_quantity_kg,
  lab_final.latest_final_observation_at,
  lab_approval.latest_approved_at,
  lab_got.latest_got_delivery_at,
  greatest(
    l.updated_at,
    coalesce(latest_receipt.activity_at, '-infinity'::timestamptz),
    coalesce(shelling.activity_at, '-infinity'::timestamptz),
    coalesce(lab_final.latest_final_observation_at, '-infinity'::timestamptz),
    coalesce(lab_approval.latest_approved_at, '-infinity'::timestamptz),
    coalesce(lab_got.latest_got_delivery_at, '-infinity'::timestamptz)
  ) as latest_activity_at
from plantlab_core.lots l
join plantlab_master.products p on p.id = l.product_id
join plantlab_master.companies c on c.id = l.company_id
left join plantlab_master.sites plant_site on plant_site.id = l.plant_site_id
left join lateral (
  select string_agg(
    lf.flag_code || coalesce('/' || lf.flag_subcode, ''),
    ', ' order by lf.started_at, lf.flag_code
  ) as active_flags
  from plantlab_core.lot_flags lf
  where lf.lot_id = l.id
    and lf.ended_at is null
) current_flags on true
left join lateral (
  select
    s.id as sample_id,
    s.sample_code,
    s.sample_type,
    sr.external_accession_no,
    coalesce(sr.source_received_at, sr.received_at, s.received_at) as incoming_at,
    sr.decision as receipt_decision,
    sr.status as receipt_status,
    greatest(s.updated_at, coalesce(sr.updated_at, '-infinity'::timestamptz))
      as activity_at
  from plantlab_core.samples s
  left join plantlab_lab.request_samples rs on rs.sample_id = s.id
  left join plantlab_lab.sample_receipts sr on sr.request_sample_id = rs.id
  where s.lot_id = l.id
  order by
    coalesce(sr.source_received_at, sr.received_at, s.received_at, s.created_at) desc,
    s.created_at desc
  limit 1
) latest_receipt on true
left join lateral (
  select
    string_agg(
      distinct coalesce(requested_method.method_code, run_method.method_code),
      ', ' order by coalesce(requested_method.method_code, run_method.method_code)
    )
      as vigour_method_codes,
    string_agg(
      distinct coalesce(requested_method.method_name, run_method.method_name),
      ', ' order by coalesce(requested_method.method_name, run_method.method_name)
    )
      as vigour_method_names
  from plantlab_lab.requests r
  join plantlab_lab.request_items ri on ri.request_id = r.id and ri.is_active
  join plantlab_lab.test_types tt on tt.id = ri.test_type_id
  left join plantlab_lab.methods requested_method on requested_method.id = ri.requested_method_id
  left join plantlab_lab.test_runs tr
    on tr.request_item_id = ri.id and tr.status <> 'CANCELLED'
  left join plantlab_lab.methods run_method on run_method.id = tr.method_id
  where r.lot_id = l.id
    and tt.test_code = 'VIGOUR'
    and r.status <> 'CANCELLED'
) vigour on true
left join lateral (
  select
    ps.started_at as shelling_started_at,
    ps.completed_at as shelling_completed_at,
    quantity.numeric_value as shelling_quantity_kg,
    greatest(ps.updated_at, coalesce(quantity.updated_at, '-infinity'::timestamptz))
      as activity_at
  from plantlab_plant.process_plans pp
  join plantlab_plant.process_steps ps on ps.plan_id = pp.id
  join plantlab_plant.process_types pt on pt.id = ps.process_type_id
  left join lateral (
    select pm.numeric_value, pm.updated_at
    from plantlab_plant.process_measurements pm
    where pm.process_step_id = ps.id
      and pm.measurement_code = 'BATCH_QUANTITY_KG'
    order by pm.measured_at desc, pm.sequence_no desc
    limit 1
  ) quantity on true
  where pp.lot_id = l.id
    and pt.process_code = 'SHELLING'
    and ps.status <> 'CANCELLED'
  order by coalesce(ps.completed_at, ps.started_at, ps.created_at) desc
  limit 1
) shelling on true
left join lab_final_activity lab_final on lab_final.lot_id = l.id
left join lab_approval_activity lab_approval on lab_approval.lot_id = l.id
left join lab_got_activity lab_got on lab_got.lot_id = l.id;

create or replace view plantlab_reporting.v_plant_daily
with (security_invoker = true)
as
with daily_rows as (
  select
    'PROCESS_MEASUREMENT'::text as source_type,
    pm.id as source_record_id,
    case
      when pm.process_step_id is not null then 'PROCESS_STEP'
      when pm.inspection_id is not null then 'LOT_INSPECTION'
      else 'SCOPE_INSPECTION'
    end as record_scope,
    coalesce(pm.process_step_id, pm.inspection_id, pm.scope_inspection_id)
      as parent_record_id,
    case
      when pm.process_step_id is not null
        then pp.plan_code || '/' || ps.sequence_no::text
      when pm.inspection_id is not null then i.inspection_code
      else si.inspection_code
    end as parent_record_code,
    coalesce(pp.lot_id, i.lot_id) as lot_id,
    coalesce(pp.site_id, inspection_lot.plant_site_id, si.site_id) as site_id,
    coalesce(plan_lot.company_id, inspection_lot.company_id, si.company_id)
      as company_id,
    coalesce(step_type.process_code, inspection_type.process_code, scope_type.process_code)
      as process_code,
    coalesce(step_type.process_name, inspection_type.process_name, scope_type.process_name)
      as process_name,
    pm.measurement_code as parameter_code,
    md.measurement_name as parameter_name,
    md.data_type,
    pm.sequence_no,
    pm.numeric_value,
    pm.text_value,
    pm.boolean_value,
    pm.unit_code,
    coalesce(i.result, si.result) as result,
    coalesce(ps.status, i.status, si.status) as status,
    pm.measured_at as recorded_at,
    pm.measured_by as recorded_by,
    pm.metadata
  from plantlab_plant.process_measurements pm
  join plantlab_plant.measurement_definitions md
    on md.measurement_code = pm.measurement_code
  left join plantlab_plant.process_steps ps on ps.id = pm.process_step_id
  left join plantlab_plant.process_plans pp on pp.id = ps.plan_id
  left join plantlab_core.lots plan_lot on plan_lot.id = pp.lot_id
  left join plantlab_plant.process_types step_type on step_type.id = ps.process_type_id
  left join plantlab_plant.inspections i on i.id = pm.inspection_id
  left join plantlab_core.lots inspection_lot on inspection_lot.id = i.lot_id
  left join plantlab_plant.process_types inspection_type on inspection_type.id = i.process_type_id
  left join plantlab_plant.scope_inspections si on si.id = pm.scope_inspection_id
  left join plantlab_plant.process_types scope_type on scope_type.id = si.process_type_id

  union all

  select
    'PLANT_TEST',
    t.id,
    'PLANT_TEST',
    t.id,
    t.test_code,
    t.lot_id,
    l.plant_site_id,
    l.company_id,
    pt.process_code,
    pt.process_name,
    t.test_type,
    t.test_type,
    case when t.numeric_value is not null then 'NUMERIC' else 'TEXT' end,
    t.attempt_no,
    t.numeric_value,
    t.text_value,
    null::boolean,
    t.unit_code,
    t.result,
    t.status,
    coalesce(t.tested_at, t.created_at),
    t.tested_by,
    '{}'::jsonb
  from plantlab_plant.tests t
  join plantlab_core.lots l on l.id = t.lot_id
  left join plantlab_plant.process_steps ps on ps.id = t.process_step_id
  left join plantlab_plant.process_types pt on pt.id = ps.process_type_id

  union all

  select
    'PLANT_TEST_COMPONENT',
    ptrv.id,
    'PLANT_TEST',
    t.id,
    t.test_code,
    t.lot_id,
    l.plant_site_id,
    l.company_id,
    pt.process_code,
    pt.process_name,
    p.parameter_code,
    p.parameter_name,
    p.data_type,
    1,
    ptrv.numeric_value,
    ptrv.text_value,
    ptrv.boolean_value,
    ptrv.unit_code,
    ptrv.result,
    t.status,
    ptrv.recorded_at,
    ptrv.recorded_by,
    '{}'::jsonb
  from plantlab_plant.test_result_values ptrv
  join plantlab_plant.tests t on t.id = ptrv.plant_test_id
  join plantlab_core.lots l on l.id = t.lot_id
  join plantlab_lab.parameters p on p.id = ptrv.parameter_id
  left join plantlab_plant.process_steps ps on ps.id = t.process_step_id
  left join plantlab_plant.process_types pt on pt.id = ps.process_type_id
)
select
  daily.source_type,
  daily.source_record_id,
  daily.record_scope,
  daily.parent_record_id,
  daily.parent_record_code,
  daily.lot_id,
  l.canonical_lot_code,
  l.lot_code,
  l.product_id,
  product.sku,
  product.name as product_name,
  daily.site_id,
  site.site_code,
  site.site_name,
  daily.company_id,
  daily.process_code,
  daily.process_name,
  daily.parameter_code,
  daily.parameter_name,
  daily.data_type,
  daily.sequence_no,
  daily.numeric_value,
  daily.text_value,
  daily.boolean_value,
  daily.unit_code,
  daily.result,
  daily.status,
  daily.recorded_at,
  daily.recorded_by,
  (daily.recorded_at at time zone coalesce(site.timezone_name, 'UTC'))::date
    as local_recorded_date,
  date_trunc(
    'month',
    daily.recorded_at at time zone coalesce(site.timezone_name, 'UTC')
  )::date as local_recorded_month,
  extract(
    isoyear from daily.recorded_at at time zone coalesce(site.timezone_name, 'UTC')
  )::integer as local_recorded_iso_year,
  extract(
    week from daily.recorded_at at time zone coalesce(site.timezone_name, 'UTC')
  )::integer as local_recorded_iso_week,
  daily.metadata
from daily_rows daily
left join plantlab_core.lots l on l.id = daily.lot_id
left join plantlab_master.products product on product.id = l.product_id
left join plantlab_master.sites site on site.id = daily.site_id;

grant select on
  plantlab_reporting.v_lab_tat,
  plantlab_reporting.v_germ_vigor_detail,
  plantlab_reporting.v_germ_vigor_summary,
  plantlab_reporting.v_quality_information_current,
  plantlab_reporting.v_receiving_harvest,
  plantlab_reporting.v_plant_daily
to authenticated, service_role;

comment on view plantlab_reporting.v_lab_tat is
  'Confirmed TAT definition: local final observation date minus local incoming date, per Test Run/cycle.';
comment on view plantlab_reporting.v_germ_vigor_detail is
  'Raw Germination/Vigour replicate observations for application detail and manual-report export.';
comment on view plantlab_reporting.v_germ_vigor_summary is
  'Derived replicate statistics and tolerance evaluation; not a substitute for the approved Lab decision.';
comment on view plantlab_reporting.v_quality_information_current is
  'One current row per active Lab request item, with latest ranked Test Run and result payload.';
comment on view plantlab_reporting.v_receiving_harvest is
  'One current Receiving Harvest read model per canonical Lot.';
comment on view plantlab_reporting.v_plant_daily is
  'Normalized daily Plant measurements and Plant test results for filtering and pivoting.';
-- Canonical source: 20260812000500_manual_import_staging_rpc.sql
set local lock_timeout = '5s';
set local statement_timeout = '2min';

-- Migration 018: service-role-only, idempotent staging ingress for audited
-- manual workbooks. This function writes only plantlab_integration.import_* tables;
-- it never creates or updates canonical Plant/Lab transactions.

create or replace function plantlab_integration.stage_manual_import_rows(
  p_source_type text,
  p_source_file_name text,
  p_source_file_sha256 text,
  p_source_file_size bigint,
  p_source_modified_at timestamptz,
  p_parser_version integer,
  p_batch_metadata jsonb,
  p_rows jsonb
)
returns table (
  batch_id uuid,
  accepted_chunk_rows integer,
  staged_total_rows integer,
  batch_status text
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch_id uuid;
  v_chunk_count integer;
  v_total_count integer;
  v_status text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'Manual import staging requires the service_role'
      using errcode = '42501';
  end if;

  if p_source_type is null
    or upper(p_source_type) !~ '^[A-Z][A-Z0-9_]*$' then
    raise exception 'Invalid source type: %', p_source_type
      using errcode = '22023';
  end if;

  if nullif(btrim(p_source_file_name), '') is null then
    raise exception 'Source file name is required'
      using errcode = '22023';
  end if;

  if p_source_file_sha256 is null
    or lower(p_source_file_sha256) !~ '^[0-9a-f]{64}$' then
    raise exception 'Source file SHA-256 is invalid'
      using errcode = '22023';
  end if;

  if p_parser_version is null or p_parser_version <= 0 then
    raise exception 'Parser version must be greater than zero'
      using errcode = '22023';
  end if;

  if p_batch_metadata is null or jsonb_typeof(p_batch_metadata) <> 'object' then
    raise exception 'Batch metadata must be a JSON object'
      using errcode = '22023';
  end if;

  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'Rows payload must be a JSON array'
      using errcode = '22023';
  end if;

  v_chunk_count := jsonb_array_length(p_rows);
  if v_chunk_count > 200 then
    raise exception 'A staging chunk may contain at most 200 rows'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      upper(p_source_type) || ':' || lower(p_source_file_sha256)
      || ':' || p_parser_version::text,
      0
    )
  );

  insert into plantlab_integration.import_batches (
    source_type,
    source_file_name,
    source_file_sha256,
    source_file_size,
    source_modified_at,
    parser_version,
    status,
    imported_by,
    metadata
  ) values (
    upper(p_source_type),
    p_source_file_name,
    lower(p_source_file_sha256),
    p_source_file_size,
    p_source_modified_at,
    p_parser_version,
    'REGISTERED',
    auth.uid(),
    p_batch_metadata
  )
  on conflict (source_type, source_file_sha256, parser_version) do update
  set source_file_name = excluded.source_file_name,
      source_file_size = excluded.source_file_size,
      source_modified_at = excluded.source_modified_at,
      metadata = plantlab_integration.import_batches.metadata || excluded.metadata,
      updated_at = now()
  returning id into v_batch_id;

  if exists (
    select 1
    from jsonb_to_recordset(p_rows) as incoming(
      sheet_name text,
      source_row_number integer,
      source_record_key text,
      row_sha256 text,
      raw_payload jsonb,
      normalized_payload jsonb
    )
    join plantlab_integration.import_rows existing
      on existing.batch_id = v_batch_id
      and existing.sheet_name = incoming.sheet_name
      and existing.source_row_number = incoming.source_row_number
    where existing.row_sha256 <> lower(incoming.row_sha256)
  ) then
    raise exception 'Existing staged position has a different row hash; increase parser_version'
      using errcode = '23505';
  end if;

  insert into plantlab_integration.import_rows (
    batch_id,
    sheet_name,
    source_row_number,
    source_record_key,
    row_sha256,
    raw_payload,
    normalized_payload,
    status
  )
  select
    v_batch_id,
    incoming.sheet_name,
    incoming.source_row_number,
    incoming.source_record_key,
    lower(incoming.row_sha256),
    incoming.raw_payload,
    coalesce(incoming.normalized_payload, '{}'::jsonb),
    'RAW'
  from jsonb_to_recordset(p_rows) as incoming(
    sheet_name text,
    source_row_number integer,
    source_record_key text,
    row_sha256 text,
    raw_payload jsonb,
    normalized_payload jsonb
  )
  where nullif(btrim(incoming.sheet_name), '') is not null
    and incoming.source_row_number > 0
    and incoming.row_sha256 = lower(incoming.row_sha256)
    and incoming.row_sha256 ~ '^[0-9a-f]{64}$'
    and jsonb_typeof(incoming.raw_payload) = 'object'
    and jsonb_typeof(coalesce(incoming.normalized_payload, '{}'::jsonb)) = 'object'
  on conflict on constraint import_rows_source_position_uq do nothing;

  if (
    select count(*)
    from jsonb_to_recordset(p_rows) as incoming(
      sheet_name text,
      source_row_number integer,
      source_record_key text,
      row_sha256 text,
      raw_payload jsonb,
      normalized_payload jsonb
    )
    where nullif(btrim(incoming.sheet_name), '') is not null
      and incoming.source_row_number > 0
      and incoming.row_sha256 = lower(incoming.row_sha256)
      and incoming.row_sha256 ~ '^[0-9a-f]{64}$'
      and jsonb_typeof(incoming.raw_payload) = 'object'
      and jsonb_typeof(coalesce(incoming.normalized_payload, '{}'::jsonb)) = 'object'
  ) <> v_chunk_count then
    raise exception 'One or more staging rows have an invalid shape'
      using errcode = '22023';
  end if;

  select count(*)::integer
    into v_total_count
  from plantlab_integration.import_rows ir
  where ir.batch_id = v_batch_id;

  update plantlab_integration.import_batches ib
  set total_row_count = v_total_count,
      status = 'STAGED',
      started_at = coalesce(ib.started_at, now()),
      updated_at = now()
  where ib.id = v_batch_id
  returning ib.status into v_status;

  return query
  select v_batch_id, v_chunk_count, v_total_count, v_status;
end;
$$;

create or replace view plantlab_reporting.v_manual_import_staging_reconciliation
with (security_invoker = true)
as
with row_counts as (
  select
    ir.batch_id,
    count(*)::integer as actual_staged_rows,
    count(*) filter (where ir.status = 'RAW')::integer as raw_rows,
    count(*) filter (where ir.status = 'VALIDATED')::integer as validated_rows,
    count(*) filter (where ir.status = 'MAPPED')::integer as mapped_rows,
    count(*) filter (where ir.status = 'REJECTED')::integer as rejected_rows,
    min(ir.source_row_number) as minimum_source_row,
    max(ir.source_row_number) as maximum_source_row
  from plantlab_integration.import_rows ir
  group by ir.batch_id
), issue_counts as (
  select
    ii.batch_id,
    count(*) filter (where ii.status = 'OPEN')::integer as open_issue_count,
    count(*) filter (
      where ii.status = 'OPEN' and ii.severity = 'BLOCKING'
    )::integer as open_blocking_issue_count
  from plantlab_integration.import_issues ii
  group by ii.batch_id
)
select
  ib.id as batch_id,
  ib.source_type,
  ib.source_file_name,
  ib.source_file_sha256,
  ib.parser_version,
  ib.status as batch_status,
  ib.total_row_count as declared_total_rows,
  coalesce(rc.actual_staged_rows, 0) as actual_staged_rows,
  coalesce(rc.raw_rows, 0) as raw_rows,
  coalesce(rc.validated_rows, 0) as validated_rows,
  coalesce(rc.mapped_rows, 0) as mapped_rows,
  coalesce(rc.rejected_rows, 0) as rejected_rows,
  coalesce(ic.open_issue_count, 0) as open_issue_count,
  coalesce(ic.open_blocking_issue_count, 0) as open_blocking_issue_count,
  rc.minimum_source_row,
  rc.maximum_source_row,
  ib.created_at,
  ib.updated_at
from plantlab_integration.import_batches ib
left join row_counts rc on rc.batch_id = ib.id
left join issue_counts ic on ic.batch_id = ib.id;

