create schema plantlab_api;
comment on schema plantlab_api is
  'Selected, role-scoped endpoints for the Plant and Lab applications.';

revoke all on schema plantlab_api from PUBLIC, anon, authenticated;
grant usage on schema plantlab_api to authenticated;

create function plantlab_api.list_lab_requests(
  p_module text,
  p_limit integer default 50,
  p_offset integer default 0
)
returns table (
  request_id uuid,
  request_code text,
  lot_id uuid,
  lot_code text,
  product_id bigint,
  request_site_id uuid,
  target_lab_site_id uuid,
  test_codes text[],
  status text,
  priority text,
  requested_at timestamptz,
  due_at timestamptz,
  sampling_instruction text
)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    r.id,
    r.request_code,
    r.lot_id,
    l.lot_code,
    r.product_id,
    r.request_site_id,
    r.target_lab_site_id,
    array(
      select distinct tt.test_code
      from plantlab_lab.request_items ri
      join plantlab_lab.test_types tt on tt.id = ri.test_type_id
      where ri.request_id = r.id and ri.is_active
      order by tt.test_code
    ),
    r.status,
    r.priority,
    r.requested_at,
    r.due_at,
    r.sampling_instruction
  from plantlab_lab.requests r
  left join plantlab_core.lots l on l.id = r.lot_id
  join plantlab_master.sites target_site on target_site.id = r.target_lab_site_id
  left join plantlab_master.sites request_site on request_site.id = r.request_site_id
  where auth.uid() is not null
    and case upper(btrim(p_module))
      when 'LAB' then plantlab_platform.has_permission(
        'LAB', 'request.read', r.target_lab_site_id,
        coalesce(l.company_id, target_site.company_id, request_site.company_id)
      )
      when 'PLANT' then
        r.source_module = 'PLANT'
        and r.request_site_id is not null
        and r.status <> 'DRAFT'
        and plantlab_platform.has_permission(
          'PLANT', 'request.read', r.request_site_id,
          coalesce(l.company_id, target_site.company_id, request_site.company_id)
        )
      else false
    end
  order by coalesce(r.requested_at, r.created_at) desc, r.id desc
  limit least(greatest(coalesce(p_limit, 50), 0), 100)
  offset greatest(coalesce(p_offset, 0), 0);
$$;

revoke all on function plantlab_api.list_lab_requests(text, integer, integer)
  from PUBLIC, anon, authenticated;
grant execute on function plantlab_api.list_lab_requests(text, integer, integer)
  to authenticated;

comment on function plantlab_api.list_lab_requests(text, integer, integer) is
  'Lists canonical requests for the selected module and the caller''s site scope. Plant sees routed, submitted requests only. Underlying RLS still applies.';
-- Canonical source: 20260817000100_current_user_access_context.sql
set local lock_timeout = '5s';
set local statement_timeout = '60s';

create or replace function plantlab_api.get_current_access_context()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception 'Authentication is required' using errcode = '28000';
  end if;

  with active_assignments as (
    select
      ura.id as assignment_id,
      ura.site_id,
      ura.company_id,
      mr.module_code,
      rd.role_code,
      rd.role_name,
      rd.permissions
    from plantlab_platform.user_role_assignments ura
    join plantlab_platform.role_definitions rd on rd.id = ura.role_id
    join plantlab_platform.module_registry mr on mr.id = rd.module_id
    where ura.user_id = v_user_id
      and ura.is_active
      and rd.is_active
      and mr.is_active
      and ura.valid_from <= now()
      and (ura.valid_until is null or ura.valid_until > now())
  ), flags as (
    select
      coalesce(bool_or(module_code = 'PLATFORM'), false) as is_platform,
      coalesce(bool_or(module_code in ('PLATFORM', 'PLANT')), false)
        as can_access_plant,
      coalesce(bool_or(
        module_code in ('PLATFORM', 'LAB')
        or (
          module_code = 'PLANT'
          and (permissions ? '*' or permissions ? 'result.read')
        )
      ), false) as can_access_lab,
      coalesce(bool_or(
        module_code = 'PLATFORM'
        and (permissions ? '*' or permissions ? 'iam.manage')
      ), false) as can_manage_users
    from active_assignments
  ), role_scope as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'module_code', module_code,
          'role_code', role_code,
          'role_name', role_name,
          'site_id', site_id,
          'company_id', company_id
        )
        order by module_code, role_code, site_id nulls first
      ),
      '[]'::jsonb
    ) as roles
    from active_assignments
  ), module_scope as (
    select coalesce(
      jsonb_agg(module_code order by module_code),
      '[]'::jsonb
    ) as modules
    from (
      select distinct module_code
      from active_assignments
    ) m
  ), primary_role as (
    select role_name
    from active_assignments
    order by
      case module_code
        when 'PLATFORM' then 1
        when 'LAB' then 2
        when 'PLANT' then 3
        else 4
      end,
      case role_code
        when 'PLATFORM_ADMIN' then 1
        when 'LAB_QA_APPROVER' then 2
        when 'PLANT_SPV' then 3
        else 4
      end,
      role_code
    limit 1
  ), site_scope as (
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'site_code', s.site_code,
          'site_name', s.site_name,
          'site_type', s.site_type,
          'company_id', s.company_id
        )
        order by s.site_type, s.site_code
      ),
      '[]'::jsonb
    ) as sites
    from plantlab_master.sites s
    cross join flags f
    where s.is_active
      and (
        f.is_platform
        or exists (
          select 1
          from active_assignments a
          where a.site_id = s.id
        )
      )
  )
  select jsonb_build_object(
    'user_id', v_user_id,
    'primary_role_name', coalesce((select role_name from primary_role), 'No active role'),
    'modules', ms.modules,
    'roles', rs.roles,
    'sites', ss.sites,
    'can_access_plant', f.can_access_plant,
    'can_access_lab', f.can_access_lab,
    'can_manage_users', f.can_manage_users
  )
  into v_result
  from flags f
  cross join role_scope rs
  cross join module_scope ms
  cross join site_scope ss;

  return v_result;
end;
$$;

comment on function plantlab_api.get_current_access_context() is
  'Returns the authenticated user active Plant/Lab module, role, company, and site context for server-rendered UI authorization.';

revoke all on function plantlab_api.get_current_access_context()
  from PUBLIC, anon;
grant execute on function plantlab_api.get_current_access_context()
  to authenticated, service_role;
-- Keep external module definitions dormant so their business states can be reused later.
update plantlab_platform.module_registry
set is_active = false
where module_code not in ('PLATFORM', 'PLANT', 'LAB');

-- Master loading is a trusted operation, separate from the client queue.
revoke all on plantlab_master.companies, plantlab_master.products from PUBLIC, anon, authenticated;
grant select on plantlab_master.companies, plantlab_master.products to authenticated;
grant usage, select on sequence plantlab_master.companies_id_seq, plantlab_master.products_id_seq to service_role;

create policy standalone_companies_read on plantlab_master.companies
for select to authenticated using (
  plantlab_platform.has_module_permission('PLATFORM', 'site.manage')
  or exists (
    select from plantlab_platform.user_role_assignments a
    join plantlab_platform.role_definitions rd on rd.id = a.role_id
    join plantlab_platform.module_registry mr on mr.id = rd.module_id
    where a.user_id = auth.uid() and a.company_id = companies.id
      and a.is_active and rd.is_active and mr.is_active
      and mr.module_code in ('PLANT', 'LAB')
      and a.valid_from <= now() and (a.valid_until is null or a.valid_until > now())
  )
);

create policy standalone_products_read on plantlab_master.products
for select to authenticated using (
  plantlab_platform.has_module_permission('PLATFORM', 'site.manage')
  or plantlab_platform.has_module_permission('PLANT', 'plantlab_master.read')
  or plantlab_platform.has_module_permission('LAB', 'plantlab_master.read')
);

-- History is carried by the canonical source-link table, never a CompFeed FK.
comment on table plantlab_core.lot_sources is
  'Optional source provenance for a lot. Source keys are informational and do not reference an external database.';

-- Hosted port of 20261106000200_plant_lab_request_commands.sql (normalized source SHA-256 88efdb4ced1c8e7ca22f49d6ec8776d5bacf3036db7bd7682af5fa54885105db)

create function plantlab_api.get_request_options()
returns jsonb
language sql stable security definer set search_path = ''
as $$
  with lots as (
    select l.id, l.lot_code, l.canonical_lot_code, l.company_id
    from plantlab_core.lots l
    join plantlab_master.sites s on s.id = l.plant_site_id
      and s.company_id = l.company_id and s.site_type = 'PLANT' and s.is_active
    where plantlab_platform.has_permission('PLANT', 'request.create', s.id, l.company_id)
    order by l.created_at desc, l.id
    limit 100
  )
  select jsonb_build_object(
    'lots', coalesce((select jsonb_agg(to_jsonb(l) order by l.lot_code, l.id) from lots l), '[]'::jsonb),
    'lab_sites', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'site_name', s.site_name, 'company_id', s.company_id)
                       order by s.site_name, s.id)
      from plantlab_master.sites s
      where s.site_type = 'LAB' and s.is_active
        and exists (select from lots l where l.company_id = s.company_id)
    ), '[]'::jsonb),
    'test_types', coalesce((
      select jsonb_agg(jsonb_build_object('test_code', t.test_code, 'test_name', t.test_name)
                       order by t.test_name, t.test_code)
      from plantlab_lab.test_types t where t.is_active and exists (select from lots)
    ), '[]'::jsonb)
  );
$$;

create function plantlab_api.submit_plant_lab_request(
  p_lot_id uuid, p_target_lab_site_id uuid, p_test_code text, p_submission_id uuid,
  p_sampling_instruction text default null
)
returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_lot plantlab_core.lots;
  v_request plantlab_lab.requests;
  v_test_id uuid;
  v_instruction text := nullif(btrim(p_sampling_instruction), '');
  v_key text;
begin
  if v_actor is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_lot_id is null or p_target_lab_site_id is null or p_submission_id is null
    or nullif(btrim(p_test_code), '') is null or length(v_instruction) > 500 then
    raise exception 'Lot, target Lab, test and submission ID are required; instruction maximum is 500 characters'
      using errcode = '22023';
  end if;

  select l.* into v_lot from plantlab_core.lots l
  join plantlab_master.sites s on s.id = l.plant_site_id and s.company_id = l.company_id
    and s.site_type = 'PLANT' and s.is_active
  where l.id = p_lot_id and plantlab_platform.has_permission('PLANT', 'request.create', s.id, l.company_id);
  if not found then
    raise exception 'Lot is outside the assigned Plant scope' using errcode = '42501';
  end if;
  if not exists (
    select from plantlab_master.sites s where s.id = p_target_lab_site_id
      and s.site_type = 'LAB' and s.is_active and s.company_id = v_lot.company_id
  ) then
    raise exception 'Target Lab must be active and belong to the Lot company' using errcode = '22023';
  end if;

  v_key := 'PLANT_LAB_SUBMIT:' || v_actor::text || ':' || p_submission_id::text;
  perform pg_advisory_xact_lock(hashtextextended(v_key, 0));
  select r.* into v_request from plantlab_lab.requests r where r.idempotency_key = v_key;
  if found then
    if v_request.lot_id is distinct from p_lot_id
      or v_request.target_lab_site_id is distinct from p_target_lab_site_id
      or v_request.sampling_instruction is distinct from v_instruction
      or not exists (
        select from plantlab_lab.request_items i join plantlab_lab.test_types t on t.id = i.test_type_id
        where i.request_id = v_request.id and t.test_code = upper(btrim(p_test_code))
      ) then
      raise exception 'Submission ID already used with different details' using errcode = '23505';
    end if;
  else
    select t.id into v_test_id from plantlab_lab.test_types t
    where t.test_code = upper(btrim(p_test_code)) and t.is_active;
    if not found then
      raise exception 'Test type is not active' using errcode = '22023';
    end if;
    insert into plantlab_lab.requests (
      source_module, lot_id, product_id, request_site_id, target_lab_site_id,
      requested_by, created_by, sampling_instruction, idempotency_key
    ) values (
      'PLANT', v_lot.id, v_lot.product_id, v_lot.plant_site_id, p_target_lab_site_id,
      v_actor, v_actor, v_instruction, v_key
    ) returning * into v_request;
    insert into plantlab_lab.request_items (request_id, test_type_id, created_by)
    values (v_request.id, v_test_id, v_actor);
    select * into v_request from plantlab_lab.submit_request(v_request.id);
  end if;

  return jsonb_build_object('request_id', v_request.id, 'request_code', v_request.request_code,
    'status', v_request.status);
end;
$$;

create function plantlab_api.accept_plant_lab_request(p_request_id uuid)
returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_request plantlab_lab.requests;
begin
  if v_actor is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  select r.* into v_request from plantlab_lab.requests r
  join plantlab_core.lots l on l.id = r.lot_id
  join plantlab_master.sites s on s.id = r.target_lab_site_id and s.company_id = l.company_id
    and s.site_type = 'LAB' and s.is_active
  where r.id = p_request_id and r.source_module = 'PLANT'
    and plantlab_platform.has_permission('LAB', 'request.write', s.id, l.company_id)
  for update of r;
  if not found then
    raise exception 'Request is outside the assigned Lab scope' using errcode = '42501';
  end if;
  if v_request.status = 'REQUESTED' then
    update plantlab_lab.requests set status = 'ACCEPTED', updated_by = v_actor
    where id = v_request.id returning * into v_request;
  elsif v_request.status <> 'ACCEPTED' then
    raise exception 'Request is not in a state that can be accepted' using errcode = '55000';
  end if;

  return jsonb_build_object('request_id', v_request.id, 'request_code', v_request.request_code,
    'status', v_request.status);
end;
$$;

revoke all on function plantlab_api.get_request_options(),
