-- Hosted port of 20261106000300_plant_lab_sample_handoff.sql (normalized source SHA-256 8ac10e99e7a02a66b919a4197681fe2c34cd4a660cd2f1d0161ea851f6f9d316)

-- Permit Plant only for the two logistics transitions, with matching dispatch evidence.
create or replace function plantlab_lab.enforce_request_transition_actor()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_company_id bigint;
  v_plant_handoff boolean := false;
begin
  select l.company_id into v_company_id from plantlab_core.lots l where l.id = new.lot_id;
  if v_company_id is null then
    select coalesce(target_site.company_id, request_site.company_id) into v_company_id
    from plantlab_master.sites target_site
    left join plantlab_master.sites request_site on request_site.id = new.request_site_id
    where target_site.id = new.target_lab_site_id;
  end if;

  if old.source_module = 'PLANT' and new.source_module = old.source_module
    and new.lot_id = old.lot_id and new.request_site_id = old.request_site_id
    and new.target_lab_site_id = old.target_lab_site_id
    and (old.status, new.status) in (('ACCEPTED', 'PREPARED'), ('PREPARED', 'SENT'))
    and plantlab_platform.has_permission('PLANT', 'dispatch.write', old.request_site_id, v_company_id) then
    v_plant_handoff := exists (
      select from plantlab_lab.request_samples rs
      join plantlab_core.samples s on s.id = rs.sample_id and s.lot_id = old.lot_id
      join plantlab_plant.sample_dispatches d on d.lab_request_id = rs.request_id and d.sample_id = s.id
      where rs.request_id = old.id and rs.is_primary and s.status = new.status
        and d.status = new.status and d.source_site_id = old.request_site_id
        and d.target_lab_site_id = old.target_lab_site_id
    );
  end if;

  if old.status <> 'DRAFT' and not v_plant_handoff
    and not plantlab_platform.has_permission('LAB', 'request.write', new.target_lab_site_id, v_company_id) then
    raise exception 'Only the assigned site may advance the Lab request' using errcode = '42501';
  end if;

  if old.status = 'IN_REVIEW' and new.status in ('APPROVED', 'REJECTED', 'RETEST') then
    if not plantlab_platform.has_permission('LAB', 'result.approve', new.target_lab_site_id, v_company_id) then
      raise exception 'Final Lab Request decision requires result.approve permission' using errcode = '42501';
    end if;
    if new.status = 'APPROVED' and exists (
      select from plantlab_lab.request_items ri
      where ri.request_id = new.id and ri.is_active and ri.status <> 'APPROVED'
    ) then
      raise exception 'All active Lab Request items must be APPROVED first' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

create function plantlab_lab.lock_plant_sample_handoff(p_request_id uuid, p_module text)
returns plantlab_lab.requests
language plpgsql set search_path = ''
as $$
declare
  v_request plantlab_lab.requests;
begin
  select r.* into v_request from plantlab_lab.requests r
  join plantlab_core.lots l on l.id = r.lot_id and l.plant_site_id = r.request_site_id
  join plantlab_master.sites src on src.id = r.request_site_id and src.company_id = l.company_id
    and src.site_type = 'PLANT' and src.is_active
  join plantlab_master.sites dst on dst.id = r.target_lab_site_id and dst.company_id = l.company_id
    and dst.site_type = 'LAB' and dst.is_active
  where r.id = p_request_id and r.source_module = 'PLANT' and auth.uid() is not null
    and case p_module
      when 'PLANT' then plantlab_platform.has_permission('PLANT', 'sample.write', src.id, l.company_id)
        and plantlab_platform.has_permission('PLANT', 'dispatch.write', src.id, l.company_id)
      when 'LAB' then plantlab_platform.has_permission('LAB', 'receipt.write', dst.id, l.company_id)
        and plantlab_platform.has_permission('LAB', 'request.write', dst.id, l.company_id)
      else false end
  for update of r;
  if not found then
    raise exception 'Request is outside the assigned site scope' using errcode = '42501';
  end if;
  return v_request;
end;
$$;
revoke all on function plantlab_lab.lock_plant_sample_handoff(uuid,text) from PUBLIC, anon, authenticated, service_role;

create function plantlab_api.prepare_lab_sample(
  p_request_id uuid, p_quantity_grams numeric, p_condition text
)
returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_request plantlab_lab.requests;
  v_sample plantlab_core.samples;
  v_dispatch plantlab_plant.sample_dispatches;
  v_condition text := nullif(btrim(p_condition), '');
  v_actor uuid := auth.uid();
begin
  v_request := plantlab_lab.lock_plant_sample_handoff(p_request_id, 'PLANT');
  if p_quantity_grams is null or p_quantity_grams <= 0 or p_quantity_grams >= 'Infinity'::numeric
    or v_condition is null or length(v_condition) > 500 then
    raise exception 'Positive weight in grams and condition (up to 500 characters) are required' using errcode = '22023';
  end if;

  select s.* into v_sample from plantlab_lab.request_samples rs
  join plantlab_core.samples s on s.id = rs.sample_id
  where rs.request_id = v_request.id and rs.is_primary;
  if found then
    select d.* into v_dispatch from plantlab_plant.sample_dispatches d
    where d.lab_request_id = v_request.id and d.sample_id = v_sample.id;
    if not found or v_request.status not in ('PREPARED', 'SENT', 'RECEIVED') then
      raise exception 'A primary sample already exists outside this handoff' using errcode = '55000';
    end if;
    if v_dispatch.quantity is distinct from p_quantity_grams or v_dispatch.unit_code is distinct from 'G'
      or v_dispatch.condition_at_dispatch is distinct from v_condition then
      raise exception 'Sample was already prepared with different details' using errcode = '23505';
    end if;
  else
    if v_request.status <> 'ACCEPTED' then
      raise exception 'Lab must accept the request before Plant can prepare the sample' using errcode = '55000';
    end if;
    insert into plantlab_core.samples (
      lot_id, sample_type, source_module, source_site_id, quantity, unit_code,
      collected_at, collected_by, sample_condition, created_by
    ) values (
      v_request.lot_id, 'LAB_REQUEST', 'PLANT', v_request.request_site_id,
      p_quantity_grams, 'G', now(), v_actor, v_condition, v_actor
    ) returning * into v_sample;
    insert into plantlab_lab.request_samples (request_id, sample_id, purpose, is_primary, linked_by)
    values (v_request.id, v_sample.id, 'LAB_REQUEST', true, v_actor);
    insert into plantlab_plant.sample_dispatches (
      sample_id, lab_request_id, source_site_id, target_lab_site_id, prepared_by,
      prepared_at, quantity, unit_code, condition_at_dispatch
    ) values (
      v_sample.id, v_request.id, v_request.request_site_id, v_request.target_lab_site_id,
      v_actor, now(), p_quantity_grams, 'G', v_condition
    ) returning * into v_dispatch;
    insert into plantlab_lab.custody_events (sample_id, request_id, event_type, from_site_id, performed_by,
      condition_notes, reference_type, reference_key)
    values (v_sample.id, v_request.id, 'PREPARED', v_request.request_site_id, v_actor,
      v_condition, 'SAMPLE_DISPATCH', v_dispatch.id::text);
    update plantlab_lab.requests set status = 'PREPARED', updated_by = v_actor
    where id = v_request.id returning * into v_request;
  end if;

  return jsonb_build_object('sample_code', v_sample.sample_code, 'dispatch_code', v_dispatch.dispatch_code,
    'status', v_request.status);
end;
$$;

create function plantlab_api.send_lab_sample(p_request_id uuid)
returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_request plantlab_lab.requests;
  v_dispatch plantlab_plant.sample_dispatches;
  v_actor uuid := auth.uid();
begin
  v_request := plantlab_lab.lock_plant_sample_handoff(p_request_id, 'PLANT');
  select d.* into v_dispatch from plantlab_lab.request_samples rs
  join plantlab_plant.sample_dispatches d on d.lab_request_id = rs.request_id and d.sample_id = rs.sample_id
  where rs.request_id = v_request.id and rs.is_primary;
  if not found then
    raise exception 'Sample must be prepared before sending' using errcode = '55000';
  end if;
  if v_request.status = 'PREPARED' and v_dispatch.status = 'PREPARED' then
    update plantlab_core.samples set status = 'SENT', sent_at = now(), updated_by = v_actor
    where id = v_dispatch.sample_id and status = 'PREPARED';
    if not found then
      raise exception 'Sample status is inconsistent with dispatch' using errcode = '55000';
    end if;
    update plantlab_plant.sample_dispatches set status = 'SENT', sent_at = now(), sent_by = v_actor
    where id = v_dispatch.id;
    insert into plantlab_lab.custody_events (sample_id, request_id, event_type, from_site_id, to_site_id,
      performed_by, reference_type, reference_key)
    values (v_dispatch.sample_id, v_request.id, 'DISPATCHED', v_dispatch.source_site_id,
      v_dispatch.target_lab_site_id, v_actor, 'SAMPLE_DISPATCH', v_dispatch.id::text);
    update plantlab_lab.requests set status = 'SENT', updated_by = v_actor
    where id = v_request.id returning * into v_request;
  elsif not (v_request.status in ('SENT', 'RECEIVED') and v_dispatch.sent_at is not null) then
    raise exception 'Sample is not in a state that can be sent' using errcode = '55000';
  end if;
  return jsonb_build_object('dispatch_code', v_dispatch.dispatch_code, 'status', v_request.status);
end;
$$;

create function plantlab_api.receive_lab_sample(
  p_request_id uuid, p_sample_code text, p_received_grams numeric, p_condition text
)
returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  v_request plantlab_lab.requests;
  v_receipt plantlab_lab.sample_receipts;
  v_request_sample_id uuid;
  v_sample_status text;
  v_dispatch_status text;
  v_condition text := nullif(btrim(p_condition), '');
begin
  v_request := plantlab_lab.lock_plant_sample_handoff(p_request_id, 'LAB');
  if p_received_grams is null or p_received_grams <= 0 or p_received_grams >= 'Infinity'::numeric
    or v_condition is null or length(v_condition) > 500 or nullif(btrim(p_sample_code), '') is null then
    raise exception 'Sample code, positive weight in grams, and condition are required' using errcode = '22023';
  end if;
  select rs.id, s.status, d.status into v_request_sample_id, v_sample_status, v_dispatch_status
  from plantlab_lab.request_samples rs
  join plantlab_core.samples s on s.id = rs.sample_id and s.lot_id = v_request.lot_id
  join plantlab_plant.sample_dispatches d on d.lab_request_id = rs.request_id and d.sample_id = s.id
  where rs.request_id = v_request.id and rs.is_primary and s.sample_code = upper(btrim(p_sample_code));
  if not found then
    raise exception 'Sample code does not match the prepared request' using errcode = '22023';
  end if;
  select r.* into v_receipt from plantlab_lab.sample_receipts r where r.request_sample_id = v_request_sample_id;
  if found then
    if v_receipt.decision is distinct from 'ACCEPT' or v_receipt.received_quantity is distinct from p_received_grams
      or v_receipt.unit_code is distinct from 'G' or v_receipt.condition_notes is distinct from v_condition then
      raise exception 'Receipt was already recorded with different details' using errcode = '23505';
    end if;
  else
    if v_request.status <> 'SENT' or v_sample_status <> 'SENT' or v_dispatch_status not in ('SENT', 'DELIVERED') then
      raise exception 'Plant must send the sample before Lab can receive it' using errcode = '55000';
    end if;
    select * into v_receipt from plantlab_lab.record_sample_receipt(
      v_request_sample_id, 'ACCEPT', p_received_grams, 'G', v_condition
    );
    v_request.status := 'RECEIVED';
  end if;
  return jsonb_build_object('receipt_code', v_receipt.receipt_code, 'status', v_request.status);
end;
$$;

create function plantlab_api.list_sample_handoffs(p_request_ids uuid[], p_module text)
returns table (
  request_id uuid, sample_code text, dispatch_code text, sent_grams numeric,
  dispatch_condition text, receipt_code text, received_grams numeric, receipt_condition text
)
language sql stable security definer set search_path = ''
as $$
  select r.id, s.sample_code, d.dispatch_code, d.quantity, d.condition_at_dispatch,
    receipt.receipt_code, receipt.received_quantity, receipt.condition_notes
  from plantlab_lab.requests r
  join plantlab_core.lots l on l.id = r.lot_id
  join plantlab_lab.request_samples rs on rs.request_id = r.id and rs.is_primary
  join plantlab_core.samples s on s.id = rs.sample_id
  join plantlab_plant.sample_dispatches d on d.lab_request_id = r.id and d.sample_id = s.id
  left join plantlab_lab.sample_receipts receipt on receipt.request_sample_id = rs.id
  where r.id = any(p_request_ids[1:50]) and r.source_module = 'PLANT'
    and auth.uid() is not null
    and case upper(btrim(p_module))
      when 'PLANT' then plantlab_platform.has_permission('PLANT', 'request.read', r.request_site_id, l.company_id)
      when 'LAB' then plantlab_platform.has_permission('LAB', 'request.read', r.target_lab_site_id, l.company_id)
      else false end;
$$;

