create function plantlab_lab.lock_germination_preview(p_request_id uuid, p_role text)
returns table (request_state text, item_id uuid, item_state text, test_type_id uuid, sample_id uuid, receipt_id uuid)
language plpgsql set search_path = ''
as $$
begin
  return query
  select r.status, i.id, i.status, i.test_type_id, s.id, receipt.id
  from plantlab_lab.requests r
  join plantlab_core.lots l on l.id = r.lot_id
  join plantlab_master.sites dst on dst.id = r.target_lab_site_id and dst.company_id = l.company_id
    and dst.site_type = 'LAB' and dst.is_active
  join plantlab_lab.request_items i on i.request_id = r.id and i.is_active
  join plantlab_lab.test_types tt on tt.id = i.test_type_id and tt.test_code = 'GERMINATION' and tt.is_active
  join plantlab_lab.request_samples rs on rs.request_id = r.id and rs.is_primary
  join plantlab_core.samples s on s.id = rs.sample_id and s.lot_id = l.id and s.status = 'RECEIVED'
  join plantlab_lab.sample_receipts receipt on receipt.request_sample_id = rs.id and receipt.decision = 'ACCEPT'
  where r.id = p_request_id and r.source_module = 'PLANT'
    and (select count(*) from plantlab_lab.request_items ri where ri.request_id = r.id and ri.is_active) = 1
    and exists (
      select from plantlab_platform.user_role_assignments a
      join plantlab_platform.role_definitions rd on rd.id = a.role_id and rd.is_active and rd.role_code = p_role
      join plantlab_platform.module_registry mr on mr.id = rd.module_id and mr.is_active and mr.module_code = 'LAB'
      where a.user_id = auth.uid() and a.is_active and a.valid_from <= now()
        and (a.valid_until is null or a.valid_until > now())
        and (a.site_id is null or a.site_id = dst.id)
        and (a.company_id is null or a.company_id = dst.company_id)
    )
  for update of r;
  if not found then
    raise exception 'A received single-item Germination request and the assigned Lab role are required' using errcode = '42501';
  end if;
end;
$$;
revoke all on function plantlab_lab.lock_germination_preview(uuid,text) from PUBLIC, anon, authenticated, service_role;

create function plantlab_api.start_germination(p_request_id uuid)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_scope record;
  v_run plantlab_lab.test_runs;
  v_method_id uuid;
  v_cycle plantlab_lab.test_cycles;
  v_assignment_id uuid;
  v_actor uuid := auth.uid();
begin
  select * into v_scope from plantlab_lab.lock_germination_preview(p_request_id, 'LAB_ANALYST');
  select tr.* into v_run from plantlab_lab.test_runs tr
  where tr.request_item_id = v_scope.item_id and tr.sample_id = v_scope.sample_id and tr.attempt_no = 1;
  if found then
    if v_run.performed_by is distinct from v_actor then
      raise exception 'Only the assigned analyst can resume this run' using errcode = '42501';
    end if;
  else
    if v_scope.request_state <> 'RECEIVED' or v_scope.item_state <> 'REQUESTED' then
      raise exception 'The received request is not ready for its first run' using errcode = '55000';
    end if;
    select m.id into v_method_id from plantlab_lab.methods m
    join plantlab_lab.method_test_types mt on mt.method_id = m.id and mt.test_type_id = v_scope.test_type_id
    where m.method_code = 'SAND_25C' and m.is_active and mt.requires_replicate_observations
    order by m.version desc limit 1;
    if not found then
      raise exception 'The active Sand 25 C method is not configured' using errcode = '55000';
    end if;
    select * into v_cycle from plantlab_lab.create_test_cycle(
      p_request_id, v_scope.sample_id, 'INITIAL', null, v_scope.receipt_id, 'GERMINATION',
      null, 'GERMINATION_PREVIEW:' || p_request_id::text
    );
    update plantlab_lab.test_cycles set status = 'ACTIVE', updated_by = v_actor where id = v_cycle.id;
    insert into plantlab_lab.test_assignments (request_item_id, sample_id, analyst_id, method_id, assigned_by)
    values (v_scope.item_id, v_scope.sample_id, v_actor, v_method_id, v_actor)
    returning id into v_assignment_id;
    update plantlab_lab.test_assignments set status = 'ACCEPTED', accepted_at = now() where id = v_assignment_id;
    update plantlab_lab.test_assignments set status = 'IN_PROGRESS' where id = v_assignment_id;
    update plantlab_lab.request_items set status = 'READY', updated_by = v_actor where id = v_scope.item_id;
    insert into plantlab_lab.test_runs (assignment_id, request_item_id, sample_id, method_id, test_cycle_id, created_by)
    values (v_assignment_id, v_scope.item_id, v_scope.sample_id, v_method_id, v_cycle.id, v_actor)
    returning * into v_run;
    select * into v_run from plantlab_lab.advance_test_run(v_run.id, 'IN_PROGRESS');
    perform plantlab_lab.record_test_run_event(v_run.id, 'PLANTED');
  end if;
  return jsonb_build_object('run_code', v_run.test_code, 'status', v_run.status);
end;
$$;

create function plantlab_api.submit_germination(p_request_id uuid, p_replicates jsonb)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_scope record;
  v_run plantlab_lab.test_runs;
  v_row jsonb;
  v_normalized jsonb := '[]';
  v_previous jsonb;
  v_normal integer;
  v_abnormal integer;
  v_dead integer;
  v_total integer;
  v_per_replicate integer;
  v_sum_normal integer := 0;
  v_index integer := 0;
  v_min integer;
  v_max integer;
  v_percent numeric;
  v_gap numeric;
  v_limit numeric;
  v_parameter_id uuid;
  v_summary jsonb;
begin
  select * into v_scope from plantlab_lab.lock_germination_preview(p_request_id, 'LAB_ANALYST');
  select tr.* into v_run from plantlab_lab.test_runs tr join plantlab_lab.methods m on m.id = tr.method_id
  where tr.request_item_id = v_scope.item_id and tr.sample_id = v_scope.sample_id
    and tr.attempt_no = 1 and m.method_code = 'SAND_25C';
  if not found or v_run.performed_by is distinct from auth.uid() then
    raise exception 'Start the run as its assigned analyst first' using errcode = '42501';
  end if;
  if jsonb_typeof(p_replicates) is distinct from 'array' then
    raise exception 'Use two or four final replicate observations' using errcode = '22023';
  end if;
  if jsonb_array_length(p_replicates) not in (2, 4) then
    raise exception 'Use two or four final replicate observations' using errcode = '22023';
  end if;
  for v_row in select value from jsonb_array_elements(p_replicates) loop
    if jsonb_typeof(v_row->'normal') is distinct from 'number'
      or jsonb_typeof(v_row->'abnormal') is distinct from 'number'
      or jsonb_typeof(v_row->'dead') is distinct from 'number'
      or (v_row->>'normal') !~ '^[0-9]{1,4}$'
      or (v_row->>'abnormal') !~ '^[0-9]{1,4}$'
      or (v_row->>'dead') !~ '^[0-9]{1,4}$' then
      raise exception 'Each replicate needs nonnegative integer normal, abnormal, and dead counts' using errcode = '22023';
    end if;
    v_normal := (v_row->>'normal')::integer;
    v_abnormal := (v_row->>'abnormal')::integer;
    v_dead := (v_row->>'dead')::integer;
    v_total := v_normal + v_abnormal + v_dead;
    if v_total = 0 or (v_per_replicate is not null and v_per_replicate <> v_total) then
      raise exception 'All replicate totals must be positive and equal' using errcode = '22023';
    end if;
    v_per_replicate := v_total;
    v_sum_normal := v_sum_normal + v_normal;
    v_min := least(v_min, v_normal);
    v_max := greatest(v_max, v_normal);
    v_index := v_index + 1;
    v_normalized := v_normalized || jsonb_build_array(jsonb_build_object(
      'normal', v_normal, 'abnormal', v_abnormal, 'dead', v_dead));
  end loop;

  select e.metadata into v_previous from plantlab_lab.test_run_events e
  where e.test_run_id = v_run.id and e.event_type = 'OBSERVED_FINAL'
    and e.idempotency_key = 'GERMINATION_FINAL:' || v_run.id::text;
  if found then
    if v_previous->'replicates' is distinct from v_normalized then
      raise exception 'Final observations were already submitted with different counts' using errcode = '23505';
    end if;
    return jsonb_build_object('run_code', v_run.test_code, 'status', v_run.status) || (v_previous - 'replicates');
  end if;
  if v_run.status <> 'IN_PROGRESS' or v_scope.request_state <> 'TESTING' then
    raise exception 'The run must be in progress' using errcode = '55000';
  end if;

  v_percent := round(100.0 * v_sum_normal / (v_per_replicate * v_index), 2);
  v_gap := 100.0 * (v_max - v_min) / v_per_replicate;
  v_limit := plantlab_lab.get_tolerance_limit(v_index, v_percent, v_scope.test_type_id, v_run.method_id);
  v_summary := jsonb_build_object('replicates', v_normalized, 'germination_percent', v_percent,
    'gap_pp', round(v_gap, 2), 'limit_pp', v_limit, 'within_tolerance', v_gap <= v_limit);
  select p.id into strict v_parameter_id from plantlab_lab.parameters p where p.parameter_code = 'GERMINATION_PERCENT';
  v_index := 0;
  for v_row in select value from jsonb_array_elements(v_normalized) loop
    v_index := v_index + 1;
    perform plantlab_lab.save_test_run_observation(v_run.id, 'FINAL', v_index, now(),
      (v_row->>'normal')::integer, (v_row->>'abnormal')::integer, (v_row->>'dead')::integer);
  end loop;
  insert into plantlab_lab.result_values (test_run_id, parameter_id, numeric_value, unit_code, recorded_by)
  values (v_run.id, v_parameter_id, v_percent, 'PERCENT', auth.uid());
  perform plantlab_lab.record_test_run_event(v_run.id, 'OBSERVED_FINAL', now(), null, v_summary,
    'GERMINATION_FINAL:' || v_run.id::text);
  perform plantlab_lab.advance_test_run(v_run.id, 'SUBMITTED');
  perform plantlab_lab.record_test_run_event(v_run.id, 'SUBMITTED');
  select * into v_run from plantlab_lab.advance_test_run(v_run.id, 'IN_REVIEW');
  update plantlab_lab.test_assignments set status = 'COMPLETED' where id = v_run.assignment_id;
  update plantlab_lab.test_cycles set status = 'COMPLETED', updated_by = auth.uid() where id = v_run.test_cycle_id;
  return jsonb_build_object('run_code', v_run.test_code, 'status', v_run.status) || (v_summary - 'replicates');
end;
$$;

create function plantlab_api.review_germination(p_request_id uuid, p_decision text, p_reason text default null)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  v_scope record;
  v_run plantlab_lab.test_runs;
  v_summary jsonb;
  v_decision plantlab_lab.result_decisions;
  v_choice text := upper(btrim(p_decision));
  v_reason text := nullif(btrim(p_reason), '');
begin
  select * into v_scope from plantlab_lab.lock_germination_preview(p_request_id, 'LAB_QA_APPROVER');
  if v_choice is null or v_choice not in ('APPROVE','RETEST')
    or (v_choice = 'RETEST' and v_reason is null) or length(v_reason) > 500 then
    raise exception 'Use APPROVE or RETEST; retest requires a reason of up to 500 characters' using errcode = '22023';
  end if;
  select tr.* into v_run from plantlab_lab.test_runs tr
  where tr.request_item_id = v_scope.item_id and tr.sample_id = v_scope.sample_id and tr.attempt_no = 1;
  if not found or v_run.performed_by is null or v_run.performed_by = auth.uid() then
    raise exception 'An independent QA Approver must review this run' using errcode = '42501';
  end if;
  select d.* into v_decision from plantlab_lab.result_decisions d where d.test_run_id = v_run.id order by d.id desc limit 1;
  if found then
    if v_decision.decision is distinct from v_choice or v_decision.reason is distinct from v_reason
      or v_decision.reviewer_id is distinct from auth.uid() then
      raise exception 'This run already has a decision' using errcode = '23505';
    end if;
  else
    if v_run.status <> 'IN_REVIEW' or v_scope.request_state <> 'IN_REVIEW' then
      raise exception 'The run is not ready for QA review' using errcode = '55000';
    end if;
    select e.metadata into v_summary from plantlab_lab.test_run_events e
    where e.test_run_id = v_run.id and e.idempotency_key = 'GERMINATION_FINAL:' || v_run.id::text;
    if not found then
      raise exception 'Final observations and tolerance snapshot are required' using errcode = '55000';
    end if;
    if v_choice = 'APPROVE' and v_summary->'within_tolerance' is distinct from 'true'::jsonb then
      raise exception 'Approval is blocked when tolerance is exceeded or not configured' using errcode = '23514';
    end if;
    select * into v_decision from plantlab_lab.decide_test_run(v_run.id, v_choice, v_reason);
  end if;
  return jsonb_build_object('run_code', v_run.test_code, 'status', v_decision.resulting_status);
end;
$$;

create function plantlab_api.list_germination_runs(p_request_ids uuid[], p_module text)
returns table (request_id uuid, run_code text, status text, summary jsonb, decision text, decision_reason text)
language sql stable security definer set search_path = ''
as $$
  select r.id, tr.test_code, tr.status, e.metadata, d.decision, d.reason
  from plantlab_lab.requests r
  join plantlab_core.lots l on l.id = r.lot_id
  join plantlab_lab.request_items i on i.request_id = r.id and i.is_active
  join plantlab_lab.test_types tt on tt.id = i.test_type_id and tt.test_code = 'GERMINATION'
  join plantlab_lab.test_runs tr on tr.request_item_id = i.id and tr.attempt_no = 1
  join plantlab_lab.methods m on m.id = tr.method_id and m.method_code = 'SAND_25C'
  join plantlab_lab.request_samples rs on rs.request_id = r.id and rs.sample_id = tr.sample_id and rs.is_primary
  left join plantlab_lab.test_run_events e on e.test_run_id = tr.id and e.idempotency_key = 'GERMINATION_FINAL:' || tr.id::text
  left join lateral (
    select rd.decision, rd.reason from plantlab_lab.result_decisions rd where rd.test_run_id = tr.id order by rd.id desc limit 1
  ) d on true
  where r.id = any(p_request_ids[1:50]) and r.source_module = 'PLANT' and auth.uid() is not null
    and case upper(btrim(p_module))
      when 'LAB' then plantlab_platform.has_permission('LAB', 'result.read', r.target_lab_site_id, l.company_id)
      when 'PLANT' then tr.status = 'APPROVED' and plantlab_platform.has_permission('PLANT', 'result.read', r.request_site_id, l.company_id)
      else false end;
$$;

revoke all on function plantlab_api.start_germination(uuid), plantlab_api.submit_germination(uuid,jsonb),
  plantlab_api.review_germination(uuid,text,text), plantlab_api.list_germination_runs(uuid[],text)
  from PUBLIC, anon, service_role;
grant execute on function plantlab_api.start_germination(uuid), plantlab_api.submit_germination(uuid,jsonb),
  plantlab_api.review_germination(uuid,text,text), plantlab_api.list_germination_runs(uuid[],text)
  to authenticated;

