create function plantlab_integration.register_quality_information_lot_pair(
  p_import_row_id uuid,
  p_dss_lot_id uuid,
  p_dcs_lot_id uuid
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch_id uuid;
  v_payload jsonb;
  v_dss_code text;
  v_dcs_code text;
  v_dss plantlab_core.lots%rowtype;
  v_dcs plantlab_core.lots%rowtype;
  v_issue_code text;
  v_issue_message text;
  v_existing jsonb := '[]'::jsonb;
begin
  select r.batch_id, r.normalized_payload into v_batch_id, v_payload
  from plantlab_integration.import_rows r
  join plantlab_integration.import_batches b on b.id = r.batch_id
  where r.id = p_import_row_id and b.source_type = 'QUALITY_INFORMATION_2026'
    and b.status in ('VALIDATED', 'MAPPING', 'PARTIALLY_MAPPED', 'COMPLETED')
    and r.status in ('VALIDATED', 'MAPPED')
  for share of r, b;
  if not found then
    raise exception 'An eligible Quality Information staging row is required' using errcode = '22023';
  end if;

  v_dss_code := nullif(plantlab_core.normalize_identifier(v_payload->>'lot_dss_code'), '');
  v_dcs_code := nullif(plantlab_core.normalize_identifier(v_payload->>'lot_dcs_code'), '');

  -- Protect the source code comparison until the insert completes.
  perform from plantlab_core.lots l where l.id in (p_dss_lot_id, p_dcs_lot_id)
  order by l.id for share;
  select * into v_dss from plantlab_core.lots where id = p_dss_lot_id;
  select * into v_dcs from plantlab_core.lots where id = p_dcs_lot_id;

  if jsonb_typeof(v_payload->'lot_dss_code') is distinct from 'string'
    or jsonb_typeof(v_payload->'lot_dcs_code') is distinct from 'string'
    or v_dss_code is null or v_dcs_code is null or v_dss_code = v_dcs_code
    or v_dss.id is null or v_dcs.id is null or v_dss.id = v_dcs.id
    or v_dss.stage_code is distinct from 'DSS' or v_dcs.stage_code is distinct from 'DCS'
    or v_dss.company_id <> v_dcs.company_id or v_dss.product_id <> v_dcs.product_id
    or plantlab_core.normalize_identifier(v_dss.lot_code) is distinct from v_dss_code
    or plantlab_core.normalize_identifier(v_dcs.lot_code) is distinct from v_dcs_code then
    v_issue_code := 'DSS_DCS_PAIR_INVALID';
    v_issue_message := 'The Quality Information codes do not match two distinct, resolved DSS/DCS lots of the same company and product.';
  else
    insert into plantlab_core.dss_dcs_pairs (dss_lot_id, dcs_lot_id, company_id, product_id, source_import_row_id)
    values (v_dss.id, v_dcs.id, v_dss.company_id, v_dss.product_id, p_import_row_id)
    on conflict do nothing;
    if found then
      return 'REGISTERED';
    end if;

    if exists (
      select from plantlab_core.dss_dcs_pairs p where p.dss_lot_id = v_dss.id and p.dcs_lot_id = v_dcs.id
    ) then
      return 'ALREADY_REGISTERED';
    end if;

    v_issue_code := 'DSS_DCS_PAIR_CONFLICT';
    v_issue_message := 'A lot or this source row is already bound to a different official pair. No pair was overwritten.';
    select coalesce(jsonb_agg(jsonb_build_object(
      'dss_lot_id', p.dss_lot_id, 'dcs_lot_id', p.dcs_lot_id,
      'source_import_row_id', p.source_import_row_id
    ) order by p.dss_lot_id), '[]'::jsonb) into v_existing
    from plantlab_core.dss_dcs_pairs p
    where p.dss_lot_id = v_dss.id or p.dcs_lot_id = v_dcs.id or p.source_import_row_id = p_import_row_id;
  end if;

  insert into plantlab_integration.import_issues (
    batch_id, import_row_id, severity, issue_code, column_name, source_value, message, metadata
  ) values (
    v_batch_id, p_import_row_id, 'BLOCKING', v_issue_code, 'Lot DSS / Lot DCS',
    jsonb_build_object('lot_dss_code', v_payload->'lot_dss_code', 'lot_dcs_code', v_payload->'lot_dcs_code'),
    v_issue_message,
    jsonb_build_object('proposed_dss_lot_id', p_dss_lot_id, 'proposed_dcs_lot_id', p_dcs_lot_id, 'existing_pairs', v_existing)
  ) on conflict (import_row_id, issue_code)
    where status = 'OPEN' and issue_code in ('DSS_DCS_PAIR_INVALID', 'DSS_DCS_PAIR_CONFLICT')
    do nothing;
  return 'REVIEW_REQUIRED';
end;
$$;

revoke all on function plantlab_integration.register_quality_information_lot_pair(uuid, uuid, uuid)
from PUBLIC, anon, authenticated;
grant execute on function plantlab_integration.register_quality_information_lot_pair(uuid, uuid, uuid) to service_role;

