-- The same transaction lock serializes case intake, verification and pair insertion.
-- General lot_lineage and Lab result ownership are not affected.
create function plantlab_core.block_unreviewed_lot_pair()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(16770601, 7);
  if exists (select from plantlab_core.dss_dcs_pairs p
    where p.dss_lot_id = new.dss_lot_id and p.dcs_lot_id = new.dcs_lot_id) then
    return new; -- The registration function treats this exact replay as a no-op.
  end if;
  if exists (
    select from plantlab_integration.lot_pair_review_cases c
    join plantlab_integration.lot_pair_review_candidates x on x.case_id = c.id
    where c.status in ('PENDING', 'HELD', 'CORRECTION_REQUESTED')
      and (x.dss_lot_id = new.dss_lot_id or x.dcs_lot_id = new.dcs_lot_id)
  ) then
    raise exception 'Pair is held for Plant verification' using errcode = '23514';
  end if;
  return new;
end;
$$;

