create function plantlab_integration.queue_lot_pair_conflict(p_anchor_lot_id uuid, p_candidates jsonb)
returns uuid language plpgsql security definer set search_path = ''
as $$
declare
  a plantlab_core.lots%rowtype;
  c plantlab_integration.lot_pair_review_cases%rowtype;
  x record;
  v_source jsonb;
  v_added integer := 0;
  v_changed boolean := false;
  v_new_case boolean := false;
begin
  if jsonb_typeof(p_candidates) is distinct from 'array' then
    raise exception 'Candidate array required' using errcode = '22023';
  end if;
  if jsonb_array_length(p_candidates) not between 2 and 30 or (
    select count(distinct (dss_lot_id, dcs_lot_id))
    from jsonb_to_recordset(p_candidates) x(dss_lot_id uuid, dcs_lot_id uuid)
  ) < 2 then
    raise exception 'Supply all candidates for a real conflict (2–30 source rows)' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(16770601, 7);
  select * into a from plantlab_core.lots where id = p_anchor_lot_id;
  if not found or a.stage_code is null or a.stage_code not in ('DSS', 'DCS') or not exists (
    select from plantlab_master.sites s where s.id = a.plant_site_id and s.company_id = a.company_id
      and s.site_type = 'PLANT' and s.is_active
  ) then
    raise exception 'Conflict anchor must be a DSS/DCS lot at a valid Plant site' using errcode = '22023';
  end if;

  select * into c from plantlab_integration.lot_pair_review_cases where anchor_lot_id = a.id for update;
  if not found then
    insert into plantlab_integration.lot_pair_review_cases(anchor_lot_id, anchor_stage, site_id, company_id)
    values (a.id, a.stage_code, a.plant_site_id, a.company_id) returning * into c;
    v_new_case := true;
  elsif (c.anchor_stage, c.site_id, c.company_id) is distinct from (a.stage_code, a.plant_site_id, a.company_id) then
    raise exception 'Anchor scope changed; resolve the source mapping first' using errcode = '22023';
  end if;

  for x in select * from jsonb_to_recordset(p_candidates) as t(dss_lot_id uuid, dcs_lot_id uuid, import_row_id uuid) loop
    if (a.stage_code = 'DSS' and x.dss_lot_id is distinct from a.id)
      or (a.stage_code = 'DCS' and x.dcs_lot_id is distinct from a.id) then
      raise exception 'All candidates must share the conflict anchor' using errcode = '22023';
    end if;
    select jsonb_build_object('dss_code', d.lot_code, 'dcs_code', k.lot_code,
      'hybrid', p.name, 'file', b.source_file_name, 'sheet', r.sheet_name, 'row', r.source_row_number,
      'has_formula', coalesce(r.raw_payload->'formula_cells', '{}'::jsonb) <> '{}'::jsonb)
    into v_source from plantlab_integration.import_rows r
    join plantlab_integration.import_batches b on b.id = r.batch_id
    join plantlab_core.lots d on d.id = x.dss_lot_id and d.stage_code = 'DSS'
    join plantlab_core.lots k on k.id = x.dcs_lot_id and k.stage_code = 'DCS'
    join plantlab_master.products p on p.id = d.product_id
    where r.id = x.import_row_id and b.source_type = 'QUALITY_INFORMATION_2026'
      and b.status in ('VALIDATED', 'MAPPING', 'PARTIALLY_MAPPED', 'COMPLETED') and r.status in ('VALIDATED', 'MAPPED')
      and d.company_id = a.company_id and k.company_id = a.company_id
      and d.plant_site_id = a.plant_site_id and k.plant_site_id = a.plant_site_id and d.product_id = k.product_id
      and plantlab_core.normalize_identifier(d.lot_code) <> plantlab_core.normalize_identifier(k.lot_code)
      and plantlab_core.normalize_identifier(d.lot_code) = plantlab_core.normalize_identifier(r.normalized_payload->>'lot_dss_code')
      and plantlab_core.normalize_identifier(k.lot_code) = plantlab_core.normalize_identifier(r.normalized_payload->>'lot_dcs_code');
    if not found then
      raise exception 'Candidate evidence is not a validated, same-site Quality Information pair' using errcode = '22023';
    end if;

    if exists (select from plantlab_integration.lot_pair_review_candidates old where old.case_id = c.id
      and old.source_import_row_id = x.import_row_id
      and (old.dss_lot_id, old.dcs_lot_id, old.source_snapshot) is distinct from (x.dss_lot_id, x.dcs_lot_id, v_source)) then
      raise exception 'Previously recorded evidence changed; submit a new source revision' using errcode = '23514';
    end if;
    v_changed := v_changed or not exists (select from plantlab_integration.lot_pair_review_candidates old where old.case_id = c.id
      and (old.dss_lot_id, old.dcs_lot_id) = (x.dss_lot_id, x.dcs_lot_id));
    insert into plantlab_integration.lot_pair_review_candidates(case_id, dss_lot_id, dcs_lot_id, source_import_row_id, source_snapshot)
    values (c.id, x.dss_lot_id, x.dcs_lot_id, x.import_row_id, v_source)
    on conflict (case_id, source_import_row_id) do nothing;
    if found then v_added := v_added + 1; end if;
  end loop;
  if not v_new_case and v_added > 0 then
    update plantlab_integration.lot_pair_review_cases set revision = revision + 1,
      status = case when v_changed then 'PENDING' else status end, updated_at = clock_timestamp() where id = c.id;
  end if;
  return c.id;
end;
$$;

-- Run on the full resolved candidate set before publishing any pair. Includes
-- existing official evidence, so even one incoming conflicting row is queued.
create function plantlab_integration.preflight_lot_pair_conflicts(p_candidates jsonb)
returns table(anchor_lot_id uuid, case_id uuid)
language plpgsql security definer set search_path = ''
as $$
declare
  v_group record;
begin
  if jsonb_typeof(p_candidates) is distinct from 'array' then
    raise exception 'Candidate array required' using errcode = '22023';
  end if;
  if jsonb_array_length(p_candidates) > 5000 or exists (
    select from jsonb_to_recordset(p_candidates) x(dss_lot_id uuid, dcs_lot_id uuid, import_row_id uuid)
    where x.dss_lot_id is null or x.dcs_lot_id is null or x.import_row_id is null
  ) then
    raise exception 'Preflight accepts up to 5000 resolved candidate rows' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(16770601, 7);
  for v_group in
    with incoming as (
      select * from jsonb_to_recordset(p_candidates) x(dss_lot_id uuid, dcs_lot_id uuid, import_row_id uuid)
    ), evidence as (
      select * from incoming
      union
      select p.dss_lot_id, p.dcs_lot_id, p.source_import_row_id
      from plantlab_core.dss_dcs_pairs p
      where exists (select from incoming i where
        (i.dss_lot_id = p.dss_lot_id or i.dcs_lot_id = p.dcs_lot_id)
        and (i.dss_lot_id, i.dcs_lot_id) is distinct from (p.dss_lot_id, p.dcs_lot_id))
    ), groups as (
      select e.dcs_lot_id as anchor, jsonb_agg(to_jsonb(e) order by e.import_row_id) as candidates
      from evidence e group by e.dcs_lot_id having count(distinct e.dss_lot_id) > 1
      union all
      select e.dss_lot_id, jsonb_agg(to_jsonb(e) order by e.import_row_id)
      from evidence e group by e.dss_lot_id having count(distinct e.dcs_lot_id) > 1
    )
    select * from groups order by anchor
  loop
    anchor_lot_id := v_group.anchor;
    case_id := plantlab_integration.queue_lot_pair_conflict(v_group.anchor, v_group.candidates);
    return next;
  end loop;
end;
$$;

create function plantlab_api.list_lot_pair_reviews(p_offset integer default 0)
returns table(case_id uuid, anchor_stage text, anchor_code text, site_name text, status text, revision integer,
  official_pair jsonb, candidates jsonb, last_decision jsonb)
language sql stable security definer set search_path = ''
as $$
  select c.id, c.anchor_stage, a.lot_code, s.site_name, c.status, c.revision,
    case when official.dss_lot_id is null then null else jsonb_build_object(
      'dss_code', od.lot_code, 'dcs_code', ok.lot_code) end,
    (select coalesce(jsonb_agg(x.source_snapshot || jsonb_build_object('id', x.id)
      order by x.source_snapshot->>'file', x.source_snapshot->>'sheet', (x.source_snapshot->>'row')::int, x.id), '[]')
      from plantlab_integration.lot_pair_review_candidates x where x.case_id = c.id),
    (select jsonb_build_object('decision', d.decision, 'reason', d.reason, 'evidence', d.evidence, 'decided_at', d.decided_at)
      from plantlab_integration.lot_pair_review_decisions d where d.case_id = c.id order by d.decided_at desc, d.id limit 1)
  from plantlab_integration.lot_pair_review_cases c
  join plantlab_core.lots a on a.id = c.anchor_lot_id and a.plant_site_id = c.site_id and a.company_id = c.company_id
  join plantlab_master.sites s on s.id = c.site_id
  left join plantlab_core.dss_dcs_pairs official on (official.dss_lot_id = a.id or official.dcs_lot_id = a.id)
  left join plantlab_core.lots od on od.id = official.dss_lot_id and od.plant_site_id = c.site_id and od.company_id = c.company_id
  left join plantlab_core.lots ok on ok.id = official.dcs_lot_id and ok.plant_site_id = c.site_id and ok.company_id = c.company_id
  where plantlab_platform.can_review_lot_pair(c.site_id, c.company_id)
  order by (c.status in ('APPROVED', 'KEPT_OFFICIAL')), c.updated_at desc, c.id
  limit 21 offset greatest(0, coalesce(p_offset, 0));
$$;

create function plantlab_api.decide_lot_pair_review(p_case_id uuid, p_revision integer, p_action_id uuid,
  p_decision text, p_candidate_id uuid, p_reason text, p_evidence text)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare
  c plantlab_integration.lot_pair_review_cases%rowtype;
  x plantlab_integration.lot_pair_review_candidates%rowtype;
  old plantlab_integration.lot_pair_review_decisions%rowtype;
  v_user uuid := auth.uid();
  v_reason text := nullif(btrim(p_reason), '');
  v_evidence text := nullif(btrim(p_evidence), '');
  v_status text;
  v_result text;
  v_has_official boolean;
begin
  perform pg_advisory_xact_lock(16770601, 7);
  select * into c from plantlab_integration.lot_pair_review_cases where id = p_case_id for update;
  if not found or not plantlab_platform.can_review_lot_pair(c.site_id, c.company_id) then
    raise exception 'Only the assigned Plant SPV can verify this case' using errcode = '42501';
  end if;
  if p_action_id is null or p_revision is null or p_decision is null
    or p_decision not in ('APPROVE', 'HOLD', 'REQUEST_CORRECTION', 'KEEP_OFFICIAL')
    or (p_decision = 'APPROVE') <> (p_candidate_id is not null)
    or v_reason is null or char_length(v_reason) > 500 or v_evidence is null or char_length(v_evidence) > 500 then
    raise exception 'A valid decision, reason and evidence are required' using errcode = '22023';
  end if;

  select * into old from plantlab_integration.lot_pair_review_decisions where id = p_action_id;
  if found then
    if (old.case_id, old.case_revision, old.actor_id, old.decision, old.candidate_id, old.reason, old.evidence)
      is distinct from (p_case_id, p_revision, v_user, p_decision, p_candidate_id, v_reason, v_evidence) then
      raise exception 'Decision action ID already used' using errcode = '23505';
    end if;
    return jsonb_build_object('status', old.result_status, 'revision', old.case_revision + 1);
  end if;
  if c.revision <> p_revision or c.status in ('APPROVED', 'KEPT_OFFICIAL') then
    raise exception 'Case changed; reload before verifying' using errcode = '55000';
  end if;
  if not exists (select from plantlab_core.lots a where a.id = c.anchor_lot_id and a.stage_code = c.anchor_stage
    and a.plant_site_id = c.site_id and a.company_id = c.company_id) then
    raise exception 'Anchor lot scope changed' using errcode = '55000';
  end if;

  select exists (select from plantlab_core.dss_dcs_pairs o where o.dss_lot_id = c.anchor_lot_id or o.dcs_lot_id = c.anchor_lot_id)
  into v_has_official;
  v_status := case p_decision when 'APPROVE' then 'APPROVED' when 'HOLD' then 'HELD'
    when 'KEEP_OFFICIAL' then 'KEPT_OFFICIAL' else 'CORRECTION_REQUESTED' end;
  if p_decision = 'KEEP_OFFICIAL' and not exists (
    select from plantlab_core.dss_dcs_pairs o
    join plantlab_core.lots d on d.id = o.dss_lot_id and d.plant_site_id = c.site_id and d.company_id = c.company_id
    join plantlab_core.lots k on k.id = o.dcs_lot_id and k.plant_site_id = c.site_id and k.company_id = c.company_id
    where o.dss_lot_id = c.anchor_lot_id or o.dcs_lot_id = c.anchor_lot_id
  ) then
    raise exception 'There is no official pair in this site scope to keep' using errcode = '55000';
  end if;
  if p_decision = 'APPROVE' then
    select * into x from plantlab_integration.lot_pair_review_candidates where id = p_candidate_id and case_id = c.id;
    if not found or v_has_official or exists (select from plantlab_core.dss_dcs_pairs o
      where o.dss_lot_id = x.dss_lot_id or o.dcs_lot_id = x.dcs_lot_id) then
      raise exception 'Candidate is invalid or already has an official partner' using errcode = '55000';
    end if;
    perform from plantlab_core.lots l where l.id in (x.dss_lot_id, x.dcs_lot_id) order by l.id for share;
    if (select count(*) from plantlab_core.lots l where l.id in (x.dss_lot_id, x.dcs_lot_id)
      and l.plant_site_id = c.site_id and l.company_id = c.company_id
      and l.lot_code = case when l.id = x.dss_lot_id then x.source_snapshot->>'dss_code' else x.source_snapshot->>'dcs_code' end) <> 2 then
      raise exception 'Candidate codes or scope changed' using errcode = '55000';
    end if;
  end if;

  update plantlab_integration.lot_pair_review_cases set status = v_status, revision = revision + 1,
    updated_at = clock_timestamp() where id = c.id;
  if p_decision = 'APPROVE' then
    v_result := plantlab_integration.register_quality_information_lot_pair(x.source_import_row_id, x.dss_lot_id, x.dcs_lot_id);
    if v_result is distinct from 'REGISTERED' then
      raise exception 'The selected pair could not be registered; case remains open' using errcode = '55000';
    end if;
  end if;
  insert into plantlab_integration.lot_pair_review_decisions (id, case_id, candidate_id, actor_id, case_revision, decision, reason, evidence, result_status)
  values (p_action_id, c.id, p_candidate_id, v_user, c.revision, p_decision, v_reason, v_evidence, v_status);
  return jsonb_build_object('status', v_status, 'revision', c.revision + 1);
end;
$$;

revoke all on function plantlab_platform.can_review_lot_pair(uuid,bigint), plantlab_core.block_unreviewed_lot_pair(),
  plantlab_integration.queue_lot_pair_conflict(uuid,jsonb), plantlab_integration.preflight_lot_pair_conflicts(jsonb),
  plantlab_api.list_lot_pair_reviews(integer),
  plantlab_api.decide_lot_pair_review(uuid,integer,uuid,text,uuid,text,text) from PUBLIC, anon, authenticated, service_role;
grant execute on function plantlab_integration.preflight_lot_pair_conflicts(jsonb) to service_role;
grant execute on function plantlab_api.list_lot_pair_reviews(integer),
  plantlab_api.decide_lot_pair_review(uuid,integer,uuid,text,uuid,text,text) to authenticated;


-- Only the selected RPC namespace may be exposed later. Revoke implicit access
-- from non-application roles, without altering grants in existing schemas.
revoke all on schema plantlab_platform, plantlab_master, plantlab_core, plantlab_plant, plantlab_lab, plantlab_audit, plantlab_integration, plantlab_reporting, plantlab_api from PUBLIC, anon;
revoke all on all functions in schema plantlab_api from PUBLIC, anon, service_role;
revoke all on plantlab_platform.identities from PUBLIC, anon, authenticated, service_role;
grant select, insert on plantlab_platform.identities to service_role;

do $$
begin
  if (select count(*) from pg_namespace where nspname = any(array['plantlab_platform', 'plantlab_master', 'plantlab_core', 'plantlab_plant', 'plantlab_lab', 'plantlab_audit', 'plantlab_integration', 'plantlab_reporting', 'plantlab_api'])) <> 9
    or (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'plantlab_api') <> 16 then
    raise exception 'Incomplete isolated Plant/Lab schema or API surface';
  end if;
  if exists (
    select from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = any(array['plantlab_platform', 'plantlab_master', 'plantlab_core', 'plantlab_plant', 'plantlab_lab', 'plantlab_audit', 'plantlab_integration', 'plantlab_reporting', 'plantlab_api']) and c.relkind in ('r', 'p') and not c.relrowsecurity
  ) then
    raise exception 'An isolated Plant/Lab table is missing row level security';
  end if;
  if exists (
    select from pg_constraint c
    join pg_class src on src.oid = c.conrelid join pg_namespace sn on sn.oid = src.relnamespace
    join pg_class dst on dst.oid = c.confrelid join pg_namespace dn on dn.oid = dst.relnamespace
    where c.contype = 'f' and sn.nspname = any(array['plantlab_platform', 'plantlab_master', 'plantlab_core', 'plantlab_plant', 'plantlab_lab', 'plantlab_audit', 'plantlab_integration', 'plantlab_reporting', 'plantlab_api'])
      and not dn.nspname = any(array['plantlab_platform', 'plantlab_master', 'plantlab_core', 'plantlab_plant', 'plantlab_lab', 'plantlab_audit', 'plantlab_integration', 'plantlab_reporting', 'plantlab_api'])
  ) or exists (
    select from pg_rewrite r join pg_class v on v.oid = r.ev_class join pg_namespace vn on vn.oid = v.relnamespace
    join pg_depend d on d.classid = 'pg_rewrite'::regclass and d.objid = r.oid and d.refclassid = 'pg_class'::regclass
    join pg_class src on src.oid = d.refobjid join pg_namespace sn on sn.oid = src.relnamespace
    where vn.nspname = any(array['plantlab_platform', 'plantlab_master', 'plantlab_core', 'plantlab_plant', 'plantlab_lab', 'plantlab_audit', 'plantlab_integration', 'plantlab_reporting', 'plantlab_api']) and not sn.nspname = any(array['plantlab_platform', 'plantlab_master', 'plantlab_core', 'plantlab_plant', 'plantlab_lab', 'plantlab_audit', 'plantlab_integration', 'plantlab_reporting', 'plantlab_api'])
  ) then
    raise exception 'Unexpected cross-namespace Plant/Lab dependency';
  end if;
  if exists (select from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'plantlab_api' and has_function_privilege('anon', p.oid, 'EXECUTE')) then
    raise exception 'Anonymous API execution is not allowed';
  end if;
  if exists (select from plantlab_platform.module_registry m where m.is_active and m.module_code not in ('PLATFORM','PLANT','LAB')) then
    raise exception 'An external module is active in the isolated environment';
  end if;
end;
$$;


commit;
